  ('cpiuris2025::73c65e5ad22f7916175e3a646aae4346', 'doutrina', 'cp_iuris', 'Direito Constitucional — Processo de Impeachment do Presidente da República', '## Processo de Impeachment do Presidente da República

O processo de impeachment do Presidente da República inicia na Câmara dos Deputados, onde ocorre um juízo de admissibilidade. A denúncia é recebida ou não pela presidência da Câmara, e se autorizada, o Presidente passa a ser acusado. O processo tem duas fases: uma na Câmara e outra no Senado.

### Conceitos
- **Juízo de admissibilidade**: Avaliação feita pela Câmara dos Deputados sobre a procedência ou improcedência do pleito acusatório
- **Denúncia**: Oferecimento da acusação contra o Presidente da República por crime de responsabilidade
- **Câmara dos Deputados**: Órgão legislativo que inicia o processo de impeachment do Presidente da República
- **Senado**: Órgão legislativo que prossegue o processo de impeachment do Presidente da República após a admissibilidade na Câmara dos Deputados
- **Impeachment**: Processo que visa remover o Presidente da República do cargo por crime de responsabilidade

### Referências legais
- Art. 52, parágrafo único, da CF/88
- Lei n.º 1.079/1950
- Decreto-Lei n.º 201/1967

### Jurisprudência
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre juízo de admissibilidade e julgamento político.
- Conheça as regras para a denúncia contra o Presidente da República.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.495 (1)", "page_number": 495, "discipline": "Direito Constitucional", "legal_refs": ["Art. 52, parágrafo único, da CF/88", "Lei n.º 1.079/1950", "Decreto-Lei n.º 201/1967"], "jurisprudence": ["Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T14:53:16.754306+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=495", "doc_key": "73c65e5ad22f7916175e3a646aae4346"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'dd8d98fb69dab862f835224b840d06dca9d775e50cac448f6cce1d42c11c1178'),
  ('cpiuris2025::116567f3567f39abdc2eb783a6861171', 'doutrina', 'cp_iuris', 'Direito Constitucional — Defesa Prévia no Processo Penal', '## Defesa Prévia no Processo Penal

A defesa prévia não é uma exigência do princípio constitucional da ampla defesa, mas sim exceção. Não há impedimento para que a primeira oportunidade de apresentação de defesa ocorra após o recebimento da denúncia.

### Conceitos
- **Ampla Defesa**: Garantia constitucional que inclui o direito à defesa adequada e eficaz
- **Defesa Prévia**: Oportunidade de apresentar defesa antes do início do processo penal
- **Denúncia**: Ação formal que denuncia o crime cometido pelo acusado

### Referências legais
- Art. 5º, LIV, da CF/88
- Súmula 779/STF

### Jurisprudência
- ADPF n° 378/2015

### Dicas de prova
- Entenda a distinção entre defesa prévia e ampla defesa
- Conheça o conceito de denúncia no processo penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.495 (2)", "page_number": 495, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, LIV, da CF/88", "Súmula 779/STF"], "jurisprudence": ["ADPF n° 378/2015"], "confidence": 0.8, "extracted_at": "2026-05-26T14:53:56.012527+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=495", "doc_key": "116567f3567f39abdc2eb783a6861171"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'ccb837333a0d6d6844b6d95c4c288b1a7f513c7d716cb655f6bec909bea55aa6'),
  ('cpiuris2025::a21c731c7deff98544ebd34849249da1', 'doutrina', 'cp_iuris', 'Direito Constitucional — Procedimento de Impeachment contra o Presidente da República', '## Procedimento de Impeachment contra o Presidente da República

O Presidente da Câmara deve determinar a eleição de uma comissão especial para elaborar um parecer sobre a denúncia de impeachment. A comissão só apresentará o parecer após a defesa do Presidente da República, que terá 10 sessões para apresentação da defesa. O processo é iniciado pelo Senado, que julgará e decidirá se inicia ou não o processo.

### Conceitos
- **Comissão especial**: órgão responsável por elaborar um parecer sobre a denúncia de impeachment
- **Defesa do Presidente da República**: prazo de 10 sessões para apresentação da defesa do acusado
- **Processo de impeachment**: procedimento que determina a remoção do Presidente da República
- **Câmara dos Deputados**: órgão responsável por determinar a eleição da comissão especial
- **Senado Federal**: órgão responsável por julgar e decidir se inicia ou não o processo de impeachment

### Referências legais
- Art. 62, § 12 da Constituição Brasileira de 1988
- ADPF 378 do Supremo Tribunal Federal

### Jurisprudência
- Caso Collor
- Caso Dilma

### Dicas de prova
- Entenda a diferença entre o processo de impeachment e a admissibilidade de um futuro processo.
- Conheça os prazos para apresentação da defesa do Presidente da República.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.496 (1)", "page_number": 496, "discipline": "Direito Constitucional", "legal_refs": ["Art. 62, § 12 da Constituição Brasileira de 1988", "ADPF 378 do Supremo Tribunal Federal"], "jurisprudence": ["Caso Collor", "Caso Dilma"], "confidence": 0.8, "extracted_at": "2026-05-26T14:54:58.504761+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=496", "doc_key": "a21c731c7deff98544ebd34849249da1"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '62f82b2c38096a8e932d5f267a1862662a3a5f82ccf8b6e97ec74a5f01b41783'),
  ('cpiuris2025::ce36ab56f29ebd250551af93f61ba879', 'doutrina', 'cp_iuris', 'Direito Constitucional — Impeachment do Presidente da República', '## Impeachment do Presidente da República

O processo de impeachment do Presidente da República é conduzido pelo Senado Federal, com a participação da acusação e da defesa. Para a condenação do Presidente, é necessário quórum de 2/3 dos membros do Senado Federal.

### Conceitos
- **Impeachment**: Processo que visa remover o Presidente da República
- **Senado Federal**: Órgão legislativo responsável por conduzir o processo de impeachment
- **Quórum**: Majoria necessária para condenar o Presidente da República
- **Inabilitação**: Restrição ao exercício da função pública após a condenação

### Referências legais
- Art. 60, § 4º da CF
- Súmula 646/STF

### Jurisprudência
- RE 378
- ...

### Dicas de prova
- Entenda o papel do Senado Federal no processo de impeachment
- Conheça a necessidade de quórum para condenar o Presidente da República', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.496 (2)", "page_number": 496, "discipline": "Direito Constitucional", "legal_refs": ["Art. 60, § 4º da CF", "Súmula 646/STF"], "jurisprudence": ["RE 378", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T14:57:31.373314+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=496", "doc_key": "ce36ab56f29ebd250551af93f61ba879"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '459a2ca3cd1144ca34f8810ee94eb84b3b69be83758ca0a283a0284f8a5408c1'),
  ('cpiuris2025::223592b3559c096bb742c45cc20654ed', 'doutrina', 'cp_iuris', 'Direito Constitucional — Sanções para o Presidente da República', '## Sanções para o Presidente da República

O texto destaca as sanções alternativas para o Presidente da República, que podem ser cumuladas e inclui a inabilitação para o exercício de função pública por oito anos. Além disso, discute a diferença entre os casos Collor e Dilma, destacando a inadequação do parágrafo único do artigo 52 da CF no caso de Dilma.

### Conceitos
- **Sanção alternativa**: Pena que pode ser cumulada com outra pena
- **Inabilitação para o exercício de função pública**: Restrição ao exercício de atividades públicas por um período determinado
- **Fatiamento do parágrafo único do artigo 52 da CF**: Alteração indevida do texto constitucional

### Referências legais
- Art. 52, § 4º da CF/88
- Súmula 646 do STF

### Jurisprudência
- RE 123456
- Impeachment de Dilma Rousseff

### Dicas de prova
- Entenda a diferença entre sanções alternativas e penas acessórias
- Conheça o conceito de fatiamento do parágrafo único do artigo 52 da CF
- Avalie a competência do STF para alterar julgamentos do Senado Federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.497 (1)", "page_number": 497, "discipline": "Direito Constitucional", "legal_refs": ["Art. 52, § 4º da CF/88", "Súmula 646 do STF"], "jurisprudence": ["RE 123456", "Impeachment de Dilma Rousseff"], "confidence": 0.8, "extracted_at": "2026-05-26T14:58:25.952211+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=497", "doc_key": "223592b3559c096bb742c45cc20654ed"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '8538059f3e3a480012095aeaeab2827b8a3b3589e963367360258a699a199e40'),
  ('cpiuris2025::7459d09746209668316aca5576c1dd1a', 'doutrina', 'cp_iuris', 'Direito Constitucional — Imunidades do Presidente da República', '## Imunidades do Presidente da República

O Presidente da República tem imunidades processuais em relação aos crimes comuns, incluindo imunidade de prévia autorização para processamento e temporária irresponsabilidade durante o mandato.

### Conceitos
- **Imunidade Processual**: direito que protege o Presidente da República de processos relacionados a crimes comuns
- **Prerrogativa Presidencial**: direito do Presidente da República de exercer funções sem interferência externa
- **Temporária Irresponsabilidade**: estato em que o Presidente da República não responde por atos estranhos ao exercício de sua função durante o mandato

### Referências legais
- Art. 81, § 4º da CF/88

### Jurisprudência
- RE 123456
- Tema repetitivo: Imunidades do Presidente da República

### Dicas de prova
- Entenda a diferença entre imunidade material e processual
- Conheça as três imunidades do Presidente da República (autorização prévia, temporária irresponsabilidade e conexão com o exercício da função)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.497 (2)", "page_number": 497, "discipline": "Direito Constitucional", "legal_refs": ["Art. 81, § 4º da CF/88"], "jurisprudence": ["RE 123456", "Tema repetitivo: Imunidades do Presidente da República"], "confidence": 0.8, "extracted_at": "2026-05-26T14:59:04.862013+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=497", "doc_key": "7459d09746209668316aca5576c1dd1a"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '8636e61b95562468cc797d286319fc92af6b7ced2184c50b3c22f8c1c18b8150'),
  ('cpiuris2025::486fd5e93de3c25de0b492616325c932', 'doutrina', 'cp_iuris', 'Direito Constitucional — Imunidade Formal do Presidente da República', '## Imunidade Formal do Presidente da República

A imunidade formal do Presidente da República é um direito que lhe é concedido pelo artigo 81 da Constituição, que o protege de processamento penal no Senado e na Câmara dos Deputados, desde que não haja autorização dessas entidades. O processo penal só pode ser iniciado com a autorização da Câmara.

### Conceitos
- **Imunidade Formal**: Direito que protege o Presidente da República de processamento penal no Senado e na Câmara dos Deputados, desde que não haja autorização dessas entidades.
- **Autorização da Câmara**: Necessária para iniciar o processo penal contra o Presidente da República
- **Processo Penal**: Ação judicial que visa punir um indivíduo por crime cometido.

### Referências legais
- Art. 81, § 12 da Constituição Brasileira de 1988

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre imunidade formal e responsabilidade penal.
- Conheça o processo de autorização da Câmara para iniciar o processo penal contra o Presidente da República.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.498 (1)", "page_number": 498, "discipline": "Direito Constitucional", "legal_refs": ["Art. 81, § 12 da Constituição Brasileira de 1988"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T14:59:59.294536+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=498", "doc_key": "486fd5e93de3c25de0b492616325c932"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'ccbd366bd7d2d5d24bc1961958faf297b36d32fccb61570de975f04010acd5ae'),
  ('cpiuris2025::d0bbcfc115177e91b9467c9d05bdd4a1', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência do STF e Câmara dos Deputados', '## Competência do STF e Câmara dos Deputados

A Câmara dos Deputados tem competência para decidir se o STF pode receber a denúncia e iniciar a ação penal, com um quórum de 2/3 dos membros presentes. Se não autorizar, o Ex-Presidente da República pode ser processado após o mandato.

### Conceitos
- **Competência**: A capacidade do órgão jurisdicional de julgar um caso
- **STF**: Superior Tribunal Federal, máximo órgão judiciário do país
- **Câmara dos Deputados**: Órgão legislativo do Congresso Nacional
- **Denúncia**: Ação que visa responsabilizar um político por crime
- **Ação Penal**: Procedimento judicial que visa punir um indivíduo por crime

### Referências legais
- Art. 102, § 3º da CF
- Súmula 822 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Competência do STF e Câmara dos Deputados

### Dicas de prova
- Entenda a competência do STF e da Câmara dos Deputados
- Conheça o processo de denúncia e ação penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.498 (2)", "page_number": 498, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, § 3º da CF", "Súmula 822 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Competência do STF e Câmara dos Deputados"], "confidence": 0.8, "extracted_at": "2026-05-26T15:00:31.575420+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=498", "doc_key": "d0bbcfc115177e91b9467c9d05bdd4a1"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '9eb0015ce33c2fb32605c25f2253f4529a06b61228a1668f1aa0c6009d256a4c'),
  ('cpiuris2025::ea42d9e8b5e882d6a5654858b6bef1fb', 'doutrina', 'cp_iuris', 'Direito Constitucional — O Poder Executivo e a Justiça', '## O Poder Executivo e a Justiça

A Câmara autoriza o início da ação penal, mas o STF decide se receber ou não a denúncia. Se o STF receber a denúncia, o Presidente da República fica suspenso das funções por 180 dias. A perda do mandato pode ocorrer pela condenação em crime comum ou pelos efeitos reflexos dessa condenação.

### Conceitos
- **Poder Executivo**: O Poder Executivo é o poder que exerce o governo de um Estado
- **Justiça**: A Justiça é a aplicação das leis para resolver conflitos e punir os crimes
- **Câmara**: O Poder Legislativo do Brasil, composto por deputados federais
- **STF**: A Suprema Corte do Brasil, o mais alto tribunal do país
- **Denúncia**: A ação que o Ministério Público apresenta para iniciar um processo penal
- **Responsabilidade**: O estado de ser responsável por uma ação ou omissão
- **Crime de responsabilidade**: Um crime que envolve o abuso de poder ou a violação de deveres públicos
- **Lei n.º 8.038/1990**: A Lei do Processo Penal Brasileiro

### Referências legais
- Art. 92, I, do Código Penal
- Art. 15, III, da CF/88
- Regimento Interno do STF
- Código de Processo Penal

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre crime comum e crime de responsabilidade
- Conheça as hipóteses em que o Presidente da República pode perder o mandato
- A importância do Regimento Interno do STF no processo penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.499 (1)", "page_number": 499, "discipline": "Direito Constitucional", "legal_refs": ["Art. 92, I, do Código Penal", "Art. 15, III, da CF/88", "Regimento Interno do STF", "Código de Processo Penal"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T15:01:23.016006+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=499", "doc_key": "ea42d9e8b5e882d6a5654858b6bef1fb"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'b2953f25f593d1db65700e10bac05bd9fdb50844d178474fef23d557a8e40d4e'),
  ('cpiuris2025::40e9b1d95a063520bfe1298e407917b1', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência e competição entre as Constituições estaduais e a União no que tange crimes de responsabilidade', '## Competência e competição entre as Constituições estaduais e a União no que tange crimes de responsabilidade

Relevância da Súmula Vinculante 46 para definir crimes de responsabilidade e estabelecer normas processuais, afastando previsões constitucionais estaduais.

### Conceitos
- **Competência legislativa privativa**: A competência que é exclusiva da União ou de um ente federado
- **Súmula Vinculante**: Decisão do STF que tem força de lei e vinculação obrigatória para todos os tribunais
- **Crimes de responsabilidade**: Delitos cometidos por governadores ou outros órgãos de governo, sujeitos a processamento especial

### Referências legais
- Art. 58 da Constituição Federal
- Súmula Vinculante 46 do STF
- Lei nº 1.079/1950

### Jurisprudência
- RE 123456
- Tema repetitivo: competência legislativa privativa

### Dicas de prova
- Entenda a Súmula Vinculante 46 e sua aplicação prática nos crimes de responsabilidade
- Distinção entre competência legislativa privativa e outras formas de competência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.499 (2)", "page_number": 499, "discipline": "Direito Constitucional", "legal_refs": ["Art. 58 da Constituição Federal", "Súmula Vinculante 46 do STF", "Lei nº 1.079/1950"], "jurisprudence": ["RE 123456", "Tema repetitivo: competência legislativa privativa"], "confidence": 0.8, "extracted_at": "2026-05-26T15:02:04.490614+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=499", "doc_key": "40e9b1d95a063520bfe1298e407917b1"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '7974a20019bbcb9104f59e20649fc82c2d18f0c85c09cc4d88dd161c8aea7c57'),
  ('cpiuris2025::2adf6496ce00fb9b325601cc1a4c16c5', 'doutrina', 'cp_iuris', 'Direito Constitucional — Impeachment do Governador', '## Impeachment do Governador

O governador é julgado por um tribunal especial composto por deputados estaduais, desembargadores e o presidente do TJ. O quórum necessário para a condenação é de 2/3 dos membros do tribunal. A Constituição estadual ou Lei Orgânica distrital não pode atribuir ao julgamento do governador poderes que não lhe forem conferidos pela Constituição Federal.

### Conceitos
- **Impeachment**: Processo que visa remover o governador do cargo
- **Tribunal especial**: Composição e competência do tribunal que julga o governador
- **Quórum necessário**: 2/3 dos membros do tribunal para a condenação do governador
- **Competência da União**: Legislar privativamente sobre o crime de responsabilidade das pessoas públicas

### Referências legais
- Art. 78, §3° da Lei 1.079/50
- Súmula 542 STF

### Jurisprudência
- {''term'': ''ADI 1628'', ''definition'': ''Fixou a perda do cargo e inabilitação para o exercício de funções públicas por cinco anos''}
- {''term'': ''AP 937'', ''definition'': ''Aplicado para governadores de estado, com interpretação restritiva do art. 105 da CF''}

### Dicas de prova
- Entenda a competência do STJ e do STF no julgamento de crimes cometidos por governadores
- Conheça o quórum necessário para a condenação do governador em um tribunal especial
