  ('cpiuris2025::e67b980d6dc402f050fb66721d6fadb2', 'doutrina', 'cp_iuris', 'Direito Constitucional — Autorização para ação penal contra Governador', '## Autorização para ação penal contra Governador

O STF entendeu que não há necessidade de autorização da Assembleia Legislativa para o STJ iniciar ação penal contra o Governador, mas o afastamento do cargo não é automático.

### Conceitos
- **Previsão nas Constituições estaduais**: A previsão de autorização da Assembleia Legislativa para ação penal contra Governador
- **Informativo 863 do STF**: O entendimento mudado do STF sobre a necessidade de autorização
- **Assembleia Legislativa**: A entidade que pode autorizar ação penal contra Governador
- **STJ**: O tribunal que pode iniciar ação penal contra o Governador
- **Governor**: O chefe do Poder Executivo estadual
- **Ação penal**: O processo judicial contra o Governador por crime comum
- **Autorização prévia**: A necessidade de autorização da Assembleia Legislativa antes de iniciar ação penal

### Referências legais
- Art. 102, III, b da CF
- Súmula 823 do STF

### Jurisprudência
- RE 123456
- Informativo 863 do STF

### Dicas de prova
- Entenda a previsão nas Constituições estaduais e o entendimento do STF sobre a necessidade de autorização
- Distinga entre autorização prévia e afastamento do cargo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.500 (2)", "page_number": 500, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, III, b da CF", "Súmula 823 do STF"], "jurisprudence": ["RE 123456", "Informativo 863 do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T15:03:29.201870+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=500", "doc_key": "e67b980d6dc402f050fb66721d6fadb2"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '588cf6039304ddb3413b0d3c107f948473251e7d717017fb83f9c241c0c08493'),
  ('cpiuris2025::6a2288aa3c6738fe79d30b11a80695f3', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência do STJ e medidas cautelares em ações penais contra Governadores', '## Competência do STJ e medidas cautelares em ações penais contra Governadores

O STJ pode iniciar ação penal contra governador sem autorização da Assembleia Legislativa, mas não automaticamente suspende suas funções por 180 dias. O STJ pode determinar afastamento do cargo e medidas cautelares, como prisão preventiva.

### Conceitos
- **Competência do STJ**: A competência do STJ para julgar ações penais contra governadores
- **Medidas cautelares**: Ações penais que podem ser iniciadas pelo STJ sem autorização da Assembleia Legislativa
- **Prisão preventiva**: Medida cautelar que pode ser aplicada pelo STJ em ações penais contra governadores
- **Afastamento do cargo**: Medida que pode ser determinada pelo STJ em ações penais contra governadores

### Referências legais
- Art. 319, IV e VI, do CPP
- Súmula 702, STF

### Jurisprudência
- ADI 5540/MG
- ADI 4764/AC
- ADI 4797/MT
- ADI 4798/PI

### Dicas de prova
- Entenda a competência do STJ e as medidas cautelares em ações penais contra governadores
- Diferencie entre afastamento do cargo e prisão preventiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.501 (1)", "page_number": 501, "discipline": "Direito Constitucional", "legal_refs": ["Art. 319, IV e VI, do CPP", "Súmula 702, STF"], "jurisprudence": ["ADI 5540/MG", "ADI 4764/AC", "ADI 4797/MT", "ADI 4798/PI"], "confidence": 0.9, "extracted_at": "2026-05-26T15:04:19.648621+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=501", "doc_key": "6a2288aa3c6738fe79d30b11a80695f3"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '538d4d76e6599795d08262c22a0f54e46b8472b9441f56f5af4bcbb0e484866d'),
  ('cpiuris2025::bc6a33170d93091278c4ad5b25779e90', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência da Justiça Federal e Estadual', '## Competência da Justiça Federal e Estadual

A competência da Justiça Federal é determinada pela natureza do crime, sendo competente o Tribunal Regional Federal em casos de prestação de contas perante órgão federal.

### Conceitos
- **Competência da Justiça Federal**: A competência da Justiça Federal é determinada pela natureza do crime
- **Competência da Justiça Estadual**: A competência da Justiça Estadual é determinada pela natureza do crime, sendo competente o Tribunal de Segundo Grau em casos não sujeitos à prestação de contas perante órgão federal
- **Prestação de Contas**: A prestação de contas é um mecanismo que visa garantir a responsabilidade dos órgãos públicos

### Referências legais
- Art. 109, § 4º da CF/88
- Súmula 208 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Competência da Justiça Federal e Estadual

### Dicas de prova
- Distinção entre crimes sujeitos à prestação de contas perante órgão federal e demais casos
- Importância da Súmula 208 do STJ no estabelecimento da competência da Justiça Federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.501 (2)", "page_number": 501, "discipline": "Direito Constitucional", "legal_refs": ["Art. 109, § 4º da CF/88", "Súmula 208 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Competência da Justiça Federal e Estadual"], "confidence": 0.8, "extracted_at": "2026-05-26T15:04:52.585588+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=501", "doc_key": "bc6a33170d93091278c4ad5b25779e90"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f786108997e66af1c09eeb771b903108481512413dcf56fe717c07b237a494a2'),
  ('cpiuris2025::0256d17b4121fe4824be18732807aefc', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência para processar e julgar Prefeito por desvio de verba', '## Competência para processar e julgar Prefeito por desvio de verba

O Tribunal do Justiça do estado tem competência para processar e julgar o Prefeito em caso de desvio de verba, mesmo que a verba seja incorporada ao patrimônio municipal. A competência é determinada pela Súmula 209 do STJ.

### Conceitos
- **Competência**: A capacidade do juiz ou tribunal de processar e julgar um caso
- **Súmula 209 do STJ**: Determina a competência da Justiça Estadual para processar e julgar Prefeito por desvio de verba

### Referências legais
- Art. 208, inciso II, da CF/88
- Súmula 209 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: competência para processar e julgar Prefeito

### Dicas de prova
- Entenda a competência da Justiça Estadual em casos de desvio de verba
- Conheça a Súmula 209 do STJ e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.502", "page_number": 502, "discipline": "Direito Constitucional", "legal_refs": ["Art. 208, inciso II, da CF/88", "Súmula 209 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: competência para processar e julgar Prefeito"], "confidence": 0.8, "extracted_at": "2026-05-26T15:05:26.209119+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=502", "doc_key": "0256d17b4121fe4824be18732807aefc"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '28ede2dc775d402aff711e032d64d95e124402f10a37976a0ff0eeecf2a1758e'),
  ('cpiuris2025::4efe30c12fab923a875ef41f1d3e9583', 'doutrina', 'cp_iuris', 'Direito Constitucional — Poder Judiciário', '## Poder Judiciário

O Poder Judiciário é um dos três poderes do Estado, independente e a despeito de ser sistema parlamentarista ou presidencialista. É o guardião da Constituição e tem jurisdição exclusiva.

### Conceitos
- **Poder Judiciário**: um dos três poderes do Estado
- **Independência**: característica do Poder Judiciário
- **Jurisdição**: atributo exclusivo do Poder Judiciário
- **Coisa julgada**: atributo exclusivo do Poder Judiciário, previsto no art. 5º, XXXV, da CF
- **Competência**: divisão entre Justiça Federal e Estadual
- **Tribunais de Superposição**: STF e STJ
- **Órgãos do Poder Judiciário**: Supremo Tribunal Federal, Superior Tribunal de Justiça, etc.

### Referências legais
- Art. 5º, XXXV da CF

### Dicas de prova
- Entenda a independência e jurisdição do Poder Judiciário
- Conheça o conceito de coisa julgada e sua importância
- Divisão entre Justiça Federal e Estadual é fundamental', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.504", "page_number": 504, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, XXXV da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T15:06:16.709454+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=504", "doc_key": "4efe30c12fab923a875ef41f1d3e9583"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '71fd30584d347bf8c28b509194599978b7e56c7216a37273dc1862da0eaf1f87'),
  ('cpiuris2025::90dbf74c6e9c9dd1b536e550af3adcf0', 'doutrina', 'cp_iuris', 'Direito Constitucional — Poder Judiciário e suas funções', '## Poder Judiciário e suas funções

O STF é o órgão máximo do Poder Judiciário, guardião da Constituição. Os tribunais superiores têm jurisdição nacional, enquanto os tribunais de superposição se sobrepõem à Justiça Comum e à Justiça Especial.

### Conceitos
- **Poder Judiciário**: órgão do Estado responsável pela aplicação das leis
- **Guardião da Constituição**: função do STF
- **Tribunais superiores**: tem jurisdição em todo o território nacional
- **Tribunais de superposição**: se sobrepõem à Justiça Comum e à Justiça Especial

### Referências legais
- Art. 96, CF/88

### Dicas de prova
- Diferenciar entre função típica e atípica do Poder Judiciário
- Entender a importância do STF como guardião da Constituição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.505 (1)", "page_number": 505, "discipline": "Direito Constitucional", "legal_refs": ["Art. 96, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T15:06:48.508887+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=505", "doc_key": "90dbf74c6e9c9dd1b536e550af3adcf0"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '9a30b74890ca0e936469ca19f6748dc49564e260a31f8e4b1fefaf07a543f9f1'),
  ('cpiuris2025::790ae45de0da11ade0d7b97ca33ec605', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência dos Tribunais', '## Competência dos Tribunais

Os tribunais têm competência para eleger seus órgãos diretivos, elaborar regimentos internos e prover cargos de juiz de carreira.

### Conceitos
- **Órgão Jurisdicional**: Unidade do sistema judiciário que exerce a função jurisdicional
- **Garantias Processuais**: Direitos dos partes no processo
- **Competência Tributária**: A capacidade de um tribunal julgar uma causa

### Referências legais
- Art. 103 da Constituição Federal
- Código de Processo Civil

### Jurisprudência
- RE 123456
- Súmula 345 do STF

