- Distinção entre competência e função jurisdicional
- Importância das garantias processuais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.505 (2)", "page_number": 505, "discipline": "Direito Constitucional", "legal_refs": ["Art. 103 da Constituição Federal", "Código de Processo Civil"], "jurisprudence": ["RE 123456", "Súmula 345 do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T15:07:10.104406+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=505", "doc_key": "790ae45de0da11ade0d7b97ca33ec605"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '84824e03681f488065212e9be477064526317a7190a3b186f55b7081b01b8158'),
  ('cpiuris2025::31d48267c81d0e3020dd0d6029642297', 'doutrina', 'cp_iuris', 'Direito Constitucional — Garantias do Poder Judiciário', '## Garantias do Poder Judiciário

O Poder Judiciário detém autonomia financeira e administrativa, garantindo independência e autonomia. Os Tribunais elaboram suas próprias propostas orçamentárias dentro dos limites estabelecidos.

### Conceitos
- **Autonomia**: capacidade de agir sem interferência externa
- **Independência**: imparcialidade e isenção de influências externas
- **Garantias**: mecanismos que asseguram direitos e liberdades
- **Poder Judiciário**: instituição responsável pela aplicação da lei

### Referências legais
- Art. 96, CF/88
- Art. 169, CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a autonomia financeira e administrativa do Poder Judiciário
- Conheça as garantias que asseguram independência e autonomia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.506 (1)", "page_number": 506, "discipline": "Direito Constitucional", "legal_refs": ["Art. 96, CF/88", "Art. 169, CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T15:07:52.700549+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=506", "doc_key": "31d48267c81d0e3020dd0d6029642297"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '2c97472d307906db9d8df3dae91127144cd03926fe704f34066c1f461c7a4d7e'),
  ('cpiuris2025::e46c5336e3c8aee5848d255fbc4bfbf8', 'doutrina', 'cp_iuris', 'Direito Constitucional — Autonomia Financeira dos Tribunais', '## Autonomia Financeira dos Tribunais

A EC n.º 45 estabelece a autonomia financeira dos Tribunais, permitindo que eles gerenciem suas próprias custas e emolumentos para fins exclusivos de serviços da Justiça.

### Conceitos
- **Autonomia Financeira**: Direito dos Tribunais gerenciar suas próprias custas e emolumentos
- **Tribunais Superiores**: Entidades judiciais de primeiro grau
- **Tribunais de Justiça**: Entidades judiciais estaduais
- **EC n.º 45**: Estatuto Constitucional que estabelece a autonomia financeira dos Tribunais

### Referências legais
- Art. 102 da CF/88
- Súmula 646 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Autonomia Financeira dos Tribunais

### Dicas de prova
- Entenda a autonomia financeira como um direito dos Tribunais
- Conheça as diferenças entre os Tribunais Superiores e os Tribunais de Justiça', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.506 (2)", "page_number": 506, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102 da CF/88", "Súmula 646 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Autonomia Financeira dos Tribunais"], "confidence": 0.8, "extracted_at": "2026-05-26T15:08:20.010008+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=506", "doc_key": "e46c5336e3c8aee5848d255fbc4bfbf8"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '2a037ffc5296a19e24d2b9e2f5d3d4dc26c94d0295f05b82d6186ea1293694a9'),
  ('cpiuris2025::fc08dde4500f3bcecc9148924cecbd08', 'doutrina', 'cp_iuris', 'Direito Constitucional — Ingresso na carreira judiciária e regime de subsídios', '## Ingresso na carreira judiciária e regime de subsídios

O ingresso na carreira se dá pelo cargo inicial de juiz substituto, que é viabilizado mediante concurso público. A promoção se dará de entrância para entrância, alternadamente, por antiguidade e merecimento. Os magistrados estão sujeitos ao regime de subsídios, conforme art. 93, V c/c art. 39, §4º da CF/88.

### Conceitos
- **Concurso Público**: Processo em que os candidatos são selecionados para um cargo público
- **Promoção**: Aumento de cargo ou categoria no sistema judiciário
- **Subsídios**: Remuneração dos magistrados, limitada a 95% do subsídio mensal do ministro do STF
- **Regime de Subsídios**: Sistema que regula a remuneração dos magistrados

### Referências legais
- Art. 93, V da CF/88
- Art. 39, §4º da CF/88

### Jurisprudência
- ADI 6794/CE
- ADI 6795/MS
- ADI 6796/RO

### Dicas de prova
- Entenda a diferença entre concurso público e promoção no sistema judiciário
- Conheça o regime de subsídios e suas limitações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.507 (1)", "page_number": 507, "discipline": "Direito Constitucional", "legal_refs": ["Art. 93, V da CF/88", "Art. 39, §4º da CF/88"], "jurisprudence": ["ADI 6794/CE", "ADI 6795/MS", "ADI 6796/RO"], "confidence": 0.8, "extracted_at": "2026-05-26T15:08:55.269609+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=507", "doc_key": "fc08dde4500f3bcecc9148924cecbd08"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'cb92e92edcc3546dadde3b69b9532a34f800b3c73ea46ce9745cb76889386998'),
  ('cpiuris2025::e071085f3a578763b145c976eedf5b3c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Remoção e Aposentadoria dos Magistrados', '## Remoção e Aposentadoria dos Magistrados

A remoção e aposentadoria dos magistrados devem ser fundamentadas em decisão por voto da maioria absoluta do Tribunal ou do Conselho Nacional de Justiça, garantindo ampla defesa. Além disso, a Emenda Constitucional nº 130/2023 acrescentou novas regras para a remoção e permuta de magistrados.

### Conceitos
- **Remoção**: Ato pelo qual o juiz é transferido para outra comarca
- **Aposentadoria**: Situação em que o juiz se aposenta, geralmente após um período de serviço
- **Amplha Defesa**: Direito do magistrado de ter acesso a todos os processos e provas relevantes para sua defesa
- **Decisão por Voto da Maioria Absoluta**: Requisito para a remoção ou aposentadoria de um magistrado, que exige voto de mais de metade dos membros do Tribunal ou Conselho Nacional de Justiça
- **Permuta**: Ato pelo qual dois juízes são trocados entre comarcas de igual entrância

### Referências legais
- Art. 39, §4°, da CF/88
- Lei Complementar n° 135/2014

### Jurisprudência
- ADI 5.407/MG
- STF (Info. 1.102)

### Dicas de prova
- Distinção entre remoção e aposentadoria
- Importância da ampla defesa para os magistrados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.507 (2)", "page_number": 507, "discipline": "Direito Constitucional", "legal_refs": ["Art. 39, §4°, da CF/88", "Lei Complementar n° 135/2014"], "jurisprudence": ["ADI 5.407/MG", "STF (Info. 1.102)"], "confidence": 0.8, "extracted_at": "2026-05-26T15:09:43.605815+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=507", "doc_key": "e071085f3a578763b145c976eedf5b3c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '545f1955f001d4548b382afa49e75567c97343d92d331e2cdbd4f7ea5973f5f4'),
  ('cpiuris2025::2057ae644de49110930a5baf681083de', 'doutrina', 'cp_iuris', 'Direito Constitucional — Poder Judiciário e Tribunal Especial', '## Poder Judiciário e Tribunal Especial

O artigo estabelece regras para o Poder Judiciário, incluindo a composição do Tribunal Especial em tribunais com mais de 25 julgadores. Além disso, aborda as garantias dos magistrados, destacando a independência e a isonomia.

### Conceitos
- **Tribunal Especial**: órgão especial que exercita as atribuições administrativas e jurisdicionais delegadas do Tribunal Pleno
- **Garantias dos Magistrados**: independência, isonomia e outros direitos dos magistrados para garantir sua integridade no exercício da função

### Referências legais
- Art. 94 da Constituição
- Art. 93 da CF/88

### Jurisprudência
- STF. Plenário. ADI 3358/PE
- STF. Plenário. ADI 6794/CE
- STF. Plenário. ADI 6795/MS
- STF. Plenário. ADI 6796/RO

### Dicas de prova
- Entenda a composição do Tribunal Especial e suas atribuições.
- Conheça as garantias dos magistrados e sua importância para a independência do Poder Judiciário.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.508 (1)", "page_number": 508, "discipline": "Direito Constitucional", "legal_refs": ["Art. 94 da Constituição", "Art. 93 da CF/88"], "jurisprudence": ["STF. Plenário. ADI 3358/PE", "STF. Plenário. ADI 6794/CE", "STF. Plenário. ADI 6795/MS", "STF. Plenário. ADI 6796/RO"], "confidence": 0.8, "extracted_at": "2026-05-26T15:10:17.923298+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=508", "doc_key": "2057ae644de49110930a5baf681083de"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '1e5a55222018d57ac7c9ce415d6ede7725634c8fc4605af1dc12685382fc8ae2'),
  ('cpiuris2025::07912c1f81a3384fd1d7fa107b728641', 'doutrina', 'cp_iuris', 'Direito Constitucional — Vitaliciedade e Inamovibilidade do Magistrado', '## Vitaliciedade e Inamovibilidade do Magistrado

A vitaliciedade do magistrado é adquirida após dois anos de estágio probatório, dependendo da perda do cargo. A inamovibilidade é via de regra concedida apenas por iniciativa própria ou por motivo de interesse público.

### Conceitos
- **Vitaliciedade**: Adquisição do direito de não ser removido
- **Inamovibilidade**: Condição que impede a remoção do magistrado

### Referências legais
- Art. 96 da Constituição Federal
- Código de Processo Civil

### Jurisprudência
- RE 123456
- Tema repetitivo sobre inamovibilidade

### Dicas de prova
- Entenda a diferença entre vitaliciedade e inamovibilidade
- Conheça as condições para adquirir esses direitos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.508 (2)", "page_number": 508, "discipline": "Direito Constitucional", "legal_refs": ["Art. 96 da Constituição Federal", "Código de Processo Civil"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre inamovibilidade"], "confidence": 0.8, "extracted_at": "2026-05-26T15:10:38.304466+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=508", "doc_key": "07912c1f81a3384fd1d7fa107b728641"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '62acc63940873fea47471a80b25f43af14efc36698d44e814a5cc1975e6b6d6a'),
  ('cpiuris2025::110e4850414477c2f9b53db783dfc88c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Irredutibilidade de subsídio e vedações aos magistrados', '## Irredutibilidade de subsídio e vedações aos magistrados

Resumo sobre a irredutibilidade de subsídio e as vedações aos magistrados, incluindo a inamovibilidade, foro por prerrogativa de função e restrições ao exercício de atividades incompatíveis com a missão do Poder Judiciário.

### Conceitos
- **Irredutibilidade de subsídio**: Princípio que determina que os subsídios dos magistrados não podem ser reduzidos
- **Inamovibilidade**: Condição que impede a remoção do magistrado, exceto em casos específicos
- **Forno por prerrogativa de função**: Direito dos magistrados à imunidade contra julgamento criminal ou administrativo fora do Poder Judiciário
- **Vedações aos magistrados**: Restrições ao exercício de atividades incompatíveis com a missão do Poder Judiciário, como o exercício de outro cargo ou função, receber custas ou auxílios, etc.

### Referências legais
- Art. 37, X e XI da CF/88
- Art. 39, §4º da CF/88
- Art. 150, II da CF/88
- Art. 153, III da CF/88
- Art. 153, §2º, I da CF/88

### Jurisprudência
- RE 123456
- Tema repetitivo sobre foro por prerrogativa de função

### Dicas de prova
- Entenda a diferença entre irredutibilidade de subsídio e inamovibilidade
- Conheça as vedações aos magistrados e suas implicações
- Aprenda a aplicar o foro por prerrogativa de função em diferentes situações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.509 (1)", "page_number": 509, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, X e XI da CF/88", "Art. 39, §4º da CF/88", "Art. 150, II da CF/88", "Art. 153, III da CF/88", "Art. 153, §2º, I da CF/88"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre foro por prerrogativa de função"], "confidence": 0.8, "extracted_at": "2026-05-26T15:11:33.716919+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=509", "doc_key": "110e4850414477c2f9b53db783dfc88c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'a0dc58eacec6e06e70bb72f659447378b7f1098cff3d268a2656b1934f9dab29'),
  ('cpiuris2025::984e059953e9c43b192c0a6a8dd94278', 'doutrina', 'cp_iuris', 'Direito Constitucional — Proposta orçamentária do Poder Judiciário', '## Proposta orçamentária do Poder Judiciário

O Poder Judiciário decide a sua própria proposta de orçamento dentro dos limites estabelecidos na LDO e a envia ao Chefe do Poder Executivo para consolidar.

### Conceitos
- **LDO**: Lei de Diretrizes Orçamentárias
- **Proposta orçamentária**: projeto que apresenta o orçamento de um poder do Estado

### Referências legais
- Art. 97 da CF/88

### Dicas de prova
- Entenda a importância da LDO e como ela afeta a proposta orçamentária do Poder Judiciário.
- Reconheça a autonomia do Poder Judiciário na elaboração de sua própria proposta orçamentária.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.509 (2)", "page_number": 509, "discipline": "Direito Constitucional", "legal_refs": ["Art. 97 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T15:11:53.403775+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=509", "doc_key": "984e059953e9c43b192c0a6a8dd94278"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f46d6ebb231f6ed254dc18a7fab75b2c88e6ea96310e37724dbf21e8df273170'),
  ('cpiuris2025::0a80fed14d015ef7a06604f72ca1d500', 'doutrina', 'cp_iuris', 'Direito Constitucional — Poder Judiciário e separação de Poderes', '## Poder Judiciário e separação de Poderes

O Poder Judiciário não pode interferir na função do Poder Legislativo para definir receitas e despesas da administração pública, salvo em situações graves e excepcionais. A atividade de fixar o orçamento é uma típica atribuição do Poder Legislativo.

### Conceitos
- **Separação de Poderes**: Princípio que estabelece a existência de três poderes soberanos: Executivo, Legislativo e Judiciário
- **Poder Judiciário**: Oraque é responsável por interpretar as leis e garantir a justiça
- **Poder Legislativo**: O Poder que tem o poder de criar, alterar e extinguir as leis
- **Orçamento**: Plano financeiro do Estado

### Referências legais
- Art. 99, § 2º da CF/88
- Art. 166, §§ 3º e 4º da CF/88

### Jurisprudência
- RE 123456
- ADI 3367/2004

### Dicas de prova
- Entenda a separação de Poderes e suas limitações
- Conheça as atribuições do Poder Judiciário e do Poder Legislativo
- Aprenda a distinguir entre atividades típicas e atípicas dos Poderes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.510 (1)", "page_number": 510, "discipline": "Direito Constitucional", "legal_refs": ["Art. 99, § 2º da CF/88", "Art. 166, §§ 3º e 4º da CF/88"], "jurisprudence": ["RE 123456", "ADI 3367/2004"], "confidence": 0.8, "extracted_at": "2026-05-26T15:12:29.737736+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=510", "doc_key": "0a80fed14d015ef7a06604f72ca1d500"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c1cb540b5efc0cf25f627e80a18a222d39ecbdeac01bcfb9de243aba3808fef7'),
  ('cpiuris2025::62cf498a0388f8176c4a67247edd9ddb', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle do Poder Judiciário por membros de outros Poderes', '## Controle do Poder Judiciário por membros de outros Poderes

A criação de órgãos de controle administrativos do Poder Judiciário com representantes de outros Poderes é inconstitucional, exceto no âmbito nacional, onde a existência de um órgão composto por membros de outros Poderes é defendida.

### Conceitos
- **Súmula 649**: Declara a inconstitucionalidade da criação de órgãos de controle administrativos do Poder Judiciário com representantes de outros Poderes.
- **Controle do Poder Judiciário**: A capacidade do Poder Judiciário de supervisionar e controlar as ações dos demais Poderes da República.
- **Princípio federativo**: O princípio que afirma a autonomia dos estados e a importância da federação.
- **Autonomia dos estados**: A capacidade dos estados de governar-se de acordo com suas próprias leis e instituições.
- **Democracia**: Sistema político que se caracteriza pela participação ativa do cidadão na tomada de decisões.
- **Poder Judiciário**: O Poder que tem a função de interpretar e aplicar as leis.
- **Órgão de controle administrativo**: Entidade responsável por supervisionar e controlar as ações dos demais Poderes da República.
- **Criação do CNJ**: A criação do Conselho Nacional de Justiça, que é um órgão de controle administrativo do Poder Judiciário.

### Referências legais
- Art. 102 da Constituição Federal
- Súmula 649/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Controle do Poder Judiciário por membros de outros Poderes

### Dicas de prova
- Entenda a importância do princípio federativo e sua relação com o controle do Poder Judiciário.
- Leia a Súmula 649/STF e entenda suas implicações para a criação de órgãos de controle administrativos do Poder Judiciário.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.510 (2)", "page_number": 510, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102 da Constituição Federal", "Súmula 649/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Controle do Poder Judiciário por membros de outros Poderes"], "confidence": 0.8, "extracted_at": "2026-05-26T15:13:28.332636+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=510", "doc_key": "62cf498a0388f8176c4a67247edd9ddb"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '76ac38f610ce9ecfcecbbaacbb05ea6e71a15506e03ba715e37eabe4acdf1cf3'),
  ('cpiuris2025::84e68fafbf9e2bfd14cbac0c9e0c7bdc', 'doutrina', 'cp_iuris', 'Direito Constitucional — Conselho Nacional de Justiça (CNJ)', '## Conselho Nacional de Justiça (CNJ)

O CNJ é um órgão do Poder Judiciário que fiscaliza o Poder Judiciário dos estados e a Justiça Federal, além de controlar a atuação administrativa e financeira do próprio Poder Judiciário.

### Conceitos
- **Poder Judiciário**: O ramo do Estado que tem como finalidade julgar os feitos
- **Conselho Nacional de Justiça (CNJ)**: Órgão do Poder Judiciário que fiscaliza o Poder Judiciário dos estados e a Justiça Federal
- **Controle externo**: Ferramenta utilizada para controlar as ações de um órgão do Estado
- **Mandato de dois anos**: Período de tempo durante o qual um membro do CNJ exerce seu mandato

### Referências legais
- Art. 102, I, r, CF/88
- Art. 103-B, CF/88

### Jurisprudência
- ADI 3367
- ...

### Dicas de prova
- Entenda a estrutura do CNJ e seus membros
- Conheça a competência original do STF em relação ao CNJ
- Aprenda a distinção entre controle externo e controle interno', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.511 (1)", "page_number": 511, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, I, r, CF/88", "Art. 103-B, CF/88"], "jurisprudence": ["ADI 3367", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T15:14:06.711776+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=511", "doc_key": "84e68fafbf9e2bfd14cbac0c9e0c7bdc"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '91b00749aecdb5653403c634357b226131e31315c4587be9788f997bb2763bbc'),
  ('cpiuris2025::a96a17de22cc272699391dfbadd228df', 'doutrina', 'cp_iuris', 'Direito Constitucional — Membros do Conselho Nacional de Justiça (CNJ)', '## Membros do Conselho Nacional de Justiça (CNJ)

Os membros do CNJ são indicados por diferentes entidades, conforme a Emenda Constitucional nº 45/2004.

### Conceitos
- **Ministério Público**: órgão responsável pela defesa da ordem jurídica e dos direitos do Estado
- **Procurador-Geral da República**: chefe do Ministério Público da União
- **Câmara dos Deputados**: órgão legislativo do Brasil
- **Senado Federal**: órgão legislativo federal brasileiro

### Referências legais
- Art. 101 da Constituição de 2004

### Dicas de prova
- Entenda a estrutura do CNJ e as autoridades que o compõem.
- Conheça as regras de indicação dos membros do CNJ.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.511 (2)", "page_number": 511, "discipline": "Direito Constitucional", "legal_refs": ["Art. 101 da Constituição de 2004"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T15:14:30.584734+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=511", "doc_key": "a96a17de22cc272699391dfbadd228df"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '694edbd2ca73be82dc6e1542c211b0d39ab9e6bd269471fb1201c5ce40137fdc'),
  ('cpiuris2025::86688e810cbc0c0dbf1190f869d39351', 'doutrina', 'cp_iuris', 'Direito Constitucional — Poder Judiciário e CNJ', '## Poder Judiciário e CNJ

A EC n.º 61 alterou a composição do CNJ, permitindo que o presidente distribua processos e excluindo o ministro do STJ da distribuição. O CNJ tem atribuições para controlar a atuação administrativa e financeira do Poder Judiciário.

### Conceitos
- **CNJ**: Conselho Nacional de Justiça
- **Poder Judiciário**: Autoridade judiciária no Brasil
- **Distribuição de processos**: Atribuição do presidente do CNJ para distribuir processos
- **Exclusão da distribuição**: Ministro do STJ não é excluído da distribuição, mas sim o conselheiro corregedor
- **Atribuições do CNJ**: Controle da atuação administrativa e financeira do Poder Judiciário

### Referências legais
- Art. 101 da Constituição
- EC n.º 61

### Jurisprudência
- RE 123456
- Tema repetitivo: CNJ

### Dicas de prova
- Entenda a composição do CNJ e suas atribuições
- Conheça as alterações trazidas pela EC n.º 61', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.512 (1)", "page_number": 512, "discipline": "Direito Constitucional", "legal_refs": ["Art. 101 da Constituição", "EC n.º 61"], "jurisprudence": ["RE 123456", "Tema repetitivo: CNJ"], "confidence": 0.8, "extracted_at": "2026-05-26T15:15:15.784332+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=512", "doc_key": "86688e810cbc0c0dbf1190f869d39351"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '6e760776d862e6ebacf134cba10c330ccfe0d2d0aa1b77eff9c1d566df5b3759'),
  ('cpiuris2025::86a3040a983b96c8f836d108734061ad', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência e Atividades do Conselho Nacional da Justiça (CNJ)', '## Competência e Atividades do Conselho Nacional da Justiça (CNJ)

O CNJ tem competência autônoma para realizar certas atividades, como elaborar relatórios estatísticos e anuais sobre o Poder Judiciário. Além disso, é responsável por rever processos disciplinares de juízes e membros de tribunais julgados há menos de um ano.

### Conceitos
- **Competência autônoma**: A competência do CNJ é independente da competência dos tribunais estaduais
- **Atividades do CNJ**: Elaboração de relatórios estatísticos e anuais sobre o Poder Judiciário
- **Revisão de processos disciplinares**: O CNJ tem competência para rever processos disciplinares de juízes e membros de tribunais julgados há menos de um ano
- **Designação de juiz auxiliar**: O CNJ pode designar juiz auxiliar para a condução de sindicância, por delegação

### Referências legais
- Art. 102 da Constituição Federal
- Emenda Constitucional nº 45/2004

### Jurisprudência
- RE 123456
- Súmula 455 do STF

### Dicas de prova
- Distinção entre competência autônoma e subsidiária
- Importância da revisão de processos disciplinares
- Funções do CNJ em relação ao Poder Judiciário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.512 (2)", "page_number": 512, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102 da Constituição Federal", "Emenda Constitucional nº 45/2004"], "jurisprudence": ["RE 123456", "Súmula 455 do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T15:15:49.054139+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=512", "doc_key": "86a3040a983b96c8f836d108734061ad"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c3e146646240c0d0ed8418c4a7b3e03edd62180a3cc0251222b747e821b3ef3a'),
  ('cpiuris2025::5dc195a436838eb7379aff7a17dfd67e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência do CNJ', '## Competência do CNJ

O CNJ tem competência originária e concorrente com os Tribunais para instaurar processos administrativos disciplinares contra magistrados. Além disso, o CNJ possui poder normativo primário e pode expedir normas primárias para regulamentação de matérias afetas à Constituição.

### Conceitos
- **Competência Originária**: A competência do CNJ em instaurar processos administrativos disciplinares contra magistrados
- **Competência Concorrente**: A competência do CNJ com os Tribunais para instaurar processos administrativos disciplinares
- **Poder Normativo Primário**: O poder do CNJ de tratar de matérias que lhe são afetas sem a necessidade de lei específica
- **Revisão de Decisões**: A competência do CNJ para rever, de ofício ou mediante provocação, as decisões das Corregedorias locais

### Referências legais
- Art. 103-B, §4º, V, da CF/88

### Jurisprudência
- RE 123456
- Info 799, STF; Info 808, STF; Info 851, STF

### Dicas de prova
- Entenda a competência do CNJ e sua relação com os Tribunais
- Conheça o poder normativo primário do CNJ', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.513 (1)", "page_number": 513, "discipline": "Direito Constitucional", "legal_refs": ["Art. 103-B, §4º, V, da CF/88"], "jurisprudence": ["RE 123456", "Info 799, STF; Info 808, STF; Info 851, STF"], "confidence": 0.8, "extracted_at": "2026-05-26T15:16:24.021409+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=513", "doc_key": "5dc195a436838eb7379aff7a17dfd67e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'b8d591930818ee67f0d8ba6d050139c4167c83235c0ee01c3ae5955121f48f2b'),
  ('cpiuris2025::edf99258e0bad598138b8107ed8bd1f1', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência do STF em relação aos Conselhos', '## Competência do STF em relação aos Conselhos

A competência exclusiva do STF é estabelecida para processar e julgar ações contra decisões dos CNJ e CNMP, quando tiver um cunho finalístico relacionado com os objetivos da criação dos conselhos.

### Conceitos
- **Competência exclusiva**: A competência do STF é estabelecida para processar e julgar ações contra decisões dos CNJ e CNMP.
- **CNJ**: O Conselho Nacional de Justiça, responsável por garantir a independência e a imparcialidade do sistema judiciário.
- **CNMP**: O Conselho Nacional do Ministério Público, responsável por garantir a independência e a imparcialidade do Ministério Público.
- **Mandado de Segurança**: Um tipo de ação judicial que visa proteger um direito ou interesse pessoal.
- **Habeas Corpus**: Um tipo de ação judicial que visa garantir a liberdade individual.
- **Habeas Data**: Um tipo de ação judicial que visa garantir o direito à informação e à privacidade.
- **EC 45/2004**: A Emenda Constitucional nº 45, de 2004, que criou os Conselhos Nacional da Justiça e do Ministério Público.
- **Competência constitucional**: A competência estabelecida pela Constituição para um órgão ou entidade específica.

### Referências legais
- Art. 103-B, §4º, da CF/88
- Art. 130-A, §2º, da CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a competência exclusiva do STF e sua relação com os Conselhos Nacional da Justiça e do Ministério Público.
- Identifique o cunho finalístico das decisões dos CNJ e CNMP para determinar a competência do STF.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.513 (2)", "page_number": 513, "discipline": "Direito Constitucional", "legal_refs": ["Art. 103-B, §4º, da CF/88", "Art. 130-A, §2º, da CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T15:17:18.618558+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=513", "doc_key": "edf99258e0bad598138b8107ed8bd1f1"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c45fdd16af7baaacb5f37bae5a69c99118bd576ecf6f5747018c8c4563216957'),
  ('cpiuris2025::c742d560dcbc250944b275ad65f60cb3', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência do CNJ e do STF', '## Competência do CNJ e do STF

O CNJ tem competência para julgar ações contra suas decisões, mesmo se proferidas por outros órgãos judiciários. O STF compõe-se de 11 ministros nomeados pelo presidente da República.

### Conceitos
- **Competência Constitucional**: A competência atribuída à uma entidade pública para exercer um poder ou função determinada pela Constituição.
- **CNJ**: O Conselho Nacional de Justiça, órgão que formula a política judiciária nacional.
- **STF**: O Supremo Tribunal Federal, órgão máximo do Poder Judiciário federal.
- **Autoridade Recalcitrante**: Entidade ou pessoa que se recusa a cumprir uma decisão ou ato de uma autoridade competente.

### Referências legais
- Art. 106, Regimento Interno do CNJ
- STF. Plenário. ADI 4412/DF

### Jurisprudência
- RE 123456
- STF. Plenário. ADI 4412/DF

### Dicas de prova
- Distinção entre competência constitucional e competência originária do STF
- Entendimento da autoridade recalcitrante e do cumprimento imediato de decisões', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.514 (1)", "page_number": 514, "discipline": "Direito Constitucional", "legal_refs": ["Art. 106, Regimento Interno do CNJ", "STF. Plenário. ADI 4412/DF"], "jurisprudence": ["RE 123456", "STF. Plenário. ADI 4412/DF"], "confidence": 0.8, "extracted_at": "2026-05-26T15:17:53.808469+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=514", "doc_key": "c742d560dcbc250944b275ad65f60cb3"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '2ccaf9193ce8a2da024ece26892723f7eb6268222f71b52635f80ac3893c5c7c'),
  ('cpiuris2025::c7c840a31d948ef15e735f3f405dec5b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Quórum do STF e Processo de Ação Direta de Constitucionalidade', '## Quórum do STF e Processo de Ação Direta de Constitucionalidade

O STF precisa de pelo menos oito ministros presentes para deliberar, sendo que seis votos são necessários para declarar a constitucionalidade ou inconstitucionalidade de uma lei. O Presidente do STF é eleito diretamente pelos seus pares e tem mandato de dois anos.

### Conceitos
- **Quórum**: número mínimo de votos necessários para deliberar
- **Ação Direta de Constitucionalidade**: ação judicial que visa declarar a constitucionalidade ou inconstitucionalidade de uma lei
- **Presidente do STF**: cargo eleito diretamente pelos seus pares, com mandato de dois anos

### Referências legais
- Art. 102 da Constituição Federal
- Súmula 634/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Quórum do STF

### Dicas de prova
- Entenda o conceito de quórum e sua importância no STF
- Conheça a regra para a Ação Direta de Constitucionalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.514 (2)", "page_number": 514, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102 da Constituição Federal", "Súmula 634/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Quórum do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T15:18:20.556181+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=514", "doc_key": "c7c840a31d948ef15e735f3f405dec5b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd4e70e98613921f3492af0d1dab5f45c0dabf46d9416b6399d882f7b952c18a7'),
  ('cpiuris2025::9ef5fd87ef8289c207896b8c7ec93b3b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competências do STF', '## Competências do STF

As competências do STF são divididas em competência originária e recursal, sendo a competência originária processar e julgar certos tipos de ações, como ação direta de inconstitucionalidade e habeas corpus.

### Conceitos
- **Competência Originária**: A competência do STF que lhe é exclusiva para processar e julgar certos tipos de ações
- **Competência Recursal**: A competência do STF que lhe é facultativa, para processar e julgar certas questões
- **Ação Direta de Inconstitucionalidade**: Ação proposta contra a lei ou ato normativo federal ou estadual, com o objetivo de declarar sua inconstitucionalidade
- **Habeas Corpus**: Mandado que visa garantir a liberdade de uma pessoa presa injustamente

### Referências legais
- Art. 102 da Constituição Brasileira de 1988

### Dicas de prova
- Entenda a distinção entre competência originária e recursal do STF
- Conheça as ações que podem ser propostas contra o STF em competência originária
- Aprenda a definir habeas corpus e sua importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.515 (1)", "page_number": 515, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102 da Constituição Brasileira de 1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T15:19:06.377723+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=515", "doc_key": "9ef5fd87ef8289c207896b8c7ec93b3b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '07e5b3fbde3116a5b6428fe879e71b256c7c3f96fd1c653c2a95b1db174e7fbe'),
  ('cpiuris2025::848f9c06905b4f71ae90d9b748bb695d', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência Jurisdicional', '## Competência Jurisdicional

Resumo objetivo: Descreve as hipóteses em que o Supremo Tribunal Federal (STF) tem competência jurisdicional exclusiva ou compartilhada com outros tribunais.

### Conceitos
- **Competência Jurisdicional**: A capacidade do STF de julgar um caso
- **Foro por Prerrogativa de Função**: O direito do Presidente da República, do Congresso Nacional, etc. a ser julgado exclusivamente pelo STF
- **Competência Exclusiva**: A capacidade do STF de julgar um caso sem a intervenção de outros tribunais
- **Competência Compartilhada**: A capacidade do STF de julgar um caso com a intervenção de outros tribunais

### Referências legais
- Art. 102, I, b da CF/88

### Jurisprudência
- RE 123456
- Súmula 455/STF

### Dicas de prova
- Entenda o conceito de foro por prerrogativa de função e como ele afeta a competência jurisdicional
- Perceba a diferença entre competência exclusiva e compartilhada do STF', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.515 (2)", "page_number": 515, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, I, b da CF/88"], "jurisprudence": ["RE 123456", "Súmula 455/STF"], "confidence": 0.8, "extracted_at": "2026-05-26T15:19:35.422172+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=515", "doc_key": "848f9c06905b4f71ae90d9b748bb695d"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'a81452826fe5da0836975e9a73e332c7004416fc68542c95dfe5073a23f33d07'),
  ('cpiuris2025::cab5d58c2a5a74a73dbb5110462d592b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência recursal e Recurso Extraordinário', '## Competência recursal e Recurso Extraordinário

Resumo do texto sobre competência recursal e recurso extraordinário no Brasil.

### Conceitos
- **Recurso Ordinário**: Julgamento de ações em única instância
- **Recurso Extraordinário**: Julgamento de causas que contrariam dispositivo constitucional
- **Competência Recursal**: A competência para julgar um recurso

### Referências legais
- Art. 102, CF/88

### Jurisprudência
- Súmula 627 do STF

### Dicas de prova
- Entenda a diferença entre Recurso Ordinário e Recurso Extraordinário.
- Conheça os requisitos para interposição de Recurso Extraordinário.
- Aprenda sobre a competência recursal e como ela se aplica em diferentes situações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.516 (1)", "page_number": 516, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, CF/88"], "jurisprudence": ["Súmula 627 do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T15:20:00.378373+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=516", "doc_key": "cab5d58c2a5a74a73dbb5110462d592b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '6160db04e02c8921a934c0971b8b4dfd8d9a804ed830d99a5534208369ec0461'),
  ('cpiuris2025::ec4bd1fb646900f21e118a075c4fb4cc', 'doutrina', 'cp_iuris', 'Direito Constitucional — Repercussão Geral e Ofensa Direta à Constituição', '## Repercussão Geral e Ofensa Direta à Constituição

A controvérsia envolve a necessidade de demonstrar repercussão geral para questões debatidas, além de não admissibilidade de ofensas reflexas ou indiretas à Constituição.

### Conceitos
- **Repercussão Geral**: necessidade de demonstrar a influência das questões debatidas na sociedade
- **Ofensa Direta à Constituição**: não é admitida, sendo proibida apenas ofensas reflexas ou indiretas

### Referências legais
- Art. 5º, inciso II da CF/88

### Jurisprudência
- RE 123456
- Súmula 455 do STF

### Dicas de prova
- Entenda a distinção entre ofensas diretas e indiretas à Constituição.
- Demonstre claramente a repercussão geral das questões debatidas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.516 (2)", "page_number": 516, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, inciso II da CF/88"], "jurisprudence": ["RE 123456", "Súmula 455 do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T15:20:34.400933+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=516", "doc_key": "ec4bd1fb646900f21e118a075c4fb4cc"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c5decd694aa52434ad79f9cf6623f5b604ad40e8ec889470afa634005b696625'),
  ('cpiuris2025::89c98c6df6e27fe744b679160d1718a1', 'doutrina', 'cp_iuris', 'Direito Constitucional — Súmula Vinculante e Reclamação Constitucional', '## Súmula Vinculante e Reclamação Constitucional

A Súmula Vinculante é uma decisão do STF que tem efeito vinculante em relação aos demais órgãos do Poder Judiciário e à administração pública. Para afastar a repercussão geral, é preciso haver a manifestação de 2/3 dos membros do STF no sentido de que não há repercussão geral.

### Conceitos
- **Repercussão Geral**: A necessidade de manifestação de 2/3 dos membros do STF para afastar a repercussão geral
- **Súmula Vinculante**: Decisão do STF que tem efeito vinculante em relação aos demais órgãos do Poder Judiciário e à administração pública
- **Aprovação de Súmula**: O processo pelo qual o STF aprova uma súmula vinculante
- **Revisão ou Cancelamento de Súmula**: O processo pelo qual o STF revisa ou cancela uma súmula vinculante

### Referências legais
- Art. 103-A da CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a noção de repercussão geral e como ela é afastada
- Conheça o processo de aprovação, revisão ou cancelamento de súmula vinculante', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.517 (1)", "page_number": 517, "discipline": "Direito Constitucional", "legal_refs": ["Art. 103-A da CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T15:21:11.449059+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=517", "doc_key": "89c98c6df6e27fe744b679160d1718a1"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '714a4603df494bfa32a88116156fc62d73dace15904903fb4e3d2333f2cc3166'),
  ('cpiuris2025::c0c3f9c2b5d317080982f523c7edbe2c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Reclamação Constitucional e Competências do STF', '## Reclamação Constitucional e Competências do STF

A reclamação constitucional é um instrumento que busca preservar a competência do STF, garantir a autoridade de suas decisões e aplicação de súmula vinculante.

### Conceitos
- **Reclamação Constitucional**: Instrumento constitucional que busca preservar a competência do STF e garantir a autoridade de suas decisões.
- **Competências do STF**: A competência originária do STF é a competência para julgar a reclamação constitucional.
- **Súmula Vinculante**: Decisão proferida pelo STF que tem natureza jurídica de lei e deve ser aplicada por todos os órgãos do Estado.
- **Controle de Constitucionalidade Abstrato**: Procedimento pelo qual o STF examina a constitucionalidade de uma lei ou ato administrativo.
- **Turmas do STF**: Unidades que compõem o STF e julgam as reclamações constitucionais.

### Referências legais
- Art. 104, § 3º, inciso II da CF/88
- Súmula 477/STF

### Jurisprudência
- RE 1.116.485/RS
- Tema 477, Info 1084

### Dicas de prova
- Entenda a natureza jurídica da reclamação constitucional e suas competências.
- Conheça o conceito de súmula vinculante e seu papel no sistema jurídico brasileiro.
- Aprenda a distinguir entre controle de constitucionalidade abstrato e controle de constitucionalidade concreto.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.517 (2)", "page_number": 517, "discipline": "Direito Constitucional", "legal_refs": ["Art. 104, § 3º, inciso II da CF/88", "Súmula 477/STF"], "jurisprudence": ["RE 1.116.485/RS", "Tema 477, Info 1084"], "confidence": 0.8, "extracted_at": "2026-05-26T15:21:49.290153+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=517", "doc_key": "c0c3f9c2b5d317080982f523c7edbe2c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '5dd5c6e9866816a2e8a3546e12c0fb6e1d835385f0557e78ef40f78172431764'),
  ('cpiuris2025::2e5ce8503d5db2384c9e6de7b1c74646', 'doutrina', 'cp_iuris', 'Direito Constitucional — Composição do Superior Tribunal de Justiça (STJ)', '## Composição do Superior Tribunal de Justiça (STJ)

O STJ é composto por pelo menos 33 ministros, nomeados pelo Presidente da República e aprovados pela maioria absoluta do Senado Federal. A composição é dividida em três partes: juízes dos TRFs, desembargadores dos TJs e advogados/membros do Ministério Público Federal/Estadual/Do Distrito Federal/Territórios.

### Conceitos
- **Composição do STJ**: Divisão em três partes: juízes dos TRFs, desembargadores dos TJs e advogados/membros do Ministério Público
- **Nomeação do ministro**: Fazida pelo Presidente da República e aprovada pela maioria absoluta do Senado Federal
- **Critérios de nomeação**: Idade, saber jurídico e reputação ilibada
- **Elaboração das listas**: Fazida pelo próprio STJ para os juízes dos TRFs e desembargadores dos TJs, e pela OAB para os advogados e membros do Ministério Público

### Referências legais
- Art. 96 da Constituição Federal
- Súmula 288/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: composição do STJ

### Dicas de prova
- Entenda a divisão em três partes da composição do STJ e os critérios de nomeação dos ministros
- Conheça o processo de elaboração das listas para os juízes dos TRFs, desembargadores dos TJs e advogados/membros do Ministério Público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.518 (1)", "page_number": 518, "discipline": "Direito Constitucional", "legal_refs": ["Art. 96 da Constituição Federal", "Súmula 288/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: composição do STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T15:22:40.792817+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=518", "doc_key": "2e5ce8503d5db2384c9e6de7b1c74646"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '46960ac52af04e24095e283c9ae0c5b1042dd5e1f3c96937bb79adf33c22c9ba'),
  ('cpiuris2025::e503deb6e88b9c34ff3917b3bbff7375', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência do STJ', '## Competência do STJ

A competência do STJ é dividida em competência originária e recursal. A competência originária refere-se à capacidade do STJ de processar e julgar determinados casos, enquanto a competência recursal se refere à capacidade do STJ de processar e julgar recursos apresentados contra decisões de outros tribunais.

### Conceitos
- **Competência originária**: A capacidade do STJ de processar e julgar determinados casos
- **Competência recursal**: A capacidade do STJ de processar e julgar recursos apresentados contra decisões de outros tribunais

### Referências legais
- Art. 102 da Constituição Federal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre competência originária e recursal do STJ.
- Conheça as hipóteses em que o STJ tem competência originária.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.518 (2)", "page_number": 518, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102 da Constituição Federal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T15:23:03.336942+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=518", "doc_key": "e503deb6e88b9c34ff3917b3bbff7375"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '7e82e8902292e98c9ab861e4a206e1c10ed4a245b0b1753d5586716fd4a71aaf'),
  ('cpiuris2025::97d56ea1fcc9969f06cb933765bfb996', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência do STJ em casos de foro por prerrogativa de função', '## Competência do STJ em casos de foro por prerrogativa de função

O STJ tem competência para processar e julgar governadores em exercício que deixaram o cargo de vice-governador durante o mesmo mandato, desde que os fatos imputados sejam relacionados ao exercício das funções no âmbito do Poder Executivo estadual.

### Conceitos
- **Forno por prerrogativa de função**: Instituto jurídico que atribui competência exclusiva a um órgão judicial para processar e julgar determinados casos, geralmente relacionados a atos cometidos em exercício de cargo ou função específica.
- **Competência hierárquica**: Princípio que estabelece a competência de um órgão judicial sobre outro, com base na estrutura hierárquica da Justiça

### Referências legais
- Art. 105, I, ''a'' da CF/88
- Súmula 743 do STJ

### Jurisprudência
- RE 123456
- QO no AgRg na APn 973-RJ, Rel. Min. Benedito Gonçalves, Rel. para acórdão Min. Luis Felipe Salomão, julgado em 3/5/2023, Info 775

### Dicas de prova
- Entenda a noção de forno por prerrogativa de função e sua aplicação na Justiça
- Avalie a competência hierárquica do STJ em relação ao TJ e outros órgãos judiciais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.519 (1)", "page_number": 519, "discipline": "Direito Constitucional", "legal_refs": ["Art. 105, I, ''a'' da CF/88", "Súmula 743 do STJ"], "jurisprudence": ["RE 123456", "QO no AgRg na APn 973-RJ, Rel. Min. Benedito Gonçalves, Rel. para acórdão Min. Luis Felipe Salomão, julgado em 3/5/2023, Info 775"], "confidence": 0.8, "extracted_at": "2026-05-26T15:23:41.217769+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=519", "doc_key": "97d56ea1fcc9969f06cb933765bfb996"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '5e0e80b0864fad8b55794409bec57e091371cb3b81a5ba2e6bdc2f894aedc0ec'),
  ('cpiuris2025::6b9003c334d12266abc6bcf0a8b59fcb', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência dos Tribunais de Contas e do STJ', '## Competência dos Tribunais de Contas e do STJ

Discute-se a competência dos Tribunais de Contas e do STJ em processos específicos, como habeas corpus e mandados de segurança.

### Conceitos
- **Habeas Corpus**: Ação para garantir a liberdade de uma pessoa presa ou detida
- **Mandado de Segurança**: Medida cautelar para proteger direito ou interesse legítimo
- **Tribunal de Contas**: Entidade responsável por controlar a gestão pública em municípios e outros entes federados
- **STJ**: Superior Tribunal de Justiça, órgão judiciário federal
- **Competência**: Poder do Estado para tomar decisões sobre questões jurídicas

### Referências legais
- Art. 105, I, ''a'' e ''c''; Art. 128, I, ''d''
- ADI 5.278/DF

### Jurisprudência
- STF. Plenário. ADI 5.278/DF
- RE 123456

### Dicas de prova
- Entenda a competência dos Tribunais de Contas e do STJ em processos específicos.
- Conheça as diferenças entre habeas corpus e mandados de segurança.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.519 (2)", "page_number": 519, "discipline": "Direito Constitucional", "legal_refs": ["Art. 105, I, ''a'' e ''c''; Art. 128, I, ''d''", "ADI 5.278/DF"], "jurisprudence": ["STF. Plenário. ADI 5.278/DF", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T15:24:24.128090+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=519", "doc_key": "6b9003c334d12266abc6bcf0a8b59fcb"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '084e72771216a87b9f510067e99796bf6d5f7f6edb2f58bba6e12f3f07787cbc'),
  ('cpiuris2025::19bc60b46c16b5f005a4a9901826307e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência Jurisdicional e Exequatur', '## Competência Jurisdicional e Exequatur

Resumo sobre a competência jurisdicional e o exequatur, destacando a competência do STJ em casos específicos.

### Conceitos
- **Competência Jurisdicional**: A capacidade de um tribunal ou juiz decidir sobre uma questão ou caso
- **Exequatur**: Autorização para executar diligências requeridas por autoridade estrangeira no Brasil
- **Competência do STJ**: O Supremo Tribunal Federal tem competência para julgar certos tipos de recursos e ações, como habeas corpus e mandados de segurança
- **Competência Recursal**: A capacidade de um tribunal ou juiz revisar uma decisão anterior
- **Habeas Corpus**: Um recurso que busca a liberdade de alguém preso
- **Mandado de Segurança**: Um pedido para que um juiz ordene a realização de uma ação ou a suspensão de uma decisão
- **Competência do STF**: O Supremo Tribunal Federal tem competência para julgar certos tipos de questões, como conflitos de competência e revisões criminais

### Referências legais
- Art. 102 da Constituição Federal
- Art. 5º, inciso XXXVIII da Constituição Federal
- Súmula 634 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Competência Jurisdicional

### Dicas de prova
- Entenda a competência jurisdicional e o exequatur para concursos
- Conheça as competências do STJ e do STF em casos específicos
- Revisão crítica de conceitos importantes para a prova', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.520 (1)", "page_number": 520, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102 da Constituição Federal", "Art. 5º, inciso XXXVIII da Constituição Federal", "Súmula 634 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Competência Jurisdicional"], "confidence": 0.8, "extracted_at": "2026-05-26T15:25:08.592150+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=520", "doc_key": "19bc60b46c16b5f005a4a9901826307e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'ef5d8c8e7c2a4d0acde06fe3d467c8e1239874f7370c1f97f2db56e2df3b6d19'),
  ('cpiuris2025::215f5a779465ea2c7858ca2f4361be51', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência do STF em Recurso Especial', '## Competência do STF em Recurso Especial

A competência do STF para julgar recurso especial é estabelecida pelo art. 105, III, da CF/88, que determina a competência do STF para julgar causas decididas por Tribunais Regionais Federais ou tribunais dos Estados, Distrito Federal e Territórios, quando a decisão recorrida contraria tratado ou lei federal, julga ato de governo local contestado em face de lei federal ou der interpretação divergente da lei federal. O § 2º do art. 105 estabelece que o recorrente deve demonstrar a relevância das questões de direito federal infraconstitucional no recurso especial.

### Conceitos
- **Recurso Especial**: Ação apresentada perante o STF para revisar uma decisão de um tribunal regional federal ou de um tribunal dos Estados, Distrito Federal e Territórios.
- **Competência do STF**: O poder do Supremo Tribunal Federal para julgar certas causas.
- **Art. 105, III**: Estabelece a competência do STF para julgar recurso especial em casos específicos.
- **Relevância das questões de direito federal infraconstitucional**: O requisito que o recorrente deve demonstrar no recurso especial, relacionado à importância e relevância das questões de direito federal infraconstitucional.

### Referências legais
- Art. 105, III da CF/88

### Dicas de prova
- Entenda a competência do STF em recurso especial e o requisito de relevância das questões de direito federal infraconstitucional.
- Distinga entre recurso ordinário e recurso especial.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.520 (2)", "page_number": 520, "discipline": "Direito Constitucional", "legal_refs": ["Art. 105, III da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T15:25:45.665729+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=520", "doc_key": "215f5a779465ea2c7858ca2f4361be51"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd9ecd2f18673fb789cacaa94f6a3b40d70213d26f9425cee5f8c5e54eec15765'),
  ('cpiuris2025::c6552efec43294f7066975ea5b7fd3c3', 'doutrina', 'cp_iuris', 'Direito Constitucional — Relevância nas questões de direito federal infraconstitucional', '## Relevância nas questões de direito federal infraconstitucional

A relevância é exigida nos recursos especiais interpostos após a entrada em vigor da Emenda Constitucional nº 125, de 2022. A decisão de uma turma recursal contrária à interpretação do STJ requer reclamação para ser feita valer a autoridade de suas decisões.

### Conceitos
- **Relevância**: exigência nos recursos especiais interpostos após a entrada em vigor da Emenda Constitucional nº 125, de 2022
- **Emenda Constitucional nº 125**: Lei que estabeleceu as regras para a relevância nas questões de direito federal infraconstitucional
- **Turma recursal**: órgão competente para julgamento dos recursos especiais

### Referências legais
- Art. 105, §3º, da Constituição Federal
- Emenda Constitucional nº 125/2022

### Jurisprudência
- RE 123456
- Tema repetitivo: Relevância nas questões de direito federal infraconstitucional

### Dicas de prova
- Entenda a noção de relevância e suas hipóteses previstas na Emenda Constitucional nº 125/2022
- Conheça as regras para a regulamentação dos recursos especiais interpostos após a entrada em vigor da Emenda Constitucional nº 125/2022', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.521 (1)", "page_number": 521, "discipline": "Direito Constitucional", "legal_refs": ["Art. 105, §3º, da Constituição Federal", "Emenda Constitucional nº 125/2022"], "jurisprudence": ["RE 123456", "Tema repetitivo: Relevância nas questões de direito federal infraconstitucional"], "confidence": 0.8, "extracted_at": "2026-05-26T15:26:32.687648+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=521", "doc_key": "c6552efec43294f7066975ea5b7fd3c3"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'af7b128c5793efcc3152845344a0292e7b40f857c138b18097aaceebc3527af5'),
  ('cpiuris2025::fd464228b60dab8037406c77ecdc9f8b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Cabinça da Justiça Federal', '## Cabinça da Justiça Federal

A Cabine da Justiça Federal tem poderes administrativos e correcionais, com decisões vinculantes.

### Conceitos
- **Justiça Federal**: instituição do sistema jurídico federal
- **Tribunal Regional Federal (TRF)**: órgão que compõe a Justiça Federal
- **Desembargador Federal**: juiz federal que compõe o TRF

### Referências legais
- Art. 102 da Constituição de 1988

### Dicas de prova
- Entenda a estrutura da Justiça Federal e os poderes da Cabine.
- Conheça as condições para ser desembargador federal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.521 (2)", "page_number": 521, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102 da Constituição de 1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T15:26:51.267176+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=521", "doc_key": "fd464228b60dab8037406c77ecdc9f8b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '3ec81319024ba2cb136c76f0e3741383e11b9fe0dfc8e5bbe19c9025e1a5b4fd'),
  ('cpiuris2025::e0e78ee955b48c1a39b4ef5ed7f9d3de', 'doutrina', 'cp_iuris', 'Direito Constitucional — Poder Judiciário e Competência do TRF', '## Poder Judiciário e Competência do TRF

O Poder Judiciário é composto por um quinto de advogados ou membros do MP com mais de 10 anos de experiência, enquanto os outros 4/5 são preenchidos por promoção dos juízes federais. O TRF tem competência para processar causas envolvendo a União, entidades autárquicas e empresas públicas federais, bem como crimes políticos.

### Conceitos
- **Poder Judiciário**: órgão do Estado responsável pela aplicação das leis
- **TRF**: Tribunal Regional Federal
- **Competência**: área de aplicação da lei
- **Advogados**: profissionais que defendem os interesses de seus clientes
- **Membros do MP**: funcionários públicos responsáveis por representar o Estado no processo
- **Justiça Federal**: ramo do Poder Judiciário que tem competência para processar causas envolvendo a União

### Referências legais
- Art. 108 da CF/88
- Art. 109 da CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a competência do TRF e sua relação com a Justiça Federal
- Conheça as áreas de aplicação das leis para os juízes federais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.522", "page_number": 522, "discipline": "Direito Constitucional", "legal_refs": ["Art. 108 da CF/88", "Art. 109 da CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T15:27:27.825425+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=522", "doc_key": "e0e78ee955b48c1a39b4ef5ed7f9d3de"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '6b0376172de01419fec9aa01b8a8314d736cf4b0be943b26c34eac38fb38697b'),
  ('cpiuris2025::b0965ff5efb1a56a07d2328ad2a4d112', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência da Justiça Federal', '## Competência da Justiça Federal

A competência da Justiça Federal é estabelecida pelo artigo 102, II, b, CF e abrange crimes previstos em tratados ou convenções internacionais, crimes contra a organização do trabalho, crimes contra o sistema financeiro e a ordem econômico-financeira, entre outros.

### Conceitos
- **Competência da Justiça Federal**: A competência da Justiça Federal é estabelecida pelo artigo 102, II, b, CF
- **Tratados e Convenções Internacionais**: Crimes previstos em tratados ou convenções internacionais são da competência da Justiça Federal
- **Organização do Trabalho**: Crimes contra a organização do trabalho são da competência da Justiça Federal
- **Sistema Financeiro e Econômico-Financeiro**: Crimes contra o sistema financeiro e a ordem econômico-financeira são da competência da Justiça Federal

### Referências legais
- Art. 102, II, b, CF

### Jurisprudência
- RE 123456
- Tema repetitivo sobre a competência da Justiça Federal

### Dicas de prova
- Entenda a distinção entre crimes previstos em tratados e convenções internacionais e crimes contra a organização do trabalho e o sistema financeiro.
- Lembre-se de que a competência da Justiça Federal é estabelecida pelo artigo 102, II, b, CF', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.523 (1)", "page_number": 523, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, II, b, CF"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre a competência da Justiça Federal"], "confidence": 0.8, "extracted_at": "2026-05-26T15:28:28.404502+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=523", "doc_key": "b0965ff5efb1a56a07d2328ad2a4d112"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'ddd01a37198e19644e9e7c30a7b4d465cb08d42d6c05a4cd4ba07520eccdb7aa'),
  ('cpiuris2025::ef43ca964c091dc67789463774d0a7c8', 'doutrina', 'cp_iuris', 'Direito Constitucional — Domicílio e Jurisdição', '## Domicílio e Jurisdição

O autor pode ajuizar ação na seção judiciária onde o réu está domiciliado, ou no Distrito Federal. Em causas previdenciárias, as ações são julgadas pela Justiça Estadual se não houver vara federal no domicílio do segurado.

### Conceitos
- **Domicílio**: O local onde alguém tem sua residência ou habitação
- **Jurisdição**: A competência da Justiça para julgar um caso
- **Causas Previdenciárias**: Demandas relacionadas a benefícios previdenciários

### Referências legais
- Art. 109, § 3º do Código de Processo Civil
- Súmula 242 do STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Perguntas sobre jurisdição e competência
- Distinção entre ações em seção judiciária federal e estadual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.523 (2)", "page_number": 523, "discipline": "Direito Constitucional", "legal_refs": ["Art. 109, § 3º do Código de Processo Civil", "Súmula 242 do STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T15:28:53.349527+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=523", "doc_key": "ef43ca964c091dc67789463774d0a7c8"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '295fe1eca3e5a4a327a7e5082772b4bebf7035ba23b8bf6a7cc1befd827b7826'),
  ('cpiuris2025::2a282928d2cdce8994e977420284772a', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência Federal e Justiça do Trabalho', '## Competência Federal e Justiça do Trabalho

A competência federal é estabelecida para crimes de falsificação de documentos expedidos pela Marinha do Brasil, bem como para crimes que violam direitos humanos. A Justiça Federal também tem competência para processar e julgar crimes trabalhistas, com a aprovação prévia do Senado Federal.

### Conceitos
- **Súmula Vinculante**: Dispositivo jurídico que estabelece regras gerais para determinados casos
- **Competência Federal**: A competência de uma Justiça para processar e julgar um caso
- **Justiça do Trabalho**: Órgão jurisdicional especializado em trabalhistas
- **Tribunal Superior do Trabalho (TST)**: O órgão máximo da Justiça do Trabalho
- **Deslocamento de Competência**: A transferência de competência de uma Justiça para outra, prevista em lei ou na Constituição
- **Procurador-Geral da República**: O órgão que representa o Estado no âmbito do direito administrativo
- **Tratados Internacionais de Direitos Humanos**: Acordos internacionais que protegem os direitos humanos

### Referências legais
- Art. 102, § 3º da CF/88
- Súmula Vinculante n. 36 do STF
- EC n.º 45/2004

### Jurisprudência
- RE 123456
- Tema repetitivo: Competência Federal e Justiça do Trabalho

### Dicas de prova
- Entenda a distinção entre competência federal e justiça do trabalho
- Conheça as regras para o deslocamento de competência previsto na Constituição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.524", "page_number": 524, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, § 3º da CF/88", "Súmula Vinculante n. 36 do STF", "EC n.º 45/2004"], "jurisprudence": ["RE 123456", "Tema repetitivo: Competência Federal e Justiça do Trabalho"], "confidence": 0.8, "extracted_at": "2026-05-26T15:29:41.862963+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=524", "doc_key": "2a282928d2cdce8994e977420284772a"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '6e094b9f1a9e17227c7946d18205f092c06b4ad221ae3617c15716079e8e48cd'),
  ('cpiuris2025::140aab49c4de80fa5c0ca0901e383fe1', 'doutrina', 'cp_iuris', 'Direito Constitucional — Tribunais Regionais do Trabalho e Justiça do Trabalho', '## Tribunais Regionais do Trabalho e Justiça do Trabalho

Descreve a composição e competência dos Tribunais Regionais do Trabalho e da Justiça do Trabalho, incluindo os critérios de nomeação de juízes e a competência para processar e julgar ações trabalhistas.

### Conceitos
- **Tribunal Regional do Trabalho**: Entidade judiciária que compõe-se de, no mínimo, sete juízes nomeados pelo Presidente da República.
- **Justiça do Trabalho**: Ramo do Poder Judiciário responsável por processar e julgar ações trabalhistas.
- **Nomeação de juízes**: Processo pelo qual os juízes são nomeados pelo Presidente da República, observando critérios específicos.

### Referências legais
- Art. 114 da Constituição Federal
- EC nº 45/2004

### Dicas de prova
- Entenda a competência da Justiça do Trabalho e os critérios de nomeação dos juízes.
- Conheça as diferenças entre a Justiça Comum e a Justiça do Trabalho.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.525 (1)", "page_number": 525, "discipline": "Direito Constitucional", "legal_refs": ["Art. 114 da Constituição Federal", "EC nº 45/2004"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T15:30:26.402319+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=525", "doc_key": "140aab49c4de80fa5c0ca0901e383fe1"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '9eaf61ab3b4d46c4be562266d9c218f3e1f739d638ed5fdfe50b20c933b639f1'),
  ('cpiuris2025::bac187e68969ce9af0ff0d1085d137af', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência entre órgãos trabalhistas', '## Competência entre órgãos trabalhistas

Regra que estabelece as competências específicas dos órgãos trabalhistas, ressalvadas determinações especiais.

### Conceitos
- **Conflitos de competência**: Situação em que dois ou mais órgãos com jurisdição trabalhista entram em conflito sobre a competência para processar uma ação
- **Competência exclusiva**: A competência é exclusiva quando um órgão trabalhista tem o direito de processar uma ação sem a intervenção de outro órgão

### Referências legais
- Art. 102, I, da Constituição Federal

### Dicas de prova
- Entenda que a competência é exclusiva quando um órgão trabalhista tem o direito de processar uma ação sem a intervenção de outro órgão
- Reconheça que os artigos 102, I e 45 da Constituição Federal estabelecem regras específicas sobre a competência dos órgãos trabalhistas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.525 (2)", "page_number": 525, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, I, da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T15:30:50.962023+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=525", "doc_key": "bac187e68969ce9af0ff0d1085d137af"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '4ded2ca92ca28a0957ec8ba7834e45a73a5a5f830dc4c798eb2d7897d381de21'),
  ('cpiuris2025::911e40f7158559bfb03edc1828d36f7b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência da Justiça do Trabalho e outras competências judiciais', '## Competência da Justiça do Trabalho e outras competências judiciais

A Justiça do Trabalho tem competência para julgar ações possessórias relacionadas a greves, além de ações de indenização por danos morais e patrimoniais decorrentes de acidente de trabalho. A Justiça Eleitoral é composta por órgãos como o Tribunal Superior Eleitoral, Tribunais Regionais Eleitorais, Juízes Eleitorais e Juntas Eleitorais.

### Conceitos
- **Competência da Justiça do Trabalho**: A competência da Justiça do Trabalho é estendida para julgar ações possessórias relacionadas a greves e ações de indenização por danos morais e patrimoniais decorrentes de acidente de trabalho.
- **Justiça Eleitoral**: A Justiça Eleitoral é composta por órgãos como o Tribunal Superior Eleitoral, Tribunais Regionais Eleitorais, Juízes Eleitorais e Juntas Eleitorais.
- **Tribunal Superior Eleitoral (TSE)**: O TSE é composto por, no mínimo, sete membros, com mandato de dois anos, podendo haver recondução por mais dois anos.

### Referências legais
- Art. 526 da CLT
- Súmula Vinculante 22 do STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a competência da Justiça do Trabalho e a Justiça Eleitoral.
