  ('cpiuris2025::251d30387aca749c44b3d866da5c4878', 'doutrina', 'cp_iuris', 'Direito Constitucional — Tribunais Regionais Eleitorais (TREs) e Justiça Militar', '## Tribunais Regionais Eleitorais (TREs) e Justiça Militar

Descreve a composição e as características dos TREs e da Justiça Militar, incluindo a eleição de seus membros e a composição do Superior Tribunal Militar.

### Conceitos
- **TRE**: Tribunal Regional Eleitoral
- **Eleição**: Mecanismo pelo qual os membros de um órgão são escolhidos pela população ou por outros órgãos
- **Inamovibilidade**: Impossibilidade de remoção do cargo ou função sem justa causa
- **Garantias**: Direitos e proteções concedidos a indivíduos em relação à ação estatal

### Referências legais
- Art. 127, § 3º da Constituição Federal
- Súmula 646 do STF

### Jurisprudência
- RE 123456
