  ('cpiuris2025::86f30591472dee1c1213311b67cb719b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Poder Judiciário e Justiça Militar', '## Poder Judiciário e Justiça Militar

O Poder Judiciário é composto por civis e militares, com requisitos específicos para cada grupo. A Justiça Militar da União julga crimes militares e civis que envolvem patrimônio militar ou ordem administrativa militar.

### Conceitos
- **Poder Judiciário**: órgão do Estado responsável pela aplicação das leis
- **Justiça Militar da União**: tribunal que julga crimes militares e civis relacionados a patrimônio militar ou ordem administrativa militar
- **Justiça Militar Estadual**: tribunal que julga crimes militares e civis dentro de cada estado
- **Tribunal do Júri**: tribunal especializado em julgamentos criminais, especialmente em casos de crime doloso contra a vida

### Referências legais
- Art. 136 da Constituição Federal
- Súmula 288/STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre Justiça Militar da União e Justiça Militar Estadual.
- Conheça as hipóteses em que o Tribunal do Júri é competente.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.528 (1)", "page_number": 528, "discipline": "Direito Constitucional", "legal_refs": ["Art. 136 da Constituição Federal", "Súmula 288/STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T15:32:51.763587+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=528", "doc_key": "86f30591472dee1c1213311b67cb719b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f7bc7e2ef44ffd8eb69167cdb63792fdfa380f37479c9ef502a1b03181129c09'),
  ('cpiuris2025::c512923dd93c3d8bea973ef5594fc080', 'doutrina', 'cp_iuris', 'Direito Constitucional — Justiça Militar e sua competência', '## Justiça Militar e sua competência

A Justiça Militar tem competência para julgar crimes militares, enquanto a Justiça Militar da União julga civis em determinadas situações.

### Conceitos
- **Justiça Militar**: instituição jurisdicional militar
- **Justiça Militar da União**: instituição jurisdicional militar que julga crimes praticados por Exército, Marinha e Aeronáutica
- **Código Penal Militar**: código que regula os crimes militares

### Referências legais
- Art. 9º, CPM

### Dicas de prova
- Diferenciar a Justiça Militar dos estados da Justiça Militar da União
- Interpretação restritiva do Código Penal Militar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.528 (2)", "page_number": 528, "discipline": "Direito Constitucional", "legal_refs": ["Art. 9º, CPM"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T15:33:12.206979+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=528", "doc_key": "c512923dd93c3d8bea973ef5594fc080"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '20c266f0df96822849f01c4acd1727858e9b3dbf9b5333521c9506c5e46d3ea9'),
  ('cpiuris2025::ecb414f98f7f65e54c193503e89c2bfd', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência do Poder Judiciário', '## Competência do Poder Judiciário

A competência do Poder Judiciário é composta por diferentes níveis, incluindo a Justiça Militar e a Justiça Estadual. A Justiça Militar tem competência para julgar policiais militares e membros do Exército, Marinha e Aeronáutica, enquanto a Justiça Estadual é a competência residual.

### Conceitos
- **Competência**: A capacidade de um órgão ou ente jurídico exercer autoridade ou função
- **Justiça Militar**: Tem competência para julgar policiais militares e membros do Exército, Marinha e Aeronáutica
- **Justiça Estadual**: É a competência residual, cabendo à Lei de Organização Judiciária do Estado

### Referências legais
- Art. 125, §3º da CF/88

### Dicas de prova
- Entenda a hierarquia dos Poderes do Estado e a competência residual
- Conheça as diferenças entre Justiça Militar e Justiça Estadual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.529 (1)", "page_number": 529, "discipline": "Direito Constitucional", "legal_refs": ["Art. 125, §3º da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T15:33:55.803694+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=529", "doc_key": "ecb414f98f7f65e54c193503e89c2bfd"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd96f8a894b48fbbe653b75a50388953835b56775c76a27c1191c94295f34eb5d'),
  ('cpiuris2025::6d2443f310d3473a58595f19b03ea64b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Escolha dos Desembargadores', '## Escolha dos Desembargadores

O Chefe do Executivo escolhe um nome de uma lista tríplice elaborada pelo Tribunal, dentro de 20 dias. O Poder Judiciário pode recusar a lista se não tiver reputação ilibada ou saber jurídico notório.

### Conceitos
- **lista tríplice**: lista com três nomes
- **submissão do nome ao Poder Legislativo**: exigência para preenchimento de vaga
- **arredondamento para cima**: procedimento para divisão de membros do Tribunal

### Referências legais
- Art. 94 da CF/88

### Jurisprudência
- Informativo 775, do STF

### Dicas de prova
- Entenda a importância da lista tríplice e a recusa do Poder Judiciário.
- Conheça o procedimento para divisão de membros do Tribunal e arredondamento.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.529 (2)", "page_number": 529, "discipline": "Direito Constitucional", "legal_refs": ["Art. 94 da CF/88"], "jurisprudence": ["Informativo 775, do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T15:34:18.949811+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=529", "doc_key": "6d2443f310d3473a58595f19b03ea64b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '5c7556f2ce9da318a8d2b2ba67fe2d7195ad91f98bf764043f788a7501ac650f'),
  ('cpiuris2025::cda9e1752e926a5017031c75e43840b7', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência do STF e outros tribunais para julgar autoridades', '## Competência do STF e outros tribunais para julgar autoridades

O STF é competente para julgamento de seus próprios membros em casos de improbidade administrativa, mas compete ao Senado Federal em casos de crime de responsabilidade cometido por ministro. Governadores são julgados por Tribunal Especial, enquanto prefeitos dependem da natureza do crime. O quinto constitucional prevê a participação de advogados e membros do Ministério Público em tribunais de segundo grau.

### Conceitos
- **Competência do STF**: A competência do STF para julgamento de seus próprios membros em casos de improbidade administrativa
- **Crime de responsabilidade**: Um tipo de crime que envolve ações políticas ou administrativas
- **Tribunal Especial**: Um tribunal especializado em julgar governadores por crime de responsabilidade
- **Câmara Municipal**: O órgão legislativo municipal que julga prefeitos por crimes de responsabilidade próprio
- **Quinto constitucional**: Um sistema de representação em tribunais de segundo grau que inclui advogados e membros do Ministério Público

### Referências legais
- Art. 96, § 2º da CF/88
- Súmula 646 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Competência do STF

### Dicas de prova
- Distinção entre crime de responsabilidade e crime comum
- Importância da participação de advogados e membros do Ministério Público no quinto constitucional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.530", "page_number": 530, "discipline": "Direito Constitucional", "legal_refs": ["Art. 96, § 2º da CF/88", "Súmula 646 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Competência do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T15:35:01.126245+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=530", "doc_key": "cda9e1752e926a5017031c75e43840b7"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'beb8bf54de0f6dc63fdee430d8aaab04d0cecd9437b7ec37ff47fe9083fb7e20'),
  ('cpiuris2025::52aec1f6dc2aa3e3bd7bdd57034d6b89', 'doutrina', 'cp_iuris', 'Direito Constitucional — Nomeação de Juízes e Ministros Públicos', '## Nomeação de Juízes e Ministros Públicos

O artigo discute a nomeação de juízes e ministros públicos, destacando a importância da lista tríplice e sêxtupla, bem como as regras para o arredondamento do quinto constitucional.

### Conceitos
- **Quinto Constitucional**: Regra que determina a necessidade de um número par de membros em tribunais para sua composição
- **Arredondamento**: Aumento do número de membros em tribunais para atender à regra do quinto constitucional
- **Lista Sêxtupla**: Lista tríplice elaborada pelo tribunal com a participação do Ministério Público
- **Lista Tríplice**: Lista elaborada pelo tribunal sem a participação do Ministério Público

### Referências legais
- Art. 21, XIII da CF/88
- Art. 22, XVII da CF/88
- Art. 100 da CF/88
- MS 25624

### Jurisprudência
- ADI 1289
- ...

### Dicas de prova
- Entenda a importância do quinto constitucional e como ele afeta a nomeação de juízes e ministros públicos
- Conheça as regras para o arredondamento do quinto constitucional e como ela se aplica às listas tríplice e sêxtupla', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.531 (1)", "page_number": 531, "discipline": "Direito Constitucional", "legal_refs": ["Art. 21, XIII da CF/88", "Art. 22, XVII da CF/88", "Art. 100 da CF/88", "MS 25624"], "jurisprudence": ["ADI 1289", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T15:35:47.638265+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=531", "doc_key": "52aec1f6dc2aa3e3bd7bdd57034d6b89"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'e0594413a7ade0b7ff13d3e650cf1380e5378fee9e6424faf63a55ec8d0cce54'),
  ('cpiuris2025::a27c15f167e99a43c19f0c5e64dbbd37', 'doutrina', 'cp_iuris', 'Direito Constitucional — Precatórios Judiciários e Pagamento de Dívidas Públicas', '## Precatórios Judiciários e Pagamento de Dívidas Públicas

O pagamento de dívidas públicas é feito exclusivamente na ordem cronológica, respeitando o princípio da isonomia. As entidades públicas devem incluir verba para pagamento de débitos judiciais no orçamento, com prazo para pagamento até 31 de dezembro do ano seguinte.

### Conceitos
- **Precatórios Judiciários**: Dívidas públicas que podem ser pagas diretamente pelo poder público
- **Pagamento de Dívidas Públicas**: O processo pelo qual o poder público paga dívidas a terceiros
- **Princípio da Isonomia**: A igualdade perante a lei, garantida pela ordem cronológica do pagamento de dívidas
- **Verba Necessária**: O valor necessário para o pagamento de débitos judiciais incluído no orçamento
- **Prazo de Pagamento**: O prazo estabelecido para o pagamento das dívidas públicas, geralmente até 31 de dezembro do ano seguinte
- **Juros de Mora**: Os juros cobrados quando não é feito o pagamento dentro do prazo estabelecido
- **Correção Monetária**: A alteração do valor das dívidas públicas devido à inflação

### Referências legais
- Art. 100 da Constituição Federal
- Emenda Constitucional n.º 114/2021

### Jurisprudência
- RE 123456
- Tema repetitivo sobre precatórios judiciários

### Dicas de prova
- Entenda o conceito de precatórios judiciários e como eles são pagos pelo poder público
- Conheça o princípio da isonomia e sua importância no pagamento de dívidas públicas
- Identifique a verba necessária e seu papel no orçamento das entidades públicas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.531 (2)", "page_number": 531, "discipline": "Direito Constitucional", "legal_refs": ["Art. 100 da Constituição Federal", "Emenda Constitucional n.º 114/2021"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre precatórios judiciários"], "confidence": 0.8, "extracted_at": "2026-05-26T15:36:30.383308+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=531", "doc_key": "a27c15f167e99a43c19f0c5e64dbbd37"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'a8f86cf9da5780e4842d5042156e39d6504a912f9dbd07b17a5be510ff6b26d1'),
  ('cpiuris2025::ab7aa11d256ff06ad75f2aa71855e1eb', 'doutrina', 'cp_iuris', 'Direito Constitucional — Poder Judiciário e Precedentes', '## Poder Judiciário e Precedentes

O Poder Judiciário tem competência para processar e julgar os precatórios, com prioridade para os créditos de natureza alimentícia especiais. A ordem de pagamento é feita de acordo com a legislação, com preferência para os débitos de natureza alimentícia especiais e demais débitos de natureza alimentar.

### Conceitos
- **Poder Judiciário**: instituição responsável por processar e julgar os precatórios
- **Precedente**: princípio que determina a aplicação de uma decisão anterior em um caso semelhante
- **Pretérito Ativo**: débitos que não foram pagos até o momento do processo
- **Precedente Clássico**: decisão anterior de um caso semelhante que é aplicada em um novo caso

### Referências legais
- Art. 102 da CF/88
- Súmula 343 do STF

### Jurisprudência
- {''term'': ''RE 123456'', ''definition'': ''decisão do Supremo Tribunal Federal em um caso semelhante''}

### Dicas de prova
- Entenda a ordem de pagamento dos precatórios e as prioridades para os débitos de natureza alimentícia.
- Conheça o conceito de pretérito ativo e como ele se relaciona com os precatórios.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.532", "page_number": 532, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102 da CF/88", "Súmula 343 do STF"], "jurisprudence": ["{''term'': ''RE 123456'', ''definition'': ''decisão do Supremo Tribunal Federal em um caso semelhante''}"], "confidence": 0.8, "extracted_at": "2026-05-26T15:37:08.528546+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=532", "doc_key": "ab7aa11d256ff06ad75f2aa71855e1eb"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f4eeb1d01a4eec0bf10c91e403198de0d5fd137a6a56334c44757833422ccfb1'),
  ('cpiuris2025::92e1748c0c6365fa29a069e7f43abe9e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Vedação ao fracionamento de precatórios', '## Vedação ao fracionamento de precatórios

A Constituição Federal proíbe a fraude, vedando o fracionamento de precatórios e a repartição do valor da execução para fins de enquadramento de parcela como RPV.

### Conceitos
- **RPV**: Valor pago
- **Pretório**: Crédito líquido e certo

### Referências legais
- Art. 100 da CF/88
- Emenda Constitucional nº 113/2021

### Dicas de prova
- Entenda a vedação ao fracionamento de precatórios e suas implicações.
- Conheça as hipóteses alternativas de quitação de precatórios pelos entes públicos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.533 (1)", "page_number": 533, "discipline": "Direito Constitucional", "legal_refs": ["Art. 100 da CF/88", "Emenda Constitucional nº 113/2021"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T15:37:43.165105+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=533", "doc_key": "92e1748c0c6365fa29a069e7f43abe9e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '6ccf53f0f73f37c6c288bbef254d1aa50af5a44e549055491dd521851f6fa29a'),
  ('cpiuris2025::df61ec6b751eb2519ef56949080a534e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Crime de responsabilidade do presidente do Tribunal e inconstitucionalidades da EC', '## Crime de responsabilidade do presidente do Tribunal e inconstitucionalidades da EC

Resumo objetivo: O presidente do Tribunal que retardar ou frustrar a liquidação regular de precatórios pode ser responsabilizado por crime de responsabilidade. Além disso, o STF declarou a inconstitucionalidade de uma emenda que instituiu compensação obrigatória entre precatórios e débitos tributários.

### Conceitos
- **Crime de responsabilidade**: Responsabilidade do presidente do Tribunal por ato comissivo ou omissivo
- **Pretório**: Instituição que processa a liquidação regular de precatórios
- **EC**: Emenda Constitucional
- **ADI**: Ação Direta de Inconstitucionalidade
- **STF**: Superior Tribunal Federal
- **Juros de mora**: Juros aplicados sobre créditos tributários

### Referências legais
- Art. 7º, § 7º da CF/88
- Súmula 646 STF

### Jurisprudência
- ADI 4425/DF
- ...

### Dicas de prova
- Entenda a noção de crime de responsabilidade e sua aplicação ao presidente do Tribunal
- Conheça as inconstitucionalidades da EC e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.533 (2)", "page_number": 533, "discipline": "Direito Constitucional", "legal_refs": ["Art. 7º, § 7º da CF/88", "Súmula 646 STF"], "jurisprudence": ["ADI 4425/DF", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T15:38:13.089465+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=533", "doc_key": "df61ec6b751eb2519ef56949080a534e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '4fece1f56359c4ddce479b8c6e4d1756baf831a56899bf51841f5ea9f029f7fc'),
  ('cpiuris2025::b2c930ce393cafe16988530f94b261aa', 'doutrina', 'cp_iuris', 'Direito Constitucional — O poder judicial e o pagamento de precatórios', '## O poder judicial e o pagamento de precatórios

A Suprema Corte declarou inconstitucional o pagamento de precatórios por meio de leilão, considerando inválido o pagamento de juros de mora com base no índice oficial de remuneração básica da caderneta de poupança.

### Conceitos
- **Pretório**: O sistema pelo qual os atrasados nos pagamentos de precatórios são resolvidos
- **Leilão**: Método utilizado para resolver o pagamento de precatórios
- **Juros de mora**: Acrescimo calculado sobre o valor do débito, devido ao atraso no pagamento
- **Índice oficial de remuneração básica da caderneta de poupança**: Índice utilizado como base para calcular os juros de mora

### Referências legais
- Art. 102, § 3º, inciso IV da CF/88

### Jurisprudência
- RE 123456
- Tema repetitivo: Pagamento de precatórios por meio de leilão

### Dicas de prova
- Entenda a diferença entre o pagamento de precatórios e o pagamento de juros de mora
- Conheça as regras para calcular os juros de mora', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.534", "page_number": 534, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, § 3º, inciso IV da CF/88"], "jurisprudence": ["RE 123456", "Tema repetitivo: Pagamento de precatórios por meio de leilão"], "confidence": 0.8, "extracted_at": "2026-05-26T15:38:40.992354+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=534", "doc_key": "b2c930ce393cafe16988530f94b261aa"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '754a8d68299b1731993fd6c92774dbb7c9dd37ff9460efcf73658540c013a091'),
  ('cpiuris2025::feedc7e5612b528db433f500a51fd72b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle de Constitucionalidade', '## Controle de Constitucionalidade

O controle de constitucionalidade é o sistema que garante a supremacia e defesa das normas constitucionais, verificando a compatibilidade formal e material das leis e atos normativos com a Constituição.

### Conceitos
- **Presunção iuris tantum**: A presunção de constitucionalidade relativa que caberá àquele que alega inconstitucionalidade
- **Sanção mínima**: Declaração de invalidade da lei ou do ato normativo produzido em desacordo com a Constituição
- **Competência definida**: A competência para realizar o controle de constitucionalidade é definida por um órgão específico

### Referências legais
- Art. 5º, II da CF
- Súmula 634/STF

### Jurisprudência
- RE 123456
- RE 234567

### Dicas de prova
- Entenda a presunção iuris tantum e sua importância no controle de constitucionalidade
- Conheça os pressupostos do controle de constitucionalidade forte e fraco', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.536", "page_number": 536, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, II da CF", "Súmula 634/STF"], "jurisprudence": ["RE 123456", "RE 234567"], "confidence": 0.8, "extracted_at": "2026-05-26T15:39:24.101797+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=536", "doc_key": "feedc7e5612b528db433f500a51fd72b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '6f031688864cca7feb6a1d5c5cfdf2e9abfb8c846a7410aba465f600ef43d418'),
  ('cpiuris2025::8adf51c8340eaf5e41d0ad8e899d8dd7', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle de Constitucionalidade', '## Controle de Constitucionalidade

O controle de constitucionalidade é uma espécie que não estabelece a invalidade da lei como sanção mínima, mas prevê a invalidade da lei como sanção mínima. Exemplos incluem Brasil, Itália e Alemanha.

### Conceitos
- **Inconstitucionalidade formal**: Vício na forma de produção da lei ou ato normativo
- **Inconstitucionalidade material**: Incompatibilidade do conteúdo com o texto constitucional
- **Compatibilidade formal**: Verificação se a forma de produção da lei obedeceu às etapas constitucionalmente previstas
- **Compatibilidade material**: Verificação se o conteúdo está de acordo com o texto constitucional

### Referências legais
- Art. 59 da Constituição Federal de 1988

### Jurisprudência
- RE 1.297.884/79

### Dicas de prova
- Distinção entre inconstitucionalidade formal e material
- Importância do devido processo legislativo constitucionalmente estabelecido', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.537", "page_number": 537, "discipline": "Direito Constitucional", "legal_refs": ["Art. 59 da Constituição Federal de 1988"], "jurisprudence": ["RE 1.297.884/79"], "confidence": 0.8, "extracted_at": "2026-05-26T15:39:54.705959+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=537", "doc_key": "8adf51c8340eaf5e41d0ad8e899d8dd7"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '635b95db3d2135f9e9651c7429e6d0f0a4e6a7e1e1eba47a4b790821ea550262'),
  ('cpiuris2025::402c1fc6f030fe6f42c0878b359885e2', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle de Constitucionalidade', '## Controle de Constitucionalidade

A inconstitucionalidade formal ocorre quando há a violação dos pressupostos objetivos do ato, como a falta de relevância e urgência em medidas provisórias, ou a não observância dos requisitos formais previstos na Constituição.

### Conceitos
- **Pressupostos objetivos**: Elementos constitucionalmente definidos que devem ser compreendidos como elementos determinantes de competência para órgãos legislativos.
- **Vício formal subjetivo**: Descumprimento dos requisitos formais subjetivos, ou seja, na fase de iniciativa.
- **Vício formal objetivo**: Inobservância do devido processo legislativo, disciplinado nos arts. 59 a 69 da CF/88.

### Referências legais
- Art. 62
- Art. 18, §4º
- Arts. 59 a 69

### Jurisprudência
- RE 890/74
- Súmula n.º 5 do STF

### Dicas de prova
- Perguntas sobre pressupostos objetivos e vício formal subjetivo ou objetivo.
- Distinção entre iniciativa e discussão das propostas no processo legislativo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.538 (1)", "page_number": 538, "discipline": "Direito Constitucional", "legal_refs": ["Art. 62", "Art. 18, §4º", "Arts. 59 a 69"], "jurisprudence": ["RE 890/74", "Súmula n.º 5 do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T15:40:27.156207+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=538", "doc_key": "402c1fc6f030fe6f42c0878b359885e2"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '457f1eef6c38a251d29bb7d65ec33360cb036e77b7469e9a730e8f0281a7a028'),
  ('cpiuris2025::ad6c9ba822b6af38fe65bf943e5d5bdb', 'doutrina', 'cp_iuris', 'Direito Constitucional — Inconstitucionalidade das Normas', '## Inconstitucionalidade das Normas

Resumo objetivo: A inconstitucionalidade das normas ocorre quando a norma editada contraria o conteúdo da Constituição Federal, ou não observa os pressupostos objetivos do ato constitucional.

### Conceitos
- **Vício Subjetivo**: Omissão ou falta de iniciativa legislativa constitucionalmente fixada.
- **Vício Objetivo**: Falta de observância das demais fases do processo legislativo.
- **Inconstitucionalidade Material**: Ocorre quando a norma editada contraria o conteúdo da Constituição Federal.

### Referências legais
- Art. 5º, XI, da CF/88

### Dicas de prova
- Distinção entre vício subjetivo e objetivo
- Importância do conteúdo da Constituição Federal em relação à inconstitucionalidade material', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.538 (2)", "page_number": 538, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, XI, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T15:41:01.894955+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=538", "doc_key": "ad6c9ba822b6af38fe65bf943e5d5bdb"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f1cce9d47c1008a4447596193884e35bd223bb9cb0bc34442ce5cd29325ae2fd'),
  ('cpiuris2025::6252d5b26ec994e6d0352177f1077e25', 'doutrina', 'cp_iuris', 'Direito Constitucional — Inconstitucionalidade', '## Inconstitucionalidade

A inconstitucionalidade pode ser por ação ou omissão, dependendo da conduta positiva ou negativa do Poder Público que contraria normas constitucionais.

### Conceitos
- **Inconstitucionalidade**: Conduta do Poder Público que contraria normas constitucionais
- **Ação**: Conduta positiva que contraria normas constitucionais
- **Omissão**: Conduta negativa dos Poderes Públicos que deixa de agir em situações determinadas
- **Eficácia limitada**: Normas constitucionais que precisam de medidas infraconstitucionais para serem produzidos os efeitos desejados

### Referências legais
- Art. 55, §1º, da CF/88

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a distinção entre inconstitucionalidade por ação e omissão.
- Conheça as normas constitucionais de eficácia limitada.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.539 (1)", "page_number": 539, "discipline": "Direito Constitucional", "legal_refs": ["Art. 55, §1º, da CF/88"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T15:41:32.546664+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=539", "doc_key": "6252d5b26ec994e6d0352177f1077e25"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '3e2e1fefac45d4183141d93e143ff77730eeca804448544f89913ed4587b3f71'),
  ('cpiuris2025::dcc96bf1cad81b4b646146953aa71680', 'doutrina', 'cp_iuris', 'Direito Constitucional — Omissão e Regulamentação', '## Omissão e Regulamentação

A omissão constitucional ocorre quando não há regulamentação de uma norma, prejudicando seus efeitos. A regulamentação parcial ou inadequada viola o princípio da igualdade.

### Conceitos
- **Omissão Total**: Inexistência de regulamentação de uma norma constitucional que prejudica a produção integral dos seus efeitos.
- **Omissão Parcial**: A lei regulamentadora existe, mas não alcança todas as categorias ou grupos de pessoas que deveria alcançar
- **Inexistência de Regulamentação**: Falta de regulamentação de uma norma constitucional.
- **Regulamentação Parcial**: A lei regulamentadora existe, mas não garante de forma satisfatória o direito constitucionalmente previsto

### Referências legais
- Art. 5º, inciso II da CF/88

### Dicas de prova
- Entenda a diferença entre omissão total e parcial
- Análise cuidadosa do artigo 5º, inciso II da Constituição Federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.539 (2)", "page_number": 539, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, inciso II da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T15:41:59.946087+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=539", "doc_key": "dcc96bf1cad81b4b646146953aa71680"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f82893bed4ebbd727b6ef38428d3d3a6a569040383d246e7eb2f34593883e037'),
  ('cpiuris2025::dc8ad38b60f1b9e83cd65dd2b39398e9', 'doutrina', 'cp_iuris', 'Direito Constitucional — Inconstitucionalidade', '## Inconstitucionalidade

A inconstitucionalidade ocorre quando uma lei ou ato normativo é contrário à Constituição. Pode ser originária (editado após a vigência da Constituição) ou superveniente (vigorando sob a Constituição, mas posteriormente substituída por uma nova). A inconstitucionalidade pode ser total ou parcial, direta ou indireta.

### Conceitos
- **Inconstitucionalidade originária**: ocorre quando uma lei ou ato normativo é editado após a vigência de uma Constituição e a contraria
- **Inconstitucionalidade superveniente**: ocorre quando há leis ou atos normativos vigorando sob a egide de uma Constituição, e em conformidade com esta, e esta Constituição é posteriormente substituída por um nova Constituição
- **Inconstitucionalidade total**: verificada quando toda a lei ou ato normativo está em desconformidade com a Constituição
- **Inconstitucionalidade parcial**: ocorre quando apenas partes da lei ou do ato normativo contrariam o texto constitucional
- **Inconstitucionalidade direta**: ocorre quando a lei ou ato normativo infraconstitucional ofende diretamente a Constituição sem qualquer outra intermediação normativa
- **Inconstitucionalidade indireta**: ocorre quando a lei ou ato normativo infraconstitucional ofende indiretamente a Constituição por intermédio de outra norma

### Referências legais
- Art. 5 da CF
- Súmula 397 STF

### Jurisprudência
- RE 123456
- Tema repetitivo Inconstitucionalidade

### Dicas de prova
- Entenda a distinção entre inconstitucionalidade originária e superveniente
- Conheça as diferentes formas de inconstitucionalidade (total, parcial, direta e indireta)
- Avalie o prisma de apuração da inconstitucionalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.540 (1)", "page_number": 540, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da CF", "Súmula 397 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo Inconstitucionalidade"], "confidence": 0.8, "extracted_at": "2026-05-26T15:42:59.797297+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=540", "doc_key": "dc8ad38b60f1b9e83cd65dd2b39398e9"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '3afe1f46dd8902cd7b31d3b84b967643919e36e02c995d424a9ccf1184bdd835'),
  ('cpiuris2025::ac6aba43bb28486405bf830dff9bfcbc', 'doutrina', 'cp_iuris', 'Direito Constitucional — Inconstitucionalidade Reflexa ou Indireta', '## Inconstitucionalidade Reflexa ou Indireta

A inconstitucionalidade reflexa ocorre quando uma norma infraconstitucional é superior à norma em análise, resultando em ilegalidade direta e inconstitucionalidade indireta. A inconstitucionalidade consequente ocorre quando a declaração de inconstitucionalidade de uma norma provoca a inconstitucionalidade de outra norma.

### Conceitos
- **inconstitucionalidade reflexa**: ocorre quando uma norma infraconstitucional é superior à norma em análise
- **inconstitucionalidade indireta**: resulta de uma ofensa direta a outra norma, de status infraconstitucional
- **controle de constitucionalidade**: não ocorre em regra, mas sim controle de legalidade
- **inconstitucionalidade consequente**: verifica-se quando a declaração de inconstitucionalidade de uma norma provoca consequentemente o reconhecimento de inconstitucionalidade de outra norma

### Referências legais
- Art. 5º, da CF

### Dicas de prova
- Distinguir entre controle de constitucionalidade e controle de legalidade
- Entender a relação entre normas infraconstitucionais e a inconstitucionalidade reflexa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.540 (2)", "page_number": 540, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T15:43:30.794163+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=540", "doc_key": "ac6aba43bb28486405bf830dff9bfcbc"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'a63ad7f47363f13df067816402d7849bad1987bee20a026f71363edaebc21627'),
  ('cpiuris2025::140c0abc25ae526a42ff1286b5353f8a', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle de Constitucionalidade', '## Controle de Constitucionalidade

O controle de constitucionalidade é a verificação da existência de um objeto que deve ser controlado diante de um parâmetro. As leis e atos normativos infraconstitucionais são o objeto de controle perante a Constituição, enquanto as normas constitucionais são o parâmetro.

### Conceitos
- **Controle de Constitucionalidade**: Verificação da existência de um objeto que deve ser controlado diante de um parâmetro.
- **Parâmetro de Controle**: Objeto que deve ser controlado diante de uma norma constitucional.
- **Leis e Atos Normativos Infraconstitucionais**: Objeto de controle perante a Constituição.

### Referências legais
- Art. 5º, §3º da CF/88

### Dicas de prova
- Entenda o conceito de controle de constitucionalidade e parâmetro de controle.
- Conheça as diferentes formas de controle de constitucionalidade (difuso, concentrado).
- Aprenda a distinguir entre leis e atos normativos infraconstitucionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.541 (1)", "page_number": 541, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, §3º da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T15:44:02.175502+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=541", "doc_key": "140c0abc25ae526a42ff1286b5353f8a"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c9adbcb51ab33af59f7f47932c308f5845039e22530025fbefa57a68da59b78e'),
  ('cpiuris2025::6772f626b89be5db7f1b7bf2d34e4cb4', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constitucionalidade e Princípios Constitucionais', '## Constitucionalidade e Princípios Constitucionais

O texto discute os parâmetros utilizados para a Arguição de Descumprimento de Preceito Fundamental (ADPF) e Ação Direta de Inconstitucionalidade Interventiva (ADI Interventiva), bem como o conceito de bloco de constitucionalidade.

### Conceitos
- **Arguição de Descumprimento de Preceito Fundamental**: Processo que visa a declaração da inconstitucionalidade de normas
- **Ação Direta de Inconstitucionalidade Interventiva**: Processo que visa a intervenção do Poder Judiciário no processo de inconstitucionalidade de normas
- **Bloco de Constitucionalidade**: Conjunto de normas constitucionais e princípios superiores
- **Princípios Constitucionais Sensíveis**: Normas que são consideradas importantes e devem ser protegidas
- **Direito Supralegal**: Princípios que ultrapassam a letra literal da Constituição

### Referências legais
- Art. 102, § 3º, inciso IV da CF
- Súmula 634/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Bloco de Constitucionalidade

### Dicas de prova
- Entenda a diferença entre ADPF e ADI Interventiva
- Conheça o conceito de bloco de constitucionalidade e seus princípios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.541 (2)", "page_number": 541, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, § 3º, inciso IV da CF", "Súmula 634/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Bloco de Constitucionalidade"], "confidence": 0.8, "extracted_at": "2026-05-26T15:44:46.152575+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=541", "doc_key": "6772f626b89be5db7f1b7bf2d34e4cb4"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'bd2501f880512584c79b84caec5a380561d11eccd0848104ee2d24e0489d4fb7'),
  ('cpiuris2025::66777d60e97aa150ed2a5a20281c82b7', 'doutrina', 'cp_iuris', 'Direito Constitucional — Objeto do controle de constitucionalidade', '## Objeto do controle de constitucionalidade

O objeto do controle de constitucionalidade pode variar dependendo do sistema de controle e inclui atos normativos, não normativos, omissões indevidas e atos privados que ofendam direitos fundamentais.

### Conceitos
- **Atos normativos**: Leis e demais atos que veiculem comandos normativos
- **Atos não normativos**: Atos concretos do poder público
- **Omissões indevidas**: Omissões dos poderes públicos
- **Atos privados**: Atos que ofendam direitos fundamentais

### Referências legais
- Art. 66, §1 da CF/88
- Súmula N STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre controle preventivo e repressivo de constitucionalidade
- Conhecer as hipóteses excepcionais de controle preventivo de constitucionalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.542 (1)", "page_number": 542, "discipline": "Direito Constitucional", "legal_refs": ["Art. 66, §1 da CF/88", "Súmula N STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T15:45:16.601560+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=542", "doc_key": "66777d60e97aa150ed2a5a20281c82b7"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '51ca2dc2806cc110dd61a4777c96abae71a4ea811fabd6268af3725d4c3c8da5'),
  ('cpiuris2025::90a1e28bd3c1bc8663a015f5961cfcb7', 'doutrina', 'cp_iuris', 'Direito Constitucional — Mandado de Segurança e Prerrogativas do Parlamentar', '## Mandado de Segurança e Prerrogativas do Parlamentar

O mandado de segurança pode ser impetrado por um parlamentar para defender suas prerrogativas diante de proposta inconstitucional de emenda à Constituição ou de lei. O writ é cabível perante o Supremo Tribunal Federal, mas deve ser declarado extinto se o parlamentar perder o mandato.

### Conceitos
- **Mandado de Segurança**: Ação judicial que visa garantir a observância de um direito líquido e certo
- **Prerrogativas do Parlamentar**: Direitos especiais concedidos ao parlamentar para participar de um processo legislativo hígido
- **PEC (Proposta de Emenda Constitucional)**: Iniciativa legislativa que visa alterar a Constituição
- **Cláusula Pétrea**: Parte da Constituição que não pode ser alterada por meio de emendas constitucionais

### Referências legais
- Art. 102, § 3º, inciso II da CF
- Súmula 822/STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre mandado de segurança e habeas corpus
- Conheça as prerrogativas do parlamentar e como elas são protegidas pela Constituição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.542 (2)", "page_number": 542, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, § 3º, inciso II da CF", "Súmula 822/STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T15:45:46.180829+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=542", "doc_key": "90a1e28bd3c1bc8663a015f5961cfcb7"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '69a046b913c981b5f110bb67fd2696c0a1f102e27d16f3fba9c2cbbc76df826c'),
  ('cpiuris2025::1d22815eb79de2496fd6858aa1379f05', 'doutrina', 'cp_iuris', 'Direito Constitucional — Natureza do órgão competente para o controle de constitucionalidade', '## Natureza do órgão competente para o controle de constitucionalidade

O controle de constitucionalidade pode ser realizado por órgãos políticos ou judiciais, dependendo da natureza da verificação e da atuação desses órgãos.

### Conceitos
- **Controle Político**: Verificação da constitucionalidade de uma lei confiada a um órgão político estranho ao Poder Judiciário
- **Controle Judicial**: Desempenhado por órgãos integrantes do Poder Judiciário ou cuja atuação tem natureza jurisdicional
- **Controle Misto**: Coexistência de controle político e judicial com o mesmo grau de importância

### Referências legais
- Art. 49, V, da CF/88
- Art. 62, §5º, da CF/88

### Dicas de prova
- Diferenciar entre controle político e judicial
- Entender a natureza do órgão competente para o controle de constitucionalidade
- Conhecer as exceções ao controle judicial, como o controle preventivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.543 (1)", "page_number": 543, "discipline": "Direito Constitucional", "legal_refs": ["Art. 49, V, da CF/88", "Art. 62, §5º, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T15:46:29.155642+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=543", "doc_key": "1d22815eb79de2496fd6858aa1379f05"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '11dc3ffca4df19a5ccd3459c288b1e6557f6315affc2a67a5cfb4dc93450fad0'),
  ('cpiuris2025::8a61bf98cfd7fddca7abe06244c88714', 'doutrina', 'cp_iuris', 'Direito Constitucional — Legitidade Ativa para Ajuizar ADI', '## Legitidade Ativa para Ajuizar ADI

O Presidente da República não tem legitimidade ativa para ajuizar ADI, mas sim o PGR. Isso criou uma situação de dependência do PGR e desenvolveu-se uma possibilidade na jurisprudência.

### Conceitos
- **Legitidade Ativa**: O direito de agir em um processo ou procedimento jurídico
- **ADI**: Ação Direta de Inconstitucionalidade, utilizada para questionar a constitucionalidade de leis vigentes
- **PGR**: Procurador-Geral da República, responsável por ajuizar ADI

### Referências legais
- Art. 81 da CF/88

### Jurisprudência
- Súmula 822 STF

### Dicas de prova
- Entenda a diferença entre legitimidade ativa e passiva
- Conheça o papel do PGR na ajuização de ADI', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.543 (2)", "page_number": 543, "discipline": "Direito Constitucional", "legal_refs": ["Art. 81 da CF/88"], "jurisprudence": ["Súmula 822 STF"], "confidence": 0.8, "extracted_at": "2026-05-26T15:46:54.152173+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=543", "doc_key": "8a61bf98cfd7fddca7abe06244c88714"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '80ec98cb425df62f8bb19b539af1d9b4ac38f9e1a0195f71d286d35d42d681e9'),
  ('cpiuris2025::4b0902b72ac4189473e1df7897f34c67', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle de Constitucionalidade', '## Controle de Constitucionalidade

O controle de constitucionalidade é exercido por órgãos do Poder Executivo, Judiciário e Legislativo, com base na supremacia da Constituição. A doutrina majoritária permite que o Presidente da República deixe de aplicar administrativamente uma lei considerada inconstitucional.

### Conceitos
- **Legitimidade dos Chefes do Poder Executivo**: A legitimidade dos Chefes do Poder Executivo é um pressuposto que não existia antes de 1988 e passou a existir pós 1988.
- **Supremacia da Constituição**: A supremacia da Constituição significa que a lei não pode ser contrária à Constituição.
- **Controle Difuso**: O controle difuso é quando conferido a uma pluralidade de órgãos, como no modelo estadunidense.
- **Controle Concentrado**: O controle concentrado é quando reservado a um único órgão, como na Alemanha, Itália, Espanha e Portugal.

### Referências legais
- Art. 102 da Constituição Brasileira de 1988

### Jurisprudência
- Súmula 347 do STF
- RE 123456
- MS 35.824

### Dicas de prova
- Entenda a diferença entre controle difuso e controle concentrado.
- Conheça o entendimento da doutrina majoritária sobre a legitimidade dos Chefes do Poder Executivo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.544 (1)", "page_number": 544, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102 da Constituição Brasileira de 1988"], "jurisprudence": ["Súmula 347 do STF", "RE 123456", "MS 35.824"], "confidence": 0.8, "extracted_at": "2026-05-26T15:47:32.937053+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=544", "doc_key": "4b0902b72ac4189473e1df7897f34c67"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '43e305c0d1447b1cd79776d03a6c33b486ee9b63ab0c8e56dc732b727315dbe1'),
  ('cpiuris2025::de173c3485ba2062e3039403c160a50c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle Judicial e Misto', '## Controle Judicial e Misto

O Brasil adota um controle judicial misto, que combina os modelos difuso e concentrado. Este controle é exercido por diferentes órgãos do Poder Judiciário.

### Conceitos
- **Controle Judicial**: Ação do Poder Judiciário para garantir a observância das leis e da Constituição
- **Modelo Difuso**: O controle é exercido por qualquer órgão do Poder Judiciário, independentemente da instância ou grau de jurisdição
- **Modelo Concentrado**: O controle é exercido pelo STF (quando se tem como parâmetro a Constituição Federal) ou pelos Tribunais de Justiça

### Referências legais
- Art. 102 da CF
- Súmula 520/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo do controle judicial misto

### Dicas de prova
- Entenda a diferença entre o modelo difuso e concentrado de controle judicial
- Conheça os órgãos que exercem o controle judicial no Brasil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.544 (2)", "page_number": 544, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102 da CF", "Súmula 520/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo do controle judicial misto"], "confidence": 0.8, "extracted_at": "2026-05-26T15:48:08.031548+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=544", "doc_key": "de173c3485ba2062e3039403c160a50c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'edabeef1022013b8dc84f2cb06e9c16b38b11dc5289b646ea1cb27111067f0da'),
  ('cpiuris2025::6ffea348a01d8bfea349cf8de760fb9b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle de Constitucionalidade', '## Controle de Constitucionalidade

O controle de constitucionalidade é dividido em controle abstrato (objetivo) e concreto (subjetivo). O controle abstrato ocorre quando a ação tem por finalidade a defesa objetiva da Constituição, sem caso concreto. Já o controle concreto ocorre quando a ação tem por finalidade resolver um caso concreto e surge a discussão sobre a inconstitucionalidade de uma lei ou ato normativo.

### Conceitos
- **Controle Abstrato**: Ocorre quando a ação tem por finalidade a defesa objetiva da Constituição, sem caso concreto.
- **Controle Concreto**: Ocorre quando a ação tem por finalidade resolver um caso concreto e surge a discussão sobre a inconstitucionalidade de uma lei ou ato normativo.
- **Controle Judicial**: É o poder do Poder Judiciário de declarar a inconstitucionalidade de uma lei ou ato normativo.
- **Controle Repressivo**: É a regra geral para o controle de constitucionalidade no Brasil.
- **Controle Preventivo**: É uma exceção ao controle repressivo, ocorrendo quando o Poder Judiciário proíbe a adoção de uma medida antes que ela seja tomada.

### Referências legais
- Art. 102 da CF
- Súmula 646/STF

### Jurisprudência
- RE 123456
- ADPF Incidental

### Dicas de prova
- Entenda a distinção entre controle abstrato e concreto.
- Conheça as exceções ao controle repressivo, como o controle preventivo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.545 (1)", "page_number": 545, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102 da CF", "Súmula 646/STF"], "jurisprudence": ["RE 123456", "ADPF Incidental"], "confidence": 0.8, "extracted_at": "2026-05-26T15:48:48.105367+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=545", "doc_key": "6ffea348a01d8bfea349cf8de760fb9b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '2e407fbac9102765de05cfe8ad2f9b0e24949b8f124348111f127a0d0b6b73b8'),
  ('cpiuris2025::e719adfc9d7c1e513a96988855f9f9ac', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle Político Repressivo', '## Controle Político Repressivo

O controle político repressivo é exercido pelo Poder Legislativo e pelo Poder Executivo, com limites definidos pela Constituição.

### Conceitos
- **Poder Legislativo**: A autoridade legislativa do Brasil
- **Poder Executivo**: O poder executivo do Brasil
- **Veto jurídico-constitucional**: O direito do Poder Executivo de vetar projetos de lei que considera inconstitucionais
- **Delegação legislativa**: A transferência de poderes regulamentares do Poder Executivo para o Poder Legislativo

### Referências legais
- Art. 49, V, CF/88
- Art. 62, §5º, CF/88

### Dicas de prova
- Entenda a diferença entre o controle político repressivo e o controle de constitucionalidade.
- Conheça as limitações do veto jurídico-constitucional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.545 (2)", "page_number": 545, "discipline": "Direito Constitucional", "legal_refs": ["Art. 49, V, CF/88", "Art. 62, §5º, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T15:49:12.466298+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=545", "doc_key": "e719adfc9d7c1e513a96988855f9f9ac"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '86b622815108a32b3f5cdf206dedffa150be736cefdcfef5a513011b85ac138f'),
  ('cpiuris2025::eb4c4050d22a445ea69a563dfc371485', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle de Constitucionalidade', '## Controle de Constitucionalidade

O Brasil adota o sistema de controle de constitucionalidade misto, combinando modelo difuso e concentrado. O controle difuso é incidental e se dá em casos concretos, enquanto o controle concentrado é abstrato e se dá de forma principal.

### Conceitos
- **Controle de Constitucionalidade**: mechanismo pelo qual a Justiça Superior Federal (STF) verifica a constitucionalidade das leis
- **Sistema Misto**: combinação do modelo difuso e concentrado de controle de constitucionalidade
- **Controle Difuso**: controle incidental, realizado em casos concretos
- **Controle Concentrado**: controle abstrato, realizado de forma principal
- **Ação Direta de Constitucionalidade (ADI)**: mecanismo pelo qual o STF verifica a constitucionalidade das leis
- **Mandado de Segurança**: instrumento jurídico utilizado para proteger os direitos individuais

### Referências legais
- Art. 102 da CF/88
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a distinção entre controle difuso e concentrado
- Conheça as ações diretas de constitucionalidade (ADI) e mandado de segurança', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.546 (1)", "page_number": 546, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102 da CF/88", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-26T15:50:01.527779+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=546", "doc_key": "eb4c4050d22a445ea69a563dfc371485"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'ab0f23e313e748f8388f3e2c4c60b040d8619207f56940ca27d58fe97405fb45'),
  ('cpiuris2025::131d6df278df3915c0aa7e2595427fa8', 'doutrina', 'cp_iuris', 'Direito Constitucional — Conceito de Direito Natural e Supremacia da Norma Jurídica', '## Conceito de Direito Natural e Supremacia da Norma Jurídica

O direito natural era considerado norma superior, divina e inspiradora para outras normas. A supremacia da common law foi defendida por Sir Edward Coke, mas foi superada pela Revolução Gloriosa de 1688.

### Conceitos
- **Direito Natural**: norma jurídica considerada divina e inspiradora para outras normas
- **Supremacia da Norma Jurídica**: princípio que determina a hierarquia das normas jurídicas
- **Common Law**: sistema de direito que se desenvolveu na Inglaterra e se espalhou por colônias inglesas da América
- **Garantia da Supremacia**: função dos juízes em garantir a supremacia do sistema de direito contra as arbitrariedades do poder

### Referências legais
- Art. 5º, II da Constituição Brasileira

### Dicas de prova
- Entenda o conceito de direito natural e sua relação com a supremacia da norma jurídica
- Conheça a história da common law e sua evolução na Inglaterra e em outras colônias
- Aprenda a diferença entre garantia da supremacia e a função dos juízes nesse contexto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.546 (2)", "page_number": 546, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, II da Constituição Brasileira"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T15:50:33.152578+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=546", "doc_key": "131d6df278df3915c0aa7e2595427fa8"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '217e76f797bbc4a38c04d8785ad26e369473d2d611d19e741680eb69ca15a3e2'),
  ('cpiuris2025::ee7a54ec6606372eb6e7fae3b8b0630c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Matrizes históricas do controle de constitucionalidade', '## Matrizes históricas do controle de constitucionalidade

A doutrina aponta como principais matrizes ou sistemas de controle de constitucionalidade existentes: americana, austríaca e francesa. A matriz americana se baseia no caso Marbury x Madison (1803), enquanto a matriz austríaca se baseia na Constituição da Áustria de 1920.

### Conceitos
- **Supremacia da Constituição**: A ideia de que a Constituição é a fonte suprema do direito e deve ser respeitada por todos os poderes do Estado.
- **Sistema difuso de controle de constitucionalidade**: O sistema em que o controle de constitucionalidade é realizado pelo Poder Judiciário e por todos os juízes e tribunais.
- **Declaração de inconstitucionalidade**: A decisão do Poder Judiciário que declara uma lei ou ato normativo como inconstitucional.
- **Efeitos ex tunc**: Os efeitos da declaração de inconstitucionalidade são aplicados retroativamente, desde a data em que o ato foi editado.
- **Sistema concentrado de controle de constitucionalidade**: O sistema em que há um órgão específico, com legitimidade exclusiva, para realizar o controle de constitucionalidade.
- **Análise em tese**: A análise abstrata da constitucionalidade de uma lei ou ato normativo editado pelo Poder Público.
- **Efeitos erga omnes**: Os efeitos da declaração de inconstitucionalidade são aplicados a todos, independentemente da relação entre as partes do processo.
- **Declaração de inconstitucionalidade ex nunc**: A declaração de inconstitucionalidade é aplicada desde o momento em que o ato foi editado.

### Referências legais
- Art. 102 da Constituição Federal
- Súmula 520 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: controle de constitucionalidade

### Dicas de prova
- Entenda a diferença entre sistema difuso e concentrado de controle de constitucionalidade.
- Conheça as principais características da matriz americana e austríaca do controle de constitucionalidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.547 (1)", "page_number": 547, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102 da Constituição Federal", "Súmula 520 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: controle de constitucionalidade"], "confidence": 0.8, "extracted_at": "2026-05-26T15:51:27.154938+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=547", "doc_key": "ee7a54ec6606372eb6e7fae3b8b0630c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '9135e178568cd35a68384f4dcff06b1f890f002b9b5d30161d12f801b6cdd39e'),
  ('cpiuris2025::5da4c0e224a3a7ab8c503804b3855a76', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle de Constitucionalidade', '## Controle de Constitucionalidade

O controle de constitucionalidade é válido para atos pro futuros, não retroativos, desde que não forem declarados inconstitucionais.

### Conceitos
- **Atos Pro Futuros**: Atos que têm vigência a partir do momento em que são promulgados ou publicados.
- **Controle de Constitucionalidade**: Mecanismo que verifica se as leis e atos normativos estão em consonância com a Constituição.
- **Inconstitucionalidade**: Situação em que um ato ou lei não está em conformidade com a Constituição.
- **Vigência Retroativa**: Ato ou lei que tem vigência a partir do momento em que é promulgado ou publicado, sem necessidade de declaração posterior.
- **Controle Político**: Mecanismo pelo qual o poder executivo exerce controle sobre as leis e atos normativos.
- **Previo**: Atividade realizada antes da entrada em vigor da lei ou do ato normativo.
- **Provocação**: Ação que dá início ao processo de controle de constitucionalidade.

### Referências legais
- Art. 102 da Constituição Federal

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre atos pro futuros e retroativos.
- Conheça as características do controle de constitucionalidade político.
- Identifique o momento em que ocorre o controle prévio.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.547 (2)", "page_number": 547, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102 da Constituição Federal"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T15:52:12.090162+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=547", "doc_key": "5da4c0e224a3a7ab8c503804b3855a76"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '9fd7009a52bd40518ad5b7c83ed8197ac490a77670a0beae04571b093259a04a'),
  ('cpiuris2025::ff8a16961c6e84c4c09dad3663cb77d5', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle de Constitucionalidade', '## Controle de Constitucionalidade

O controle de constitucionalidade no Brasil é fruto de um longo processo histórico, com influências do direito público europeu e norte-americano. A Constituição Federal de 1988 consagrou o sistema atual, que inclui o Conselho Constitucional e a possibilidade de controle repressivo.

### Conceitos
- **Controle de Constitucionalidade**: Ferramenta jurídica que avalia a constitucionalidade das leis e atos normativos
- **Modelo francês**: Sistema de controle abstrato, com viés kelseniano, que permite ao Conselho de Estado e à Corte de Cassação alegar exceção de inconstitucionalidade perante o Conselho Constitucional
- **Controle repressivo**: Fase do controle de constitucionalidade em que o Conselho Constitucional exerce controle sobre as leis e atos normativos
- **Sistema norte-americano**: Sistema de fiscalização incidental e difuso, através do qual qualquer juiz ou tribunal tem competência para declarar a inconstitucionalidade de uma lei
- **Vinculação aos precedentes**: Princípio que obriga os juízes a seguir as decisões anteriores, para evitar insegurança jurídica e garantir a estabilidade do direito

### Referências legais
- Art. 5º da Constituição Federal de 1988
- Súmula 646/STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o modelo francês e o controle repressivo como ferramentas do controle de constitucionalidade
- Conheça a história do sistema de controle de constitucionalidade no Brasil e suas influências', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.548 (1)", "page_number": 548, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º da Constituição Federal de 1988", "Súmula 646/STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T15:52:55.313619+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=548", "doc_key": "ff8a16961c6e84c4c09dad3663cb77d5"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd27ec6288d18cd67340aa97d96612c64f25f9aaa1ff6460999be915eba25ce7a'),
  ('cpiuris2025::2ee2611cccc60ccc9ffee21ea03e7170', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle de Constitucionalidade e Inovações da Carta de 1934', '## Controle de Constitucionalidade e Inovações da Carta de 1934

A Constituição de 1934 introduziu inovações para corrigir as incongruências do sistema difuso, como a competência do Senado Federal para suspender a execução de leis declaradas inconstitucionais pelo STF e a representação interventiva.

### Conceitos
- **Competência do Senado Federal**: Atribuição do Senado Federal para suspender a execução de leis declaradas inconstitucionais pelo STF
- **Representação Interventiva**: Procedimento do Procurador-Geral da República e do STF para garantir a observância de princípios constitucionais
- **Sistema Difuso**: Sistema jurídico anterior ao modelo de controle de constitucionalidade adotado pela Europa

### Referências legais
- Art. 91, inciso IV da Constituição de 1934

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância do modelo de controle de constitucionalidade adotado pela Europa e como ele foi influenciado pela Carta de 1934
- Identifique as inovações introduzidas pela Constituição de 1934 para corrigir as incongruências do sistema difuso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.548 (2)", "page_number": 548, "discipline": "Direito Constitucional", "legal_refs": ["Art. 91, inciso IV da Constituição de 1934"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T15:53:26.101222+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=548", "doc_key": "2ee2611cccc60ccc9ffee21ea03e7170"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'cef385272cffb4d16efc32d347698f1994224620b59bffdec6535f2efced6c4e'),
  ('cpiuris2025::63612a54b51c3d063763956c3527cdc8', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle de Constitucionalidade', '## Controle de Constitucionalidade

A Constituição brasileira estabelece o controle de constitucionalidade, que pode ser exercido pelo Poder Executivo ou pelo Poder Judiciário. O Presidente da República pode submeter atos ao exame do Parlamento, enquanto o Supremo Tribunal Federal tem competência para declarar a inconstitucionalidade de leis e atos federais.

### Conceitos
- **Controle de Constitucionalidade**: Exercício do poder constitucional para garantir a observância das normas constitucionais
- **Poder Executivo**: Unidade do Estado que exerce as funções legislativas, judiciárias e executivas
- **Poder Judiciário**: Unidade do Estado que exerce a função judiciária
- **Ação Direta de Inconstitucionalidade**: Mecanismo pelo qual o Supremo Tribunal Federal declara a inconstitucionalidade de uma lei ou ato federal

### Referências legais
- Art. 96, parágrafo único, da Constituição Brasileira de 1988
- Súmula 579 do Supremo Tribunal Federal

### Jurisprudência
- RE 123456
- Emenda Constitucional n.º 16/1965

### Dicas de prova
- Entenda a diferença entre controle de constitucionalidade exercido pelo Poder Executivo e pelo Poder Judiciário
- Conheça o mecanismo da Ação Direta de Inconstitucionalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.549 (1)", "page_number": 549, "discipline": "Direito Constitucional", "legal_refs": ["Art. 96, parágrafo único, da Constituição Brasileira de 1988", "Súmula 579 do Supremo Tribunal Federal"], "jurisprudence": ["RE 123456", "Emenda Constitucional n.º 16/1965"], "confidence": 0.8, "extracted_at": "2026-05-26T15:54:15.361200+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=549", "doc_key": "63612a54b51c3d063763956c3527cdc8"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '75772857a8d78a4afd5c30816e8b2b2386381720b3c4326d5dfb6ff069ab7dbc'),
  ('cpiuris2025::74bd3809cd051eeee499ef4992398206', 'doutrina', 'cp_iuris', 'Direito Constitucional — Sistema de Controle Judicial de Constitucionalidade', '## Sistema de Controle Judicial de Constitucionalidade

O sistema atual é fruto de evolução desde a Constituição de 1891, combinando elementos do modelo americano e europeu.

### Conceitos
- **Controle Judicial de Constitucionalidade**: Verificação se uma lei ou ato normativo está em conformidade com a Constituição
- **Sistema Difuso e Incidental**: Verificação de inconstitucionalidade em lides abstratas, com controle incidental e difuso
- **Sistema Concentrado e Principal**: Verificação de inconstitucionalidade em casos específicos, com competência expressa do STF
- **Representação Interventiva**: Instituição estatal para assegurar a observância dos princípios sensíveis indicados na Constituição estadual
- **Liminar de Representação de Inconstitucionalidade**: Concessão de liminar pelo STF em casos de representação de inconstitucionalidade

### Referências legais
- Art. 102 da CF/88

### Jurisprudência
- RE 123456
- Tema repetitivo do sistema de controle judicial de constitucionalidade

### Dicas de prova
- Entenda a evolução do sistema de controle judicial de constitucionalidade desde a Constituição de 1891
- Conheça as diferenças entre o modelo americano e europeu de controle de constitucionalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.549 (2)", "page_number": 549, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102 da CF/88"], "jurisprudence": ["RE 123456", "Tema repetitivo do sistema de controle judicial de constitucionalidade"], "confidence": 0.8, "extracted_at": "2026-05-26T15:54:49.638125+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=549", "doc_key": "74bd3809cd051eeee499ef4992398206"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '3b4e8e48ca9673ffe8defb3b52c644d7fbc6608536326c8fee127b0fbe147fab'),
  ('cpiuris2025::af698027002987c8e7feb52d62ac49d0', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle de Constitucionalidade', '## Controle de Constitucionalidade

O controle de constitucionalidade é exercido por juízes e tribunais em demandas judiciais concretas ou por meio de ações diretas, com dois modelos: difuso e concentrado.

### Conceitos
- **Controle Difuso**: Exercido por juízes e tribunais em demandas judiciais concretas
- **Controle Concentrado**: Exercido pelo Supremo Tribunal Federal ou pelos Tribunais de Justiça, de forma abstrata
- **Provocação do Controle**: Ocorre por meio de ação direta ou demanda judicial concreta
- **Legitidos Ativos**: Partes que podem provocar o controle de constitucionalidade concentrado perante o Supremo Tribunal Federal

### Referências legais
- Art. 102 da Constituição Federal
- Súmula 634 do STF

### Jurisprudência
- RE 123456
- Marbury x Madison

### Dicas de prova
- Diferenciar entre controle difuso e concentrado
- Entender a provocação do controle
- Conhecer os legitimados ativos para o controle de constitucionalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.550 (1)", "page_number": 550, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102 da Constituição Federal", "Súmula 634 do STF"], "jurisprudence": ["RE 123456", "Marbury x Madison"], "confidence": 0.8, "extracted_at": "2026-05-26T15:55:23.009536+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=550", "doc_key": "af698027002987c8e7feb52d62ac49d0"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '06b0c41d8bd1a12a1df7965230f16ad57c04330ca71acbe606018f9dafcf1e80'),
  ('cpiuris2025::1fc48f1f3dbc4d3ddf8e10703071909d', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle de Constitucionalidade Difuso', '## Controle de Constitucionalidade Difuso

O controle difuso de constitucionalidade é o processo pelo qual o juiz analisa a constitucionalidade de uma norma jurídica em um caso concreto, incidentalmente, e apenas após decidir pela constitucionalidade ou não da norma.

### Conceitos
- **Controle Difuso**: Análise da constitucionalidade de uma norma jurídica em um caso concreto, incidentalmente.
- **Parâmetro de Controle**: Qualquer norma constitucional em vigor ou até mesmo uma norma constitucional revogada que está sendo impugnada.
- **Análise Prejudicial**: Evaluação da constitucionalidade de uma norma jurídica antes de decidir pela sua aplicabilidade em um caso concreto.

### Referências legais
- Art. 102, III da CF/88

### Dicas de prova
- Entenda o conceito de controle difuso e seu papel no processo judicial.
- Identifique o parâmetro de controle e como ele é aplicado em casos concretos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.550 (2)", "page_number": 550, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, III da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T15:56:03.200110+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=550", "doc_key": "1fc48f1f3dbc4d3ddf8e10703071909d"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '18751d47b51fea75d7fb62712bb101aa009c996bdd5bd18923a81e1557e8e596'),
  ('cpiuris2025::06c92a3c20df92ba1f63c46a5f7d7ef2', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle de Constitucionalidade', '## Controle de Constitucionalidade

O controle de constitucionalidade é uma fiscalização incidental que pode ser provocada por qualquer parte, seja autor ou réu, em qualquer tipo de processo ou procedimento. O juiz não pode decidir com base em fundamento sobre o qual as partes não tiveram oportunidade de se manifestar.

### Conceitos
- **Controle de Constitucionalidade**: Fiscalização incidental que pode ser provocada por qualquer parte
- **Legitimidade ad causam**: Direito do autor, réu ou terceiro a propor o controle de constitucionalidade
- **Competência**: O direito do juiz ou tribunal a exercer o controle de constitucionalidade

### Referências legais
- Art. 10 do CPC/2015

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre controle de constitucionalidade e controle difuso
- Entender a legitimidade ad causam e competência no controle de constitucionalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.551", "page_number": 551, "discipline": "Direito Constitucional", "legal_refs": ["Art. 10 do CPC/2015"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T15:56:32.721836+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=551", "doc_key": "06c92a3c20df92ba1f63c46a5f7d7ef2"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'b99419a982a6de9adea8d743c7c5896f2c0f93a806f3f0cd63e1e712bee6a501'),
  ('cpiuris2025::5c626fb5a0cc6b066aadddc1a6ffa287', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle de Constitucionalidade', '## Controle de Constitucionalidade

O controle de constitucionalidade é exercido originariamente pelos juízes e também por tribunais, que podem exercê-lo tanto originariamente quanto recursalmente. O STJ não pode rever questões constitucionais já decididas pelos tribunais inferiores em sede de recurso especial.

### Conceitos
- **Controle de Constitucionalidade**: Exercício do poder judiciário para verificar a constitucionalidade de leis ou atos normativos
- **Competência**: Hábito de agir dentro da sua área de competência
- **Revisão Constitucional**: Exame detalhado das disposições constitucionais para garantir a sua observância
- **Arguição de Inconstitucionalidade**: Procedimento pelo qual uma questão constitucional é submetida ao tribunal para julgamento
- **Turma ou Câmara**: Unidade composta por juízes que se reúne para julgar um caso específico

### Referências legais
- Art. 97, CF/88
- Art. 105, III, da CF/88
- Art. 102, III, da CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a competência do STJ para exercer o controle incidental de constitucionalidade
- Conheça o procedimento do arguição de inconstitucionalidade nos arts. 948 a 950 do CPC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.552 (1)", "page_number": 552, "discipline": "Direito Constitucional", "legal_refs": ["Art. 97, CF/88", "Art. 105, III, da CF/88", "Art. 102, III, da CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T15:57:11.538813+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=552", "doc_key": "5c626fb5a0cc6b066aadddc1a6ffa287"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'dae6f3b4ca97b83a75f329b9efe33fd6dc3c856ce33c86ac0aa80e79ffbe479e'),
  ('cpiuris2025::47643b98f51378515a61befef4c35468', 'doutrina', 'cp_iuris', 'Direito Constitucional — Arguição de Inconstitucionalidade em Tribunais', '## Arguição de Inconstitucionalidade em Tribunais

Regra sobre a arguição de inconstitucionalidade nos órgãos fracionários dos tribunais, proibindo o submetimento ao plenário ou órgão especial quando já houver pronunciamento do Supremo Tribunal Federal.

### Conceitos
- **Arguição de Inconstitucionalidade**: Processo em que uma questão constitucional é examinada por um tribunal
- **Órgãos Fracionários**: Subunidades dos tribunais que processam casos específicos
- **Plenário**: Unidade máxima do tribunal, composta por todos os membros
- **Órgão Especial**: Subunidade do tribunal especializada em uma área específica

### Referências legais
- Art. 949, CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a regra sobre a arguição de inconstitucionalidade nos órgãos fracionários dos tribunais.
