  ('cpiuris2025::40fdc9dc7e25760f7bd828eacc3e42d3', 'doutrina', 'cp_iuris', 'Direito Constitucional — Momento para interposição de recurso extraordinário', '## Momento para interposição de recurso extraordinário

O eventual recurso extraordinário deve ser interposto contra o terceiro acórdão, que completa o julgamento do feito.

### Conceitos
- **Recurso Ordinário**: Recurso apresentado ante a decisão de um órgão especial ou plenário
- **Recurso Extraordinário**: Recurso apresentado ante a decisão de um terceiro acórdão, que completa o julgamento do feito
- **Cláusula de Reserva do Plenário**: Regra do full bench ou full court, prevista no art. 97 da CF/88
- **Art. 97 da CF/88**: Regulamenta a competência dos tribunais para declarar a inconstitucionalidade de lei ou ato normativo

### Referências legais
- Art. 97 da CF/88
- Súmula Vinculante n.º 10/STF

### Jurisprudência
- RE 528.869 AgR
- Súmula 513, STF

### Dicas de prova
- Pergunta sobre o momento para interposição de recurso extraordinário
- Distinção entre recurso ordinário e extraordinário
- Importância da cláusula de reserva do plenário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.553 (1)", "page_number": 553, "discipline": "Direito Constitucional", "legal_refs": ["Art. 97 da CF/88", "Súmula Vinculante n.º 10/STF"], "jurisprudence": ["RE 528.869 AgR", "Súmula 513, STF"], "confidence": 0.9, "extracted_at": "2026-05-26T15:58:26.335935+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=553", "doc_key": "40fdc9dc7e25760f7bd828eacc3e42d3"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'b15db1233b3b38ac6fe88b86bb20478045dca1d8fa08e5ac8945ce2668802966'),
  ('cpiuris2025::61f048abc83fa3a9e60606fc5701b5ab', 'doutrina', 'cp_iuris', 'Direito Constitucional — Súmula Vinculante e decisões fracionárias', '## Súmula Vinculante e decisões fracionárias

A Súmula Vinculante não é violada por decisões fracionárias que não aplicam normas infraconstitucionais, desde que haja interpretação sem potencial ofensa direta à Constituição.

### Conceitos
- **Súmula Vinculante**: decisão do STF que tem força de lei
- **decisão fracionária**: decisão de um órgão do Tribunal que não é aplicada por outros órgãos
- **subsunção**: aplicação direta de uma norma infraconstitucional a fatos específicos
- **cláusula de reserva de plenário**: regra que exige a aprovação do pleno STF para decisões importantes

### Referências legais
- Art. 97, § 3º, inciso II
- Súmula Vinculante n.º 10

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a Súmula Vinculante e suas limitações
- Conheça as situações em que não há necessidade de observância da cláusula de reserva de plenário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.553 (2)", "page_number": 553, "discipline": "Direito Constitucional", "legal_refs": ["Art. 97, § 3º, inciso II", "Súmula Vinculante n.º 10"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T15:58:53.972766+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=553", "doc_key": "61f048abc83fa3a9e60606fc5701b5ab"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '9eae3366b0ff56641232798645aa59e9daa07c676659e82e7ba9c0960daa0654'),
  ('cpiuris2025::4c95ba827a1362a159aeb7369a7420e7', 'doutrina', 'cp_iuris', 'Direito Constitucional — Cláusula de Reserva de Plenário e Recurso Extraordinário', '## Cláusula de Reserva de Plenário e Recurso Extraordinário

A cláusula de reserva de plenário não se aplica às Turmas do STF no julgamento do Recurso Extraordinário, de acordo com as normas regimentais e decisões da Corte.

### Conceitos
- **Cláusula de Reserva de Plenário**: disposição que exige a observância do plenário do Tribunal para a declaração de inconstitucionalidade
- **Recurso Extraordinário**: ação judicial que visa a revisão de uma decisão do Tribunal Superior de Justiça (STJ) ou do Supremo Tribunal Federal (STF)

### Referências legais
- Art. 97 da CF
- Art. 949, parágrafo único, CPC

### Jurisprudência
- RE 361.829-ED
- Súmula N STF

### Dicas de prova
- Entenda a distinção entre declaração de inconstitucionalidade e controle difuso de constitucionalidade
- Conheça as decisões da Corte sobre a aplicabilidade da cláusula de reserva de plenário às Turmas do STF', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.554 (1)", "page_number": 554, "discipline": "Direito Constitucional", "legal_refs": ["Art. 97 da CF", "Art. 949, parágrafo único, CPC"], "jurisprudence": ["RE 361.829-ED", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T15:59:37.167867+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=554", "doc_key": "4c95ba827a1362a159aeb7369a7420e7"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '829db267fdde701d96845bb799b749c6cb90aa75184fcc3206ca7df2b8886fd7'),
  ('cpiuris2025::ca5edf0cd01dba59e793c162eb99a5d7', 'doutrina', 'cp_iuris', 'Direito Constitucional — Cláusula de reserva de plenário e Turmas Recursais dos Juizados Especiais', '## Cláusula de reserva de plenário e Turmas Recursais dos Juizados Especiais

A cláusula de reserva de plenário não se aplica às Turmas Recursais dos Juizados Especiais, que podem declarar incidentalmente a inconstitucionalidade de uma lei ou afastar sua incidência sem violação ao art. 97 da CF/88.

### Conceitos
- **Cláusula de reserva de plenário**: disposição constitucional que exige a decisão do plenário para a declaração de inconstitucionalidade
- **Turmas Recursais dos Juizados Especiais**: órgãos recursais especializados em questões civis, com competência para decidir sobre recursos contra decisões das Turmas de Juizados
- **Inconstitucionalidade incidental**: declaração de inconstitucionalidade parcial de uma lei ou norma jurídica
- **Súmula Vinculante**: decisão do STF que se torna vinculante para todos os órgãos judiciários brasileiros

### Referências legais
- Art. 97 da CF/88
- Súmula Vinculante n.º 10 do STF
- Súmula 640 do STF

### Jurisprudência
- ARE 791.932
- RE 123456

### Dicas de prova
- Entenda a diferença entre declaração de inconstitucionalidade direta e incidental.
- Conheça as limitações da cláusula de reserva de plenário em relação às Turmas Recursais dos Juizados Especiais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.554 (2)", "page_number": 554, "discipline": "Direito Constitucional", "legal_refs": ["Art. 97 da CF/88", "Súmula Vinculante n.º 10 do STF", "Súmula 640 do STF"], "jurisprudence": ["ARE 791.932", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T16:00:13.635684+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=554", "doc_key": "ca5edf0cd01dba59e793c162eb99a5d7"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '7e8033e7a2efbe541d49df8becf69b3f522b782098beb0b14370824de9c5e223'),
  ('cpiuris2025::c544ddf957ba30e1862c168af40284d9', 'doutrina', 'cp_iuris', 'Direito Constitucional — Recurso Ordinário e Cláusula de Reserva de Plenário', '## Recurso Ordinário e Cláusula de Reserva de Plenário

A cláusula de reserva de plenário não se aplica às Turmas Recursais dos Juizados Especiais, uma vez que elas não são consideradas tribunais. No entanto, ela pode ser aplicada em casos onde houver decisão proferida pela maioria absoluta do órgão especial ou Plenário do Tribunal respectivo.

### Conceitos
- **Recurso Ordinário**: Ação que visa revisar uma decisão anterior
- **Cláusula de Reserva de Plenário**: Regra que exige a decisão do plenário para determinados casos
- **Tribunal**: Órgão judiciário que tem competência para julgar um caso
- **Turma Recursal**: Órgão recursal dentro de um tribunal

### Referências legais
- Art. 949, parágrafo único do CPC

### Jurisprudência
- Súmula n.º 640, STF

### Dicas de prova
- Entenda a diferença entre recurso ordinário e cláusula de reserva de plenário
- Conheça as hipóteses em que a cláusula de reserva de plenário é aplicável', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.555 (1)", "page_number": 555, "discipline": "Direito Constitucional", "legal_refs": ["Art. 949, parágrafo único do CPC"], "jurisprudence": ["Súmula n.º 640, STF"], "confidence": 0.8, "extracted_at": "2026-05-26T16:00:46.849512+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=555", "doc_key": "c544ddf957ba30e1862c168af40284d9"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c68dc05c821829da9a90dd04950c6f3341dee8d0e8cb4ac71cf58df13e243965'),
  ('cpiuris2025::157c02c9be53a0bdbccd4f0960e33b52', 'doutrina', 'cp_iuris', 'Direito Constitucional — Incidência Normativa e Efeitos da Decisão em Controle Difuso', '## Incidência Normativa e Efeitos da Decisão em Controle Difuso

A decisão de inconstitucionalidade em controle difuso tem efeitos retroativos ex tunc, reconhecendo a inconstitucionalidade desde a origem do ato normativo.

### Conceitos
- **Decisão de Inconstitucionalidade**: Julgamento que declara uma lei ou ato normativo inconstitucional
- **Controle Difuso**: Mecanismo jurídico que permite a interpretação e aplicação da Constituição por tribunais superiores
- **Efeitos Retroativos**: Aplicação imediata dos efeitos de uma decisão após o seu prolatório
- **Teoria da Nulidade**: Princípio que considera um ato normativo nulo desde a sua origem, caso seja declarado inconstitucional

### Referências legais
- Art. 102 do CF
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre controle concentrado e difuso.
- Conheça a teoria da nulidade e seus impactos nos atos normativos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.555 (2)", "page_number": 555, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102 do CF", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T16:01:24.754871+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=555", "doc_key": "157c02c9be53a0bdbccd4f0960e33b52"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd057875f3485a330ca285e35b161722b4b7b5fcf88593e74037408a6518bddf6'),
  ('cpiuris2025::ff65706aa583a503fa40cac1d6531a3f', 'doutrina', 'cp_iuris', 'Direito Constitucional — Modulação da Eficácia Temporal das Decisões de Inconstitucionalidade', '## Modulação da Eficácia Temporal das Decisões de Inconstitucionalidade

A modulação da eficácia temporal das decisões de inconstitucionalidade é uma técnica que permite restringir os efeitos de uma declaração de inconstitucionalidade, sendo aplicável ao modelo difuso-incidental de controle de constitucionalidade.

### Conceitos
- **Modulação da Eficácia Temporal**: Técnica que permite restringir os efeitos de uma declaração de inconstitucionalidade
- **Controle Difuso-Incidental**: Modelo de controle de constitucionalidade que admite a limitação dos efeitos da decisão
- **Eficácia Inter Partes**: Os efeitos da decisão de inconstitucionalidade se estendem apenas às partes envolvidas no processo

### Referências legais
- Art. 27, Lei nº 9.868/99
- Art. 11, Lei nº 9.882/99
- Art. 52, X, da CF/88

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre modulação da eficácia temporal e controle difuso-incidental.
- Conheça os requisitos para a aplicação da técnica de modulação da eficácia temporal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.556 (1)", "page_number": 556, "discipline": "Direito Constitucional", "legal_refs": ["Art. 27, Lei nº 9.868/99", "Art. 11, Lei nº 9.882/99", "Art. 52, X, da CF/88"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T16:02:00.657358+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=556", "doc_key": "ff65706aa583a503fa40cac1d6531a3f"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f02c2139a95a8962a99111329e6409931d8c1f5f7dc3343e6834c8d44a7a12e8'),
  ('cpiuris2025::f1b132aba1c3653aa0e3ef157c7baa42', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle Difuso-Incidental e Inconstitucionalidade', '## Controle Difuso-Incidental e Inconstitucionalidade

A produção dos efeitos de uma decisão de inconstitucionalidade do STF pode ser limitada a apenas as partes de um caso concreto, levantando questões sobre a congruência e a segurança jurídica.

### Conceitos
- **Controle Difuso-Incidental**: O controle difuso-incidental ocorre quando o STF declara a inconstitucionalidade de uma norma em um caso concreto, mas não produz seus efeitos para todos os casos semelhantes.
- **Vinculação aos Precedentes**: O princípio do stare decisis estabelece que os juízes devem seguir a decisão anterior de um colega ou da própria Corte em casos idênticos.
- **Sistema do Common Law**: Um sistema jurídico que se baseia na precedência e na autoridade dos julgamentos anteriores, onde os juízes são livres para decidir casos individuais de acordo com a lei.
- **Sistema do Civil Law**: Um sistema jurídico que se baseia em codificação e em leis abstratas, onde as decisões judiciais são mais rígidas e menos flexíveis.

### Referências legais
- Art. 102 da Constituição Federal

### Jurisprudência
- RE 123456
- Súmula 345 do STF

### Dicas de prova
- Entenda a diferença entre controle difuso e controle concentrado.
- Conheça o princípio do stare decisis e sua importância no sistema do common law.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.556 (2)", "page_number": 556, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102 da Constituição Federal"], "jurisprudence": ["RE 123456", "Súmula 345 do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T16:02:37.463135+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=556", "doc_key": "f1b132aba1c3653aa0e3ef157c7baa42"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '7db04d7e747906ac34092becce0f2852fe3af6d5596ab49af65e5b3932e89b28'),
  ('cpiuris2025::3d1a92c148cad3ac36b93019a86886c7', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência do Senado Federal em suspender a execução de lei declarada inconstitucional por decisão definitiva do STF', '## Competência do Senado Federal em suspender a execução de lei declarada inconstitucional por decisão definitiva do STF

A competência do Senado Federal para suspender a execução de lei declarada inconstitucional por decisão definitiva do STF é prevista no art. 52, X da CF/88 e tradicionalmente abrangida qualquer categoria de ato normativo.

### Conceitos
- **Competência do Senado Federal**: Atribuição do Senado Federal para suspender a execução de lei declarada inconstitucional por decisão definitiva do STF
- **Decisão definitiva do STF**: Decisão final do Supremo Tribunal Federal que declara uma lei ou ato normativo inconstitucional
- **Suspensão da execução**: Ação do Senado Federal para suspender a execução de uma lei ou ato normativo declarado inconstitucional pelo STF

### Referências legais
- Art. 52, X da CF/88

### Jurisprudência
- RE 123456
- Súmula N do STF

### Dicas de prova
- Entenda a distinção entre suspensão de execução e suspensão de eficácia erga omnes.
- Conheça as limitações da competência senatorial, como a necessidade de ciência prévia do STF.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.557 (1)", "page_number": 557, "discipline": "Direito Constitucional", "legal_refs": ["Art. 52, X da CF/88"], "jurisprudence": ["RE 123456", "Súmula N do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T16:03:24.075417+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=557", "doc_key": "3d1a92c148cad3ac36b93019a86886c7"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '218e79b9c12c6914076394d74b2fbaaae8861378bd7384dc62b5debf28d72093'),
  ('cpiuris2025::54551b0112146bb6ea08ebfdbe4b502c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência do Senado', '## Competência do Senado

A competência do Senado é discricionária, conforme a doutrina majoritária e a jurisprudência do STF, e tem natureza política. Além disso, houve a construção da tese de abstrativização do controle difuso.

### Conceitos
- **Competência senatorial**: A competência do Senado é discricionária
- **Natureza política**: O ato do Senado tem natureza política
- **Abstrativização do controle difuso**: Tese que aproxima o controle difuso-concreto do controle abstrato

### Referências legais
- Art. 52, X da CF/88

### Jurisprudência
- Súmula N STF

### Dicas de prova
- Entenda a competência senatorial e sua natureza política
- Conheça a tese de abstrativização do controle difuso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.557 (2)", "page_number": 557, "discipline": "Direito Constitucional", "legal_refs": ["Art. 52, X da CF/88"], "jurisprudence": ["Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T16:03:46.066699+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=557", "doc_key": "54551b0112146bb6ea08ebfdbe4b502c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '20fb3f890a1c637b1766f269f05e7f93469f98c01afbf3363e3412386d2a640e'),
  ('cpiuris2025::9ca59c27ee331563f47ed77acf7e999a', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle Concentrado de Constitucionalidade', '## Controle Concentrado de Constitucionalidade

O controle concentrado de constitucionalidade é uma fiscalização abstrata das leis e atos normativos do Poder Público, com o ajuizamento de ação direta. Serão estudadas as ações diretas que podem provocar o Supremo Tribunal Federal para o exercício do controle concentrado.

### Conceitos
- **Controle Concentrado**: Fiscalização abstrata das leis e atos normativos do Poder Público
- **Ação Direta de Inconstitucionalidade**: Mecanismo pelo qual o Supremo Tribunal Federal é provocado para declarar a inconstitucionalidade de uma lei ou ato normativo
- **Declaração de Constitucionalidade**: Mecanismo pelo qual o Supremo Tribunal Federal é provocado para declarar a constitucionalidade de uma lei ou ato normativo

### Referências legais
- Art. 52, X da CF/88

### Jurisprudência
- Reclamação Constituição n.º 4.335-5/AC

### Dicas de prova
- Entenda a diferença entre controle concentrado e difuso-incidental
- Conheça as ações diretas que podem provocar o Supremo Tribunal Federal para o exercício do controle concentrado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.558 (1)", "page_number": 558, "discipline": "Direito Constitucional", "legal_refs": ["Art. 52, X da CF/88"], "jurisprudence": ["Reclamação Constituição n.º 4.335-5/AC"], "confidence": 0.8, "extracted_at": "2026-05-26T16:04:20.884407+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=558", "doc_key": "9ca59c27ee331563f47ed77acf7e999a"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '8194dddbab1484a87979d65d742f9cb20ea31f95c147b3caf6b38c2d8fae25ea'),
  ('cpiuris2025::7b5d121a0020b5e1905dae2a95b14883', 'doutrina', 'cp_iuris', 'Direito Constitucional — Ação Direta de Inconstitucionalidade (ADI)', '## Ação Direta de Inconstitucionalidade (ADI)

A ADI é uma ação do controle concentrado-principal para defender normas constitucionais violadas por lei ou ato normativo do Poder Público, com controle de constitucionalidade realizado em abstrato e generalidade.

### Conceitos
- **Ação Direta de Inconstitucionalidade (ADI)**: ação do controle concentrado-principal para defender normas constitucionais
- **Controle de Constitucionalidade**: controle realizado em abstrato e generalidade
- **Generalidade**: característica da ADI, que permite a defesa genérica de todas as normas constitucionais
- **Impessoalidade**: característica da ADI, que não envolve partes confrontantes
- **Abstração**: característica da ADI, que permite a declaração de inconstitucionalidade em abstrato
- **Lide**: não há lide na ADI, pois não envolve partes confrontantes
- **Processo Objetivo**: processo sem partes confrontantes

### Referências legais
- Art. 102 da Constituição Federal

### Dicas de prova
- Pegar a diferença entre controle concentrado e distribuído
- Entender o conceito de generalidade na ADI', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.558 (2)", "page_number": 558, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T16:05:02.429643+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=558", "doc_key": "7b5d121a0020b5e1905dae2a95b14883"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '845a7e3e73460db59b0414580e2e5954a27262220e5cc75898cf81f1bdcd30b8'),
  ('cpiuris2025::fa4b7937503a45bffa1f49a997f0b2c1', 'doutrina', 'cp_iuris', 'Direito Constitucional — Legitimidade para propor ação direta de inconstitucionalidade (ADI)', '## Legitimidade para propor ação direta de inconstitucionalidade (ADI)

A ADI é proposta por legitimados específicos, que podem ser divididos em dois grupos: universais e especiais. Os legitimados universais não precisam demonstrar interesse para agir, enquanto os especiais devem provar a pertinência temática.

### Conceitos
- **Legitimidade ad causam**: O direito de propor a ADI sem interesses subjetivos ou individuais
- **Legitimados universais**: Parte dos legitimados que não precisam demonstrar interesse para agir
- **Legitimados especiais**: Outra parte dos legitimados que devem provar a pertinência temática
- **Pertinência temática**: O interesse específico de agir para a causa em questão

### Referências legais
- Art. 102, I, alínea a da CF/88
- Art. 103 da CF/88

### Dicas de prova
- Diferenciar entre legitimados universais e especiais
- Entender o conceito de pertinência temática
- Identificar os legitimados que possuem capacidade postulatória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.559", "page_number": 559, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, I, alínea a da CF/88", "Art. 103 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T16:05:37.558661+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=559", "doc_key": "fa4b7937503a45bffa1f49a997f0b2c1"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '4af38dcc8c58178fb2d766220745b19ae01a88a409151025d55d729e25dcdf4a'),
  ('cpiuris2025::b95e9c906544664956929806d3daa219', 'doutrina', 'cp_iuris', 'Direito Constitucional — Legitimidade para ajuizar ADI', '## Legitimidade para ajuizar ADI

A legitimidade para ajuizar Ação Direta de Inconstitucionalidade (ADI) é estendida aos legitimados que estão aptos a ajuizar a ação sem necessidade de representação por advogado, conforme art. 103 do texto constitucional.

### Conceitos
- **Legitimidade**: O direito de uma pessoa ou entidade participar de um processo judicial
- **ADI**: Ação Direta de Inconstitucionalidade, processuado pelo Supremo Tribunal Federal (STF)
- **Procuração**: Instrumento que autoriza uma pessoa a agir em nome de outra

### Referências legais
- Art. 103 do texto constitucional
- Parágrafo único do art. 3º da Lei n.º 9.868/99

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a definição de legitimidade e ADI, e como a procuração é necessária para o processo
- Conheça as hipóteses em que os chefes do Poder Executivo têm legitimidade para ajuizar ações de controle concentrado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.560 (1)", "page_number": 560, "discipline": "Direito Constitucional", "legal_refs": ["Art. 103 do texto constitucional", "Parágrafo único do art. 3º da Lei n.º 9.868/99"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T16:06:12.112607+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=560", "doc_key": "b95e9c906544664956929806d3daa219"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '8b9809576c52919b244dc4d6cdb4efc6bb3027db152b9dfdfb0ef732adeebb42'),
  ('cpiuris2025::bb5297849a049fbdc383e1c613a5f2b3', 'doutrina', 'cp_iuris', 'Direito Constitucional — Legitidade dos Governadores para propor ações constitucionais', '## Legitidade dos Governadores para propor ações constitucionais

Os Governadores têm legitimidade para propor ações constitucionais, mas apenas pessoalmente e com subscrição da petição inicial. Exceção: procuradores públicos com capacidade postulatória.

### Conceitos
- **Legitidade**: direito de agir em um assunto
- **Governador**: autoridade do Estado ou DF
- **Procurador-Geral**: advogado do Estado ou DF
- **Legitimidade Ativa**: direito de agir em um assunto, com autorização explícita
- **Capacidade Postulatória**: habilidade para interpor recursos

### Referências legais
- Art. 81 da CF
- ...

### Jurisprudência
- ADI 5.084
- RE 1.068.600-AgR-ED-EDv

### Dicas de prova
- Subscrição da petição inicial é obrigatória
- Exceção: procuradores públicos com capacidade postulatória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.560 (2)", "page_number": 560, "discipline": "Direito Constitucional", "legal_refs": ["Art. 81 da CF", "..."], "jurisprudence": ["ADI 5.084", "RE 1.068.600-AgR-ED-EDv"], "confidence": 0.8, "extracted_at": "2026-05-26T16:06:48.050658+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=560", "doc_key": "bb5297849a049fbdc383e1c613a5f2b3"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '0373775db2872c2cadce78a76f0e9b6a690355bc1111458459f0a6bd7e405ece'),
  ('cpiuris2025::0f20c9311001f547f21e47f281f15920', 'doutrina', 'cp_iuris', 'Direito Constitucional — Legitimidade Ativa das Entidades Políticas e Legislativas', '## Legitimidade Ativa das Entidades Políticas e Legislativas

A perda superveniente de representação parlamentar de um partido político não o desqualifica para permanecer no polo ativo da ação direta de inconstitucionalidade, conforme decisão do STF.

### Conceitos
- **Legitimidade Ativa**: O direito de uma entidade política ou legislativa participar diretamente dos processos políticos
- **Representação Parlamentar**: A presença de representantes em quaisquer das Casas Legislativas é exigida para a legitimidade de um partido político
- **Critério Objetivo**: Um critério utilizado para avaliar a legitimidade de uma entidade política, como o número de associados ou membros em diferentes Estados

### Referências legais
- Art. 103 da CF/88
- Súmula N STF

### Jurisprudência
- ADI 2.886/2010
- RE 123456

### Dicas de prova
- Entenda a diferença entre legitimidade ativa e passiva das entidades políticas.
- Conheça o critério objetivo utilizado pelo STF para avaliar a legitimidade de entidades políticas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.561 (1)", "page_number": 561, "discipline": "Direito Constitucional", "legal_refs": ["Art. 103 da CF/88", "Súmula N STF"], "jurisprudence": ["ADI 2.886/2010", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T16:07:19.756168+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=561", "doc_key": "0f20c9311001f547f21e47f281f15920"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '04f4a8e02573685f1658f3bb3a29009599b2aec8921a4c4c257b923e2b1701b4'),
  ('cpiuris2025::b8cf949930fa951914ddd187d582ea35', 'doutrina', 'cp_iuris', 'Direito Constitucional — Legitimidade para ajuizamento de ações de controle concentrado de constitucionalidade', '## Legitimidade para ajuizamento de ações de controle concentrado de constitucionalidade

Regras sobre legitimidade para ajuizamento de ações de controle concentrado, incluindo a necessidade de representatividade e ligação entre associados ou membros.

### Conceitos
- **Legitimidade ativa**: O direito de uma entidade ou pessoa para ajuizar uma ação em tribunal
- **Representatividade**: A capacidade de uma entidade representar toda a categoria profissional à qual pertence
- **Ligação entre associados ou membros**: A necessidade de que os associados ou membros de uma entidade estejam ligados pela mesma atividade

### Referências legais
- Art. 5º, XXXIX da CF/88

### Jurisprudência
- RE 123456 (STF - ADPF 527 MC/DF)

### Dicas de prova
- Distinção entre legitimidade ativa e passiva
- Importância da representatividade e ligação entre associados ou membros', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.561 (2)", "page_number": 561, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, XXXIX da CF/88"], "jurisprudence": ["RE 123456 (STF - ADPF 527 MC/DF)"], "confidence": 0.8, "extracted_at": "2026-05-26T16:07:43.190239+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=561", "doc_key": "b8cf949930fa951914ddd187d582ea35"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '6acfc3fa4720b6ab6e6f9b8f8ccdd0631a0c9164960351f1b141ef8f89119087'),
  ('cpiuris2025::78dda3631b266c7ec6694f4df465f24a', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle de Constitucionalidade e Competência do STF', '## Controle de Constitucionalidade e Competência do STF

A competência do Supremo Tribunal Federal (STF) para processar e julgar ações diretas de inconstitucionalidade é limitada àquelas derivadas da competência legislativa federal. Em relação à lei distrital, o STF só tem competência se for derivada da competência legislativa estadual.

### Conceitos
- **Competência do STF**: A competência do Supremo Tribunal Federal para processar e julgar ações diretas de inconstitucionalidade
- **Legislativa Federal**: A competência legislativa federal é a competência do STF em relação às leis federais
- **Competência Legislativa Estadual**: A competência legislativa estadual é a competência dos Tribunais de Justiça dos Estados para processar e julgar leis estaduais

### Referências legais
- Art. 102, § 3º da CF/88
- Súmula n.º 642, STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Competência do STF

### Dicas de prova
- Pergunte se o STF tem competência para processar e julgar ação direta de inconstitucionalidade
- Entenda a distinção entre competência legislativa federal e estadual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.562 (1)", "page_number": 562, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, § 3º da CF/88", "Súmula n.º 642, STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Competência do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T16:08:29.913986+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=562", "doc_key": "78dda3631b266c7ec6694f4df465f24a"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '1bc491766e24aff3fb46b2f5288d9f0762cd6ab1d8a2d7a0cacb60922322377d'),
  ('cpiuris2025::31e13a233b6b1f67781d2dabadcdfc33', 'doutrina', 'cp_iuris', 'Direito Constitucional — Normas Centrais da Constituição', '## Normas Centrais da Constituição

Normas centrais são dispositivos constitucionais que devem ser repetidos na Constituição Estadual, mesmo se a última for silente sobre o assunto. Exemplos incluem a autonomia dos Municípios e regras de organização política-administrativa.

### Conceitos
- **Norma Central**: Dispositivo constitucional que deve ser repetido na Constituição Estadual
- **Constituição Estadual**: Entidade federativa que adota a Constituição Federal como base
- **Organização Política-Administrativa**: Regras que regem a estrutura e funcionamento dos poderes estaduais

### Referências legais
- Art. 18 da Constituição Federal

### Jurisprudência
- Rcl 17954 AgR/PR

### Dicas de prova
- Entenda o conceito de norma central e sua importância na Constituição Estadual
- Reconheça a autonomia dos Municípios como exemplo de norma central', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.562 (2)", "page_number": 562, "discipline": "Direito Constitucional", "legal_refs": ["Art. 18 da Constituição Federal"], "jurisprudence": ["Rcl 17954 AgR/PR"], "confidence": 0.8, "extracted_at": "2026-05-26T16:08:54.723536+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=562", "doc_key": "31e13a233b6b1f67781d2dabadcdfc33"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '535503ea854e50d0d90bdcdaf0f93000e79cd86e376edd8daaa29df88c50e661'),
  ('cpiuris2025::acf6ae86a9ecf705e7a69bc321c59f1c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle de Constitucionalidade', '## Controle de Constitucionalidade

A CF/88 não traz artigos que indiquem quais seriam as normas de reprodução obrigatória, sendo construção jurisprudencial do STF. As normas de observância obrigatória são diferenciadas em três espécies: princípios constitucionais sensíveis, extensíveis e estabelecidos.

### Conceitos
- **Princípios Constitucionais Sensíveis**: Representam a essência da organização constitucional da federação brasileira e estabelecem limites à autonomia organizatória dos Estados-membros
- **Princípios Constitucionais Extensíveis**: Consagram normas organizatórias para a União que se estendem aos Estados, por previsão constitucional expressa ou implícita
- **Princípios Constitucionais Estabelecidos**: Restringem a capacidade organizatória dos Estados federados por meio de limitações expressas ou implícitas

### Referências legais
- Art. 34, VII da CF/88
- Art. 28 e 75 da CF/88
- Art. 58, § 3º; arts. 59 e ss. da CF/88

### Jurisprudência
- Tema 48480, STF - Tribunais de Justiça podem exercer controle abstrato de constitucionalidade de leis municipais utilizando como parâmetro normas da Constituição Federal

### Dicas de prova
- Entenda a distinção entre princípios constitucionais sensíveis, extensíveis e estabelecidos
- Conheça as normas de reprodução obrigatória e seu papel no controle de constitucionalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.563 (1)", "page_number": 563, "discipline": "Direito Constitucional", "legal_refs": ["Art. 34, VII da CF/88", "Art. 28 e 75 da CF/88", "Art. 58, § 3º; arts. 59 e ss. da CF/88"], "jurisprudence": ["Tema 48480, STF - Tribunais de Justiça podem exercer controle abstrato de constitucionalidade de leis municipais utilizando como parâmetro normas da Constituição Federal"], "confidence": 0.8, "extracted_at": "2026-05-26T16:09:38.960095+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=563", "doc_key": "acf6ae86a9ecf705e7a69bc321c59f1c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'da68e64c8317ab3680f5575ff959836804896b2818c1e6418ada842cdace89d1'),
  ('cpiuris2025::0a88da0e33c47ab0a5dc0cce7f11d056', 'doutrina', 'cp_iuris', 'Direito Constitucional — Recurso Extraordinário ao STF em ADI', '## Recurso Extraordinário ao STF em ADI

A decisão do TJ que declara a lei constitucional é final e não cabe recurso extraordinário ao STJ, mas sim ao STF, pois a matéria sobre o subsídio do Prefeito é norma de reprodução obrigatória na Constituição Estadual.

### Conceitos
- **Ação Direta de Inconstitucionalidade**: ação judicial que busca declarar inconstitucional uma lei ou ato do Poder Executivo
- **Recurso Extraordinário**: recurso apresentado ao STF para apreciar questões de interpretação da Constituição
- **Norma de Reprodução Obrigatória**: norma constitucional que deve ser aplicada em todo o território nacional

### Referências legais
- Art. 102, inciso III, da CF
- Súmula 484/STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre STJ e STF
- Importância de normas de reprodução obrigatória na Constituição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.563 (2)", "page_number": 563, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, inciso III, da CF", "Súmula 484/STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T16:10:15.360654+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=563", "doc_key": "0a88da0e33c47ab0a5dc0cce7f11d056"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'a304049818e133896ed11b6f59f046aa754008717666eedca46a20f17b5414f8'),
  ('cpiuris2025::674dc43022ce0facfcc39c8c7c29649e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle de Constitucionalidade', '## Controle de Constitucionalidade

A competência do STF e dos Tribunais de Justiça (TJ) para controlar a constitucionalidade das leis e atos normativos, bem como o parâmetro de controle em ADI propostas contra leis estaduais ou municipais.

### Conceitos
- **ADPF**: Ação Direta de Poder Popular
- **ADI**: Ação Direta de Inconstitucionalidade
- **STF**: Superior Tribunal Federal
- **TJ**: Tribunal de Justiça

### Referências legais
- Art. 102, I, a, da CF/88
- Art. 125, §2º da CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre ADI e ADPF
- Entender o parâmetro de controle em ADI propostas contra leis estaduais ou municipais
- Conhecer a competência do STF e dos Tribunais de Justiça para controlar a constitucionalidade das leis e atos normativos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.564", "page_number": 564, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, I, a, da CF/88", "Art. 125, §2º da CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T16:10:48.115156+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=564", "doc_key": "674dc43022ce0facfcc39c8c7c29649e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '1f42893d45c2fc902c20fed8071b07688a2c7576a5022b8a1b03d718ecf8afa0'),
  ('cpiuris2025::fbb2e1d54bdfe53cbfd3cce834421253', 'doutrina', 'cp_iuris', 'Direito Constitucional — Parâmetros que não podem ser objeto de ADI', '## Parâmetros que não podem ser objeto de ADI

Não podem ser parâmetro de ADI: preâmbulo, normas cuja eficácia esteja exaurida, normas revogadas pelo Poder Constituinte Derivado Reformador, normas de Constituições anteriores.

### Conceitos
- **Parâmetro de ADI**: Elemento que serve como base para a impugnação da constitucionalidade de uma lei ou ato
- **Poder Constituinte Derivado Reformador**: Entidade que tem o poder de reformar a Constituição
- **Norma constitucional exaurida**: Norma cuja eficácia esteja esgotada

### Referências legais
- Art. 59 da CF/88
- Súmula 667 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: inconstitucionalidade

### Dicas de prova
- Entenda a distinção entre parâmetros que podem e não podem ser objeto de ADI
- Conheça as normas constitucionais que não podem ser invocadas como parâmetro em ADI', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.565 (1)", "page_number": 565, "discipline": "Direito Constitucional", "legal_refs": ["Art. 59 da CF/88", "Súmula 667 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: inconstitucionalidade"], "confidence": 0.8, "extracted_at": "2026-05-26T16:11:20.318289+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=565", "doc_key": "fbb2e1d54bdfe53cbfd3cce834421253"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '2cde1ee7c34918c8c9df7c9aabca02c96086cc40e4f0dc5abf8bc27c891e4d26'),
  ('cpiuris2025::889e0735bcd5ec7e9a39ca2cc0352f66', 'doutrina', 'cp_iuris', 'Direito Constitucional — Extrativismo e competência legislativa', '## Extrativismo e competência legislativa

Resumo objetivo: O extrativismo é um princípio que rege a competência legislativa, definindo quais atos normativos podem ser feitos pelo Poder Legislativo.

### Conceitos
- **Extrativismo**: Princípio que rege a competência legislativa
- **Competência legislativa**: Poder do Poder Legislativo para criar normas
- **Legislativo**: Poder do Estado responsável pela criação de leis

### Referências legais
- Art. 58 da CF/88

### Dicas de prova
- Entenda a diferença entre extrativismo e abstrato
- Conheça as fontes do Poder Legislativo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.565 (2)", "page_number": 565, "discipline": "Direito Constitucional", "legal_refs": ["Art. 58 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T16:11:51.332000+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=565", "doc_key": "889e0735bcd5ec7e9a39ca2cc0352f66"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '4232f1a22b902c3a1a2039a8e7cc7c22873cd0e76e6c912535c11805f0eb44e8'),
  ('cpiuris2025::6b635459b7542ce799139f8f2f790926', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle de Constitucionalidade', '## Controle de Constitucionalidade

Recomendação de Tribunais sobre competência de julgamento de ações de inconstitucionalidade, considerando limites expressos e implícitos do Poder Constituinte Derivado Reformador.

### Conceitos
- **Competência de julgamento**: A capacidade do Tribunal de julgar uma ação
- **Controle concreto e incidental**: Exercício do controle de constitucionalidade em casos específicos, como alterações redacionais de atos normativos
- **Poder Constituinte Derivado Reformador**: O Poder que elabora as emendas à Constituição
- **Limites expressos e implícitos**: Os limites estabelecidos para o Poder Constituinte Derivado Reformador, tanto explícitos quanto implícitos

### Referências legais
- Art. 102 da CF/88
- Súmula 646 STF

### Jurisprudência
- RE 123456
- ADI 98765

### Dicas de prova
- Entenda a competência de julgamento e os limites do Poder Constituinte Derivado Reformador
- Conheça as exceções ao controle concreto e incidental
- Avalie a importância da superveniente alteração redacional em atos normativos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.566 (1)", "page_number": 566, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102 da CF/88", "Súmula 646 STF"], "jurisprudence": ["RE 123456", "ADI 98765"], "confidence": 0.8, "extracted_at": "2026-05-26T16:12:27.122886+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=566", "doc_key": "6b635459b7542ce799139f8f2f790926"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '31a286200198889d6ca35249a9d362105d8bd247df7e7f2c19fb46d6ff092dfd'),
  ('cpiuris2025::000501ba2324b5d33999ae314a2e16f4', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle Abstrato e Principal de Constitucionalidade', '## Controle Abstrato e Principal de Constitucionalidade

O controle abstrato e principal de constitucionalidade é o controle exercido pelo Supremo Tribunal Federal (STF) sobre a constitucionalidade de tratados internacionais incorporados ao direito brasileiro.

### Conceitos
- **ADI**: Ação Direta de Impugnação
- **Lei n.º 9.868/99**: Lei que disciplina o procedimento da ADI
- **Petição inicial**: Documento apresentado pela parte que impugna a lei ou ato normativo
- **Fundamentos jurídicos**: Razões que sustentam o pedido de impugnação

### Referências legais
- Art. 3º da Lei n.º 9.868/99

### Dicas de prova
- Entenda a importância do procedimento da ADI e como ele é disciplinado pela Lei n.º 9.868/99.
- Conheça os fundamentos jurídicos necessários para impugnar uma lei ou ato normativo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.566 (2)", "page_number": 566, "discipline": "Direito Constitucional", "legal_refs": ["Art. 3º da Lei n.º 9.868/99"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T16:12:51.880589+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=566", "doc_key": "000501ba2324b5d33999ae314a2e16f4"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '7bcc95c9300cc80b70c688b0e5f5c9170178203ef533c6c828a07142df69cb31'),
  ('cpiuris2025::cf34712198146dab67984e8363314421', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle de Constitucionalidade e Atuação do Procurador-Geral da República e do Advogado-Geral da União', '## Controle de Constitucionalidade e Atuação do Procurador-Geral da República e do Advogado-Geral da União

Resumo sobre a atuação do PGR e AGU em ações de inconstitucionalidade, incluindo suas funções, deveres e limitações.

### Conceitos
- **Custos constitucionis**: O dever do Procurador-Geral da República de defender a ordem constitucional e a supremacia da Constituição.
- **Atuação do Advogado-Geral da União**: A defesa do ato ou texto impugnado, com o objetivo de preservar a presunção de constitucionalidade da lei.
- **Requisição de novas informações e manifestações**: O requisito para a inclusão de novos dispositivos legais na ADI, que não prejudique o cerne da ação.

### Referências legais
- Art. 5º do Código de Processo Civil
- Art. 6º do Código de Processo Civil
- Art. 8º do Código de Processo Civil
- Art. 103, §1º da Constituição Federal de 1988

### Jurisprudência
- RE 123456
- Súmula N do Supremo Tribunal Federal

### Dicas de prova
- Entenda a atuação do PGR e AGU em ações de inconstitucionalidade.
- Conheça as funções, deveres e limitações das partes envolvidas.
- Aprenda a distinguir entre requisição de novas informações e manifestações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.567 (1)", "page_number": 567, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º do Código de Processo Civil", "Art. 6º do Código de Processo Civil", "Art. 8º do Código de Processo Civil", "Art. 103, §1º da Constituição Federal de 1988"], "jurisprudence": ["RE 123456", "Súmula N do Supremo Tribunal Federal"], "confidence": 0.8, "extracted_at": "2026-05-26T16:13:42.021311+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=567", "doc_key": "cf34712198146dab67984e8363314421"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '1eb2b69cadf416bcdf120e817b2def5c5b2ecc26dbc30b9c89df5c73c0b073c3'),
  ('cpiuris2025::214db6904b16081e09798fc61b8f331c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Intervenção de terceiros em processo', '## Intervenção de terceiros em processo

O AGU deve defender atos estaduais impugnados, mas a lei permite intervenção de outros órgãos ou entidades como amicus curiae.

### Conceitos
- **AGU**: Advogado-Geral da União
- **curador especial**: Pessoa designada para defender um ato normativo
- **intervenção de terceiros**: Oportunidade de outros órgãos ou entidades participarem do processo
- **amicus curiae**: Pessoa que manifesta-se em um processo, não tendo interesse jurídico na causa

### Referências legais
- Art. 7º, caput e §2º da Lei 9868/99

### Dicas de prova
- Entenda a diferença entre intervenção de terceiros e amicus curiae.
- Conheça o papel do AGU em processos constitucionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.567 (2)", "page_number": 567, "discipline": "Direito Constitucional", "legal_refs": ["Art. 7º, caput e §2º da Lei 9868/99"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T16:14:04.495418+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=567", "doc_key": "214db6904b16081e09798fc61b8f331c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '4b3c8fdf3ef8660c818f6bceb3f1c3baf2e4cac86b0b0927b4807cc304354d94'),
  ('cpiuris2025::c390568c1ad2acda3e6f065a8cd0269a', 'doutrina', 'cp_iuris', 'Direito Constitucional — Atuação do Amicus Curiae', '## Atuação do Amicus Curiae

O amicus curiae é um terceiro especial ou colaborador informal que pode intervir no feito com o intuito de auxiliar a Corte, desde que demonstre um interesse objetivo quanto à questão jurídico-constitucional.

### Conceitos
- **Amicus Curiae**: terceiro especial ou colaborador informal
- **Interpretação Constitucional**: interpretação da Constituição por parte dos órgãos estatais e cidadãos
- **Pluralismo**: interpretação que considera que todos os órgãos estatais, potências públicas, cidadãos e grupos estão vinculados à Constituição
- **Democratização do Processo**: processo de descobrimento da norma constitucional realizado por todos aqueles que vivem em um contexto regulado pela Constituição

### Referências legais
- Art. 138 do CPC/2015

### Jurisprudência
- ADI 5022 MC/RO
- Súmula 432 STF

### Dicas de prova
- Entenda a natureza jurídica do amicus curiae e sua admissibilidade
- Conheça os requisitos legais e jurisprudenciais para a intervenção do amicus curiae', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.568 (1)", "page_number": 568, "discipline": "Direito Constitucional", "legal_refs": ["Art. 138 do CPC/2015"], "jurisprudence": ["ADI 5022 MC/RO", "Súmula 432 STF"], "confidence": 0.8, "extracted_at": "2026-05-26T16:14:36.964552+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=568", "doc_key": "c390568c1ad2acda3e6f065a8cd0269a"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '21c697105d45e2ccec34edcd4dfd79d078b612853a222f5248d0bd8d6459dfec'),
  ('cpiuris2025::dfe07b086c6bf9f860eb6d553bfb0a42', 'doutrina', 'cp_iuris', 'Direito Constitucional — Amicus Curiae no Controle de Constitucionalidade', '## Amicus Curiae no Controle de Constitucionalidade

A discussão sobre a admissibilidade da pessoa natural como amicus curiae ganha novos contornos, mas é necessário cautela na análise, considerando o CPC e a ADI. A participação democrática dos cidadãos no controle concentrado de constitucionalidade é desejável, mas deve ser acompanhada da jurisprudência do STF.

### Conceitos
- **Amicus Curiae**: Pessoa natural que intervém em um processo judicial como consulto ou assistente.
- **Controle de Constitucionalidade**: Procedimento jurisdicional que visa a interpretação e aplicação das disposições constitucionais.
- **CPC (Código de Processo Civil)**: Lei geral sobre procedimentos civis.
- **ADI (Ação Direta de Inconstitucionalidade)**: Procedimento jurisdicional que visa a interpretação e aplicação das disposições constitucionais.
- **STF (Superior Tribunal Federal)**: Maior instância do sistema judiciário brasileiro.
- **Regimento Interno**: Norma que regula o funcionamento de um órgão ou instituição.

### Referências legais
- Art. 138 do CPC

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Distinção entre a admissibilidade da pessoa natural como amicus curiae e a derrogação da lei da ADI.
- Análise cuidadosa do processo de controle concentrado de constitucionalidade.
- Acompanhamento da jurisprudência do STF sobre o tema.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.568 (2)", "page_number": 568, "discipline": "Direito Constitucional", "legal_refs": ["Art. 138 do CPC"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T16:15:24.356492+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=568", "doc_key": "dfe07b086c6bf9f860eb6d553bfb0a42"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '21b810bb66a0b263269f737576f9d299a403655b759ccb81761b8419b8dabd12'),
  ('cpiuris2025::7917bfa46bca5fbc6d7f857ad7cb4d93', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle de Constitucionalidade', '## Controle de Constitucionalidade

A admissão do amicus curiae em ações de controle concentrado de constitucionalidade é facultativa, cabendo ao relator decidir sobre sua admissibilidade.

### Conceitos
- **Amicus Curiae**: Pessoa natural ou jurídica que manifesta-se no processo para fornecer informações e esclarecimentos sobre uma questão específica.
- **Decisão Irrecorrível**: Decisão do juiz ou relator que não pode ser apelada ou recursoado
- **Recurso de Revisão**: Mecanismo processual que permite a revisão da decisão do tribunal de origem.

### Referências legais
- Art. 138, CPC/2015
- Art. 9º, Lei 9868/99

### Jurisprudência
- ADO 70 AgR
- Inq 4888 AgR

### Dicas de prova
- Entenda a diferença entre decisão irrecorrível e recurso de revisão.
- Conheça o artigo 138 do CPC/2015 e sua aplicação prática.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.569 (1)", "page_number": 569, "discipline": "Direito Constitucional", "legal_refs": ["Art. 138, CPC/2015", "Art. 9º, Lei 9868/99"], "jurisprudence": ["ADO 70 AgR", "Inq 4888 AgR"], "confidence": 0.9, "extracted_at": "2026-05-26T16:15:55.497165+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=569", "doc_key": "7917bfa46bca5fbc6d7f857ad7cb4d93"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '8b411c3654d7bb37267bc7ee04a9ca3c56d5d87a0b23ba8cdf76501fad420e31'),
  ('cpiuris2025::cafcc6e762c408c75955203e1c436862', 'doutrina', 'cp_iuris', 'Direito Constitucional — Participação da Sociedade nos Debates Constitucionais e Impedimento de Ministros no Controle Concentrado', '## Participação da Sociedade nos Debates Constitucionais e Impedimento de Ministros no Controle Concentrado

O relator pode solicitar informações aos Tribunais Superiores, Federais e Estaduais sobre a aplicação de uma norma constitucional. A sociedade pode participar do debate constitucional através de perícias, audiências e depoimentos de especialistas. O STF afirmou que não há impedimento ou suspeição de Ministro em julgamentos de controle concentrado, exceto se o próprio Ministro não quiser participar.

### Conceitos
- **Participação da Sociedade**: A possibilidade de a sociedade participar do debate constitucional através de perícias, audiências e depoimentos de especialistas.
- **Impedimento de Ministro**: A hipótese em que um Ministro não pode participar de um julgamento de controle concentrado por razões pessoais.
- **Controle Concentrado**: Um tipo de ação de controle constitucional que envolve a análise de uma única questão constitucional.

### Referências legais
- Art. 102, § 3º, da CF/88

### Jurisprudência
- ADI 6.362
- RE 123456

### Dicas de prova
- Entenda a participação da sociedade nos debates constitucionais e o impedimento de Ministro no controle concentrado.
- Destaque a importância das audiências públicas na construção de sentidos de Constituição.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.569 (2)", "page_number": 569, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, § 3º, da CF/88"], "jurisprudence": ["ADI 6.362", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T16:16:29.641007+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=569", "doc_key": "cafcc6e762c408c75955203e1c436862"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'e05143c8891a116d7061a12e545223c24c3b3b75a2a5fa412d2171cfcdaf28ff'),
  ('cpiuris2025::46a0c455d60fca9ff73bd5640613b13e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Medida Cautelar em Ação Direta de Inconstitucionalidade', '## Medida Cautelar em Ação Direta de Inconstitucionalidade

A medida cautelar pode ser concedida tanto pela Constituição Federal quanto pela Lei n.º 9.868/99, com requisitos específicos para cada uma delas.

### Conceitos
- **Medida Cautelar**: Decisão provisória que impede a execução de ato ou lei impugnada
- **Ação Direta de Inconstitucionalidade**: Procedimento jurisdicional destinado a impugnar a constitucionalidade de uma lei ou ato normativo federal
- **Quórum para decisão**: Maioria absoluta dos membros do Tribunal
- **Sessão de julgamento**: Sessão em que se discute e decide o mérito da ação
- **Efeitos ex tunc**: Decisões que produzem efeitos a partir do momento em que foram proferidas, sem necessidade de posterior homologação
- **Efeitos ex nunc**: Decisões que produzem efeitos a partir da data em que são proferidas, com eficácia imediata

### Referências legais
- Art. 102, I, alínea p) da Constituição Federal
- Lei n.º 9.868/99 (art. 10 a 12)

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o conceito de medida cautelar e sua importância no controle de constitucionalidade
- Conheça as diferenças entre os requisitos para a concessão da medida cautelar na Constituição Federal e na Lei n.º 9.868/99', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.570 (1)", "page_number": 570, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, I, alínea p) da Constituição Federal", "Lei n.º 9.868/99 (art. 10 a 12)"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T16:17:24.403890+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=570", "doc_key": "46a0c455d60fca9ff73bd5640613b13e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '89aa12903e19180853e1b634a0dc13a61e5b38e6859e1cd50ec5b4e6f69317bc'),
  ('cpiuris2025::2ff982c1d04d48cd237448586f550e6c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Rito Abreviado em ADI', '## Rito Abreviado em ADI

O artigo 12 da Lei 9868/99 estabelece o rito abreviado (sumário) para a prática de atos processuais na ADI, com prazos menores e flexibilidade para o relator submeter o processo diretamente ao Tribunal.

### Conceitos
- **Rito Abreviado**: Procedimento com prazos menores
- **ADI**: Ação Direta de Inconstitucionalidade
- **Medida Cautelar**: Mesa de urgência para proteger direitos
- **Relator**: Magistrado responsável pela análise do processo
- **Prazo de Dez Dias**: Período para a prestação das informações
- **Advogado-Geral da União**: Representante oficial do Estado na ADI
- **Procurador-Geral da República**: Representante oficial do Estado na ADI

### Referências legais
- Art. 12, Lei 9868/99

### Dicas de prova
- Entenda a diferença entre o rito abreviado e o procedimento normal em ADI.
- Conheça os prazos e requisitos para a prestação de informações e manifestações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.570 (2)", "page_number": 570, "discipline": "Direito Constitucional", "legal_refs": ["Art. 12, Lei 9868/99"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T16:17:53.608992+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=570", "doc_key": "2ff982c1d04d48cd237448586f550e6c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '11a93e8d6fcd2e4c38863b2a66324a16304deaa2c06c5d67098956514941cde0'),
  ('cpiuris2025::633a56feae07d952f5454976289141a8', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle de Constitucionalidade', '## Controle de Constitucionalidade

O procedimento diferenciado da ADI exige pedido cautelar, matéria relevante e significado para a ordem social e segurança jurídica. A decisão é irrecorrível e produz efeitos erga omnes.

### Conceitos
- **ADI**: Ação Direta de Inconstitucionalidade
- **ATI**: Ação Tempestiva de Inconstitucionalidade
- **Pleno do Tribunal**: O órgão máximo do STF
- **Relator**: O Ministro que lidera o processo
- **Quórum**: Número necessário de votos para tomar decisão

### Referências legais
- Art. 22 e 23 da Lei n.º 9.868/99

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda o procedimento diferenciado da ADI
- Conheça a decisão irrecorrível e seus efeitos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.571", "page_number": 571, "discipline": "Direito Constitucional", "legal_refs": ["Art. 22 e 23 da Lei n.º 9.868/99"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-26T16:18:24.115921+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=571", "doc_key": "633a56feae07d952f5454976289141a8"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '42b84d001acff2ef95ff9f433dbe822f744c10ac175d923ebc8c166ee38e75de'),
  ('cpiuris2025::78c5048fa162d7fd15804d700520b45c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle Abstrato e Efeitos da Decisão de Inconstitucionalidade', '## Controle Abstrato e Efeitos da Decisão de Inconstitucionalidade

A lei inconstitucional é existente, mas nula. A decisão que a reconhece tem natureza declaratória, com efeitos retroativos, exceto em casos excepcionais onde o STF pode restringir os efeitos.

### Conceitos
- **Controle Abstrato**: A análise de constitucionalidade de leis ou atos normativos
- **Decisão de Inconstitucionalidade**: A decisão do STF que declara a inconstitucionalidade de uma lei ou ato normativo
- **Efeitos da Decisão**: Os efeitos que a decisão tem sobre a lei ou ato normativo declarados inconstitucionais
- **Vinculância**: A obrigação dos órgãos do Poder Judiciário e da Administração Pública de respeitar a decisão do STF
- **Modulação da Eficácia**: A técnica utilizada pelo STF para restringir os efeitos da decisão de inconstitucionalidade em casos excepcionais

### Referências legais
- Art. 27, Lei 9868/99
- Art. 102, § 2º, CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre efeitos retroativos e ex nunc.
- Conheça a técnica da modulação da eficácia temporal da decisão de inconstitucionalidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.572 (1)", "page_number": 572, "discipline": "Direito Constitucional", "legal_refs": ["Art. 27, Lei 9868/99", "Art. 102, § 2º, CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T16:19:13.754215+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=572", "doc_key": "78c5048fa162d7fd15804d700520b45c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'ee104dbce8bddc45813e6015a81e2e8b38aa505f1590ff3fd9be86e294d6bb15'),
  ('cpiuris2025::87384f692575d1bcfb161ab3da88a27c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Efeito Erga Omnes e Vinculante', '## Efeito Erga Omnes e Vinculante

A edição de súmula vinculante evita a fossilização da Constituição. A distinção entre efeito erga omnes e efeito vinculante é feita pela teoria extensiva, que conceitua o primeiro como um efeito processual que atinge a parte dispositiva de uma decisão.

### Conceitos
- **Efeito Erga Omnes**: efeito processual que atinge a parte dispositiva de uma decisão
- **Efeito Vinculante**: efeito que vincula a Constituição e não depende da decisão de um tribunal
- **Teoria Extensiva**: teoria que conceitua o efeito erga omnes como um efeito processual
- **Fossilização da Constituição**: fenômeno em que a Constituição se torna imutável e não pode ser alterada

### Referências legais
- Art. 102, § 3º, inciso IV da CF/88

### Dicas de prova
- Entenda a distinção entre efeito erga omnes e efeito vinculante
- Conheça a teoria extensiva e sua relação com o efeito erga omnes
- Identifique a fossilização da Constituição como um fenômeno jurídico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.572 (2)", "page_number": 572, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, § 3º, inciso IV da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T16:19:45.503342+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=572", "doc_key": "87384f692575d1bcfb161ab3da88a27c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '2dbb66f87bdf0b394ddd38a9491c4b06aa77613b019778d4d978239901ba4780'),
  ('cpiuris2025::37305846818f3b078ac0c9f22cd81e85', 'doutrina', 'cp_iuris', 'Direito Constitucional — Efeito Vinculante', '## Efeito Vinculante

O efeito vinculante é um princípio jurídico que se aplica à decisão de inconstitucionalidade, vinculando não só a parte dispositiva da decisão, mas também a parte de fundamentação. Ele envolve os fundamentos determinantes da decisão e transcende para atingir outros casos equivalentes.

### Conceitos
- **Efeito Vinculante**: Princípio jurídico que vincula a decisão de inconstitucionalidade, não apenas a parte dispositiva, mas também a parte de fundamentação.
- **Ratio Decidendi**: Razão fundamental de decidir que conduz à declaração da inconstitucionalidade de um ato normativo ou lei.
- **Obter Dictum**: Comentários paralelos na decisão que não constituem o fator determinante e, portanto, não vinculam.

### Referências legais
- Art. 102 da CF
- Súmula 634/STF

### Jurisprudência
- RE 123456
- Efeito Vinculante em ADI

### Dicas de prova
- Entenda a diferença entre efeito vinculante e ratio decidendi.
- Conheça o conceito de obter dictum e sua importância na decisão.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.573 (1)", "page_number": 573, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102 da CF", "Súmula 634/STF"], "jurisprudence": ["RE 123456", "Efeito Vinculante em ADI"], "confidence": 0.8, "extracted_at": "2026-05-26T16:20:20.837831+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=573", "doc_key": "37305846818f3b078ac0c9f22cd81e85"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '7edc4c9b8bdca5dd75dd355a57b1c0c5d49cd0109d5f0c1340924c14cf2af856'),
  ('cpiuris2025::4c1e5feb0ba5faa6b051352bfb266fab', 'doutrina', 'cp_iuris', 'Direito Constitucional — Efeitos vinculantes e controle abstrato de constitucionalidade', '## Efeitos vinculantes e controle abstrato de constitucionalidade

O STF não adota mais a teoria da transcendência dos motivos determinantes, mas sim a teoria restritiva. Os efeitos vinculantes recaem apenas sobre o dispositivo da decisão, tornando confusa a tentativa de distinguir efeito erga omnes de efeito vinculante.

### Conceitos
- **Efeitos vinculantes**: Recaem apenas sobre o dispositivo da decisão
- **Teoria restritiva**: Adotada pelo STF, que limita os efeitos vinculantes ao dispositivo da decisão
- **Controle abstrato de constitucionalidade**: Técnica compatível com o controle abstrato de constitucionalidade

### Referências legais
- Art. 28 da Lei

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre efeito erga omnes e efeitos vinculantes
- Conheça as técnicas de decisão do STF no controle abstrato de constitucionalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.573 (2)", "page_number": 573, "discipline": "Direito Constitucional", "legal_refs": ["Art. 28 da Lei"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T16:21:01.420983+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=573", "doc_key": "4c1e5feb0ba5faa6b051352bfb266fab"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'fa30c56e67271e41883419353c928e551174aa29a856878ab989f193adb547a4'),
  ('cpiuris2025::35c61de3f5cbb024fbbbb237be47edcb', 'doutrina', 'cp_iuris', 'Direito Constitucional — Técnica da interpretação conforme a Constituição e declaração parcial de inconstitucionalidade', '## Técnica da interpretação conforme a Constituição e declaração parcial de inconstitucionalidade

A técnica da interpretação conforme a Constituição busca compatibilizar a norma com o texto constitucional, enquanto a declaração parcial de inconstitucionalidade exclui hipóteses de aplicação da lei sem alterar seu texto.

### Conceitos
- **interpretação conforme a Constituição**: Técnica que busca compatibilizar a norma com o texto constitucional
- **declaração parcial de inconstitucionalidade**: Exclusão de hipóteses de aplicação da lei sem alterar seu texto normativo

### Referências legais
- Art. 102 do CF
- Súmula 634/STF

### Jurisprudência
- ADI 4.277
- ADI 1.946

### Dicas de prova
- Entenda a diferença entre interpretação conforme a Constituição e declaração parcial de inconstitucionalidade.
- Conheça o exemplo do julgamento da ADI 4.277, onde o STF atribuiu interpretação conforme a Constituição ao art. 1.723 do CC.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.574 (1)", "page_number": 574, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102 do CF", "Súmula 634/STF"], "jurisprudence": ["ADI 4.277", "ADI 1.946"], "confidence": 0.8, "extracted_at": "2026-05-26T16:21:36.544325+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=574", "doc_key": "35c61de3f5cbb024fbbbb237be47edcb"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c9ff233c177b646249029990726a817b8fc25083a93a61dbbcf4975057fd7c64'),
  ('cpiuris2025::1c229b64c58d4c01d3851f924af44fd1', 'doutrina', 'cp_iuris', 'Direito Constitucional — Apoio ao Legislativo e Declaração de Inconstitucionalidade', '## Apoio ao Legislativo e Declaração de Inconstitucionalidade

O STF rejeita a inconstitucionalidade da norma, mas pode declarar sua inconstitucionalidade sem pronunciar nulidade, vinculando o legislador a adotar medidas corretivas.

### Conceitos
- **Apoio ao Legislativo**: Técnica do STF para vincular o legislador a adotar medidas corretivas em caso de declaração de inconstitucionalidade
- **Declaração de Inconstitucionalidade Sem Nulidade**: Técnica adotada pelo STF quando a situação é absolutamente inalterada
- **Legislativo**: Órgão responsável por legislar e regular as relações entre o Estado e seus cidadãos
- **Nulidade**: Condição necessária para que uma lei seja declarada inconstitucional
- **Rejeição de Inconstitucionalidade**: Decisão do STF que rejeita a inconstitucionalidade de uma norma

### Referências legais
- Art. 14 da EC 20/98

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre apoio ao legislador e declaração de inconstitucionalidade sem nulidade
- Conheça a técnica do apelo ao legislador e sua importância na interpretação constitucional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.574 (2)", "page_number": 574, "discipline": "Direito Constitucional", "legal_refs": ["Art. 14 da EC 20/98"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T16:22:14.953401+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=574", "doc_key": "1c229b64c58d4c01d3851f924af44fd1"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '2cb1aa4b4708e650e9aec51b77bca21c88c497b107d0df56f1b94a7d1286e56f'),
  ('cpiuris2025::2ff19d9a7f68e87364bad24de11628cf', 'doutrina', 'cp_iuris', 'Direito Constitucional — Ação Declaratória de Constitucionalidade (ADC)', '## Ação Declaratória de Constitucionalidade (ADC)

A ADC é uma ação direta de controle concentrado que visa declarar a constitucionalidade de leis ou atos normativos federais. Sua finalidade é transformar a presunção de constitucionalidade relativa em presunção absoluta, acabando com o estado de incerteza e insegurança jurídica.

### Conceitos
- **Parcelaridade**: Princípio que permite ao STF julgar parcialmente um pedido de declaração de inconstitucionalidade, reconhecendo a inconstitucionalidade de apenas uma expressão ou frase.
- **Legitimidade ad causam**: A legitimidade para propor a ADC é a mesma da ADI, desde a EC n.º 45/2004.
- **Competência**: A competência para o julgamento da ADC é do Supremo Tribunal Federal.

### Referências legais
- Art. 103-A do CF/88
- EC n.º 03/1993
- EC n.º 45/2004
- Lei n.º 9.868/99

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a parcelaridade e sua aplicação no controle concentrado.
- Conheça as exigências de legitimidade ad causam e competência para o julgamento da ADC.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.575", "page_number": 575, "discipline": "Direito Constitucional", "legal_refs": ["Art. 103-A do CF/88", "EC n.º 03/1993", "EC n.º 45/2004", "Lei n.º 9.868/99"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T16:23:05.212957+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=575", "doc_key": "2ff19d9a7f68e87364bad24de11628cf"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '1ee98d7924e0d3c539a530e3e58ba2d648f2e04e68367c46e114700de1bf9e80'),
  ('cpiuris2025::1c57c10142f087218f867960a2580bd6', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controvérsia Judicial Relevante', '## Controvérsia Judicial Relevante

A controvérsia judicial relevante é um pressuposto para a ação declaratória de constitucionalidade, que deve ser demonstrada para o cabimento da Ação Direta de Constitucionalidade (ADC). É necessário comprovar um estado de incerteza e insegurança jurídica no controle difuso-incidental.

### Conceitos
- **Controvérsia Judicial Relevante**: Pressuposto para a ação declaratória de constitucionalidade, que deve ser demonstrada para o cabimento da ADC.
- **Estado de Incerteza e Insegurança Jurídica**: Condição necessária para a comprovação da controvérsia judicial relevante.
- **Controle Difuso-Incidental**: Fenômeno jurídico que ocorre quando o Poder Judiciário não está claro sobre a aplicação de uma lei ou ato normativo federal.

### Referências legais
- Art. 14 da Lei n.º 9.868/99
- Súmula 08 do Supremo Tribunal Federal

### Jurisprudência
- ADC n.º 08
- RE 123456

### Dicas de prova
- Entenda a noção de controvérsia judicial relevante e seu papel na ação declaratória de constitucionalidade.
- Identifique o estado de incerteza e insegurança jurídica como condição necessária para a comprovação da controvérsia judicial relevante.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.576 (1)", "page_number": 576, "discipline": "Direito Constitucional", "legal_refs": ["Art. 14 da Lei n.º 9.868/99", "Súmula 08 do Supremo Tribunal Federal"], "jurisprudence": ["ADC n.º 08", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T16:23:41.634335+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=576", "doc_key": "1c57c10142f087218f867960a2580bd6"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'ac0c77dda401cd68b9c95970ecab44ea34631bf32e6c7c507d4dad7216ecb1f7'),
  ('cpiuris2025::9c61019a3ed0e1bc084fecc9b9a144a5', 'doutrina', 'cp_iuris', 'Direito Constitucional — Requisitos para a Ação Direta de Constitucionalidade (ADC) e Ação Declaratória de Constitucionalidade (ADI)', '## Requisitos para a Ação Direta de Constitucionalidade (ADC) e Ação Declaratória de Constitucionalidade (ADI)

O STF firmou o entendimento de que a controvérsia judicial relevante na ADC deve ser qualitativa, não quantitativa. A análise não se limita ao número de decisões judiciais, mas sim à estatura constitucional do diploma e potencialidade de decisões similares.

### Conceitos
- **Controvérsia judicial relevante**: Qualidade da controvérsia que justifica a intervenção do STF
- **Análise qualitativa**: Avaliação não quantitativa da controvérsia
- **Requisito para ADC**: Existência de controvérsia judicial relevante
- **Desistência na ADC**: Não é permitida a desistência na ADC
- **Agravo no STF**: Possibilidade de agravo para o Pleno da STF

### Referências legais
- Art. 15 do STF
- Art. 16 do STF

### Jurisprudência
- ADI 5316/MC
- RE 123456

### Dicas de prova
- Entenda a diferença entre ADC e ADI
- Conheça o requisito de controvérsia judicial relevante
