  ('cpiuris2025::8b4c2cdca7d55f7a68858497e1b73e96', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle de Constitucionalidade e Ações Diretas de Constitucionalidade', '## Controle de Constitucionalidade e Ações Diretas de Constitucionalidade

Descreve as providências que podem ser solicitadas ao relator em ADC, incluindo a solicitação de informações adicionais, designação de peritos e audiência pública, além da possibilidade de concessão de medida cautelar.

### Conceitos
- **Relator**: O magistrado responsável pela elaboração do relatório em ADC
- **Audiência Pública**: Reunião pública para ouvir depoimentos de pessoas com experiência e autoridade na matéria
- **Medida Cautelar**: Decisão do STF que determina a suspensão do julgamento de processos envolvendo a aplicação da lei ou do ato normativo objeto da ação
- **Procedimento Abreviado**: Método utilizado para julgar ações diretas de constitucionalidade, que inclui a solicitação de informações adicionais e a designação de peritos

### Referências legais
- Art. 20, §1º da Lei n.º 9.868/99
- Art. 18 da Lei n.º 9.868/99
- Art. 21 da Lei n.º 9.868/99

### Jurisprudência
- STF, ADC-33, Rel. Min. Gilmar Mendes
- STF, ADC-18, Rel. Min. Celso de Mello

### Dicas de prova
- Entenda a diferença entre a intervenção de terceiros em ADC e ADI
- Conheça as providências que podem ser solicitadas ao relator em ADC
