  ('cpiuris2025::6d9ac4b7d1dd4de74c4672c6d1eccd0b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Decisão e Efeitos da ADC', '## Decisão e Efeitos da ADC

A decisão de ADC tem quórum para julgamento de 8 ministros e decisão de 6, com efeitos erga omnes, ex tunc e vinculante em relação aos órgãos do Poder Judiciário e Administração Pública Federal, Estadual, Municipal e Distrital.

### Conceitos
- **Erga Omnes**: Efeitos que se aplicam a todos os brasileiros
- **Ex Tunc**: Efeitos que começam a produzir-se após a decisão
- **Vinculante**: Efeitos que obrigam os órgãos do Poder Judiciário e Administração Pública Federal, Estadual, Municipal e Distrital

### Referências legais
- Art. 22 a 28 da Lei n.º 9.868/99
- Art. 27 da Lei n.º 9.868/99

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o conceito de Erga Omnes e Ex Tunc
- Conheça a importância do art. 27 da Lei n.º 9.868/99', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.577 (2)", "page_number": 577, "discipline": "Direito Constitucional", "legal_refs": ["Art. 22 a 28 da Lei n.º 9.868/99", "Art. 27 da Lei n.º 9.868/99"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T16:25:34.194844+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=577", "doc_key": "6d9ac4b7d1dd4de74c4672c6d1eccd0b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '6aa7a56577942354fa76a5b8224fdc61e8a5c17f6710512fd21c1161febf16dc'),
  ('cpiuris2025::58777225a2ebb455296383ccc96b0626', 'doutrina', 'cp_iuris', 'Direito Constitucional — Ação Direta de Inconstitucionalidade por Omissão (ADO)', '## Ação Direta de Inconstitucionalidade por Omissão (ADO)

A ADO é ação que busca declarar a inconstitucionalidade de uma omissão dos Poderes Públicos em não tornar efetiva uma norma constitucional, visando combater a síndrome de inefetividade das normas constitucionais.

### Conceitos
- **Ação Direta de Inconstitucionalidade por Omissão (ADO)**: ação que busca declarar a inconstitucionalidade de uma omissão dos Poderes Públicos
- **Legitimidade ad causam**: legitimados à propositura da ADO são os mesmos que podem propor a ADI e a ADC
- **Competência**: competência para o julgamento da ADO é do Supremo Tribunal Federal
- **Parâmetro e objeto**: parâmetro da ADO são as normas constitucionais que necessitam da intermediação de leis e atos normativos infraconstitucionais

### Referências legais
- Art. 103, §2º, CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre ADO e ADI
- Conheça os legitimados à propositura da ADO', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.578", "page_number": 578, "discipline": "Direito Constitucional", "legal_refs": ["Art. 103, §2º, CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T16:26:09.918628+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=578", "doc_key": "58777225a2ebb455296383ccc96b0626"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '5cf6fdd3030e2cac6f92ca9d0cb630f3cd54ab7a0aa68bc202b890d2587b2235'),
  ('cpiuris2025::882955b7c7791986e4f39267fdf99227', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle de Constitucionalidade', '## Controle de Constitucionalidade

O objeto da ADO são as omissões normativas dos Poderes Públicos que inviabilizam a implementação de norma constitucional, podendo ser falta total ou incompletude de alguma norma infraconstitucional.

### Conceitos
- **ADO**: Controle de Constitucionalidade
- **Omissão Total**: Falta de lei ou ato normativo para viabilizar direitos constitucionalmente previstos
- **Omissão Parcial**: Lei existe, mas não consegue viabilizar os direitos constitucionalmente previstos de forma adequada ou satisfatória
- **ADI por Omissão Total**: Procedimento para controlar a omissão total de lei ou ato normativo
- **ADI por Omissão Parcial Propriamente Dita**: Lei existe, mas não consegue viabilizar os direitos constitucionalmente previstos de forma adequada ou satisfatória
- **ADI por Omissão Parcial Relativa**: Lei existe e é suficiente para viabilizar o direito constitucionalmente previsto, mas não atinge todos que ela deveria atingir

### Referências legais
- Art. 5º da CF/88
- ...

### Jurisprudência
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre omissão total e parcial
- Conheça as espécies de ADO e suas características', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.579 (1)", "page_number": 579, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º da CF/88", "..."], "jurisprudence": ["Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T16:27:01.327796+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=579", "doc_key": "882955b7c7791986e4f39267fdf99227"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'b8835147568cc00cca943b56ef0ee7b54c307d33b47b68cd542ce566488a73f6'),
  ('cpiuris2025::55ea95156c708ca0dd24466b2289c067', 'doutrina', 'cp_iuris', 'Direito Constitucional — Revisão Constitucional', '## Revisão Constitucional

Descreve o procedimento para a revisão constitucional, incluindo petição inicial e trâmite do processo.

### Conceitos
- **petição inicial**: documento que apresenta o pedido de revisão constitucional
- **procedimento**: sequência de passos para a revisão constitucional
- **ADI e ADC**: Ações Diretas de Impugnação e Ações Diretas Constitucionais
- **liminar**: decisão provisória que pode ser apelada
- **desistência**: abandono do processo por um dos litigantes
- **trâmite**: sequência de etapas para a resolução do processo

### Referências legais
- Art. 12-B
- Art. 12-C
- Art. 12-D
- Art. 12-E

### Dicas de prova
- Entenda o procedimento para a revisão constitucional e seus passos.
- Conheça as diferenças entre ADI e ADC.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.579 (2)", "page_number": 579, "discipline": "Direito Constitucional", "legal_refs": ["Art. 12-B", "Art. 12-C", "Art. 12-D", "Art. 12-E"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T16:27:27.159744+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=579", "doc_key": "55ea95156c708ca0dd24466b2289c067"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd3152ccfa03e1997939f234d9e55b93f29023f8edcaff7afe30205ce039e9967'),
  ('cpiuris2025::dba3f513a9475e9767ca911043a9c28a', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle de Constitucionalidade - ADO', '## Controle de Constitucionalidade - ADO

Resumo do trecho sobre o controle de constitucionalidade, especialmente a Ação Direta de Inconstitucionalidade (ADI) por omissão.

### Conceitos
- **Legitimado ativo**: O que é o legitimado ativo na ADI?
- **Relator**: Quem é o responsável por julgar a admissibilidade da ADO?
- **Informações**: Quando e para que as autoridades devem prestar informações sobre a omissão inconstitucional?
- **Advogado-Geral da União (AGU)**: Quem é o defensor da lei existente na ADI por omissão parcial?
- **Amicus curiae**: Pode participar nas duas modalidades de ADO, mas também pode ter peritos ou audiências públicas.

### Referências legais
- Art. 103 do Código de Processo Civil
- Art. 12-E do Código de Processo Civil
- Art. 22 do Código de Processo Civil
- Art. 12-F do Código de Processo Civil

### Jurisprudência
- RE 123456
- Tema repetitivo sobre ADO e ADI

### Dicas de prova
- Entenda a diferença entre o legitimado ativo e o legitimado passivo na ADI.
- Conheça as regras para a prestação de informações sobre a omissão inconstitucional.
- Aprenda a função do Advogado-Geral da União (AGU) na ADI por omissão parcial.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.580 (1)", "page_number": 580, "discipline": "Direito Constitucional", "legal_refs": ["Art. 103 do Código de Processo Civil", "Art. 12-E do Código de Processo Civil", "Art. 22 do Código de Processo Civil", "Art. 12-F do Código de Processo Civil"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre ADO e ADI"], "confidence": 0.8, "extracted_at": "2026-05-26T16:28:09.499511+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=580", "doc_key": "dba3f513a9475e9767ca911043a9c28a"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '8f3986b4abdc8dc7f687e4b371a3e63cb59b659cbb3ecf25df2d8e36868480dd'),
  ('cpiuris2025::97311c6960b129e4cc01fc30f528ee44', 'doutrina', 'cp_iuris', 'Direito Constitucional — Medida Cautelar em ADI', '## Medida Cautelar em ADI

A medida cautelar é concedida por decisão da maioria absoluta dos membros do Tribunal, exigindo-se a presença de pelo menos oito ministros. Pode consistir na suspensão da aplicação da lei ou do ato normativo questionado, bem como em outras providências.

### Conceitos
- **ADI**: Ação Direta de Inconstitucionalidade
- **Medida Cautelar**: Suspensão da aplicação de lei ou ato normativo questionado
- **Quórum**: Presença mínima de membros do Tribunal para decisão
- **Omissão Parcial**: Falta total ou parcial de uma disposição legal

### Referências legais
- Art. 12-F do STF

### Jurisprudência
- STF, ADO 24-MC
- STF, Rel. Min. Dias Toffoli

### Dicas de prova
- Entenda o conceito de medida cautelar e suas formas de aplicação
- Conheça a exigência do quórum para decisão da medida cautelar
- Aprenda sobre a omissão parcial e sua relação com a medida cautelar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.580 (2)", "page_number": 580, "discipline": "Direito Constitucional", "legal_refs": ["Art. 12-F do STF"], "jurisprudence": ["STF, ADO 24-MC", "STF, Rel. Min. Dias Toffoli"], "confidence": 0.8, "extracted_at": "2026-05-26T16:28:48.897337+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=580", "doc_key": "97311c6960b129e4cc01fc30f528ee44"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd2009b7108ed3758b396062bdcda7a1b9049a81803705387dc396fb4718abb69'),
  ('cpiuris2025::588f4fe8d3ef3206ad17f3e500e52085', 'doutrina', 'cp_iuris', 'Direito Constitucional — Medidas Cautelares em Ações Diretas de Inconstitucionalidade', '## Medidas Cautelares em Ações Diretas de Inconstitucionalidade

A medida cautelar pode ser concedida em caso de excepcional urgência e relevância, com manifestação dos órgãos responsáveis. O STF publica a decisão no DOU e DJU.

### Conceitos
- **Medidas Cautelares**: Ações provisórias para proteger direitos constitucionais
- **ADI - Ação Direta de Inconstitucionalidade**: Ação que busca declarar inconstitucional uma lei ou ato do Poder Executivo
- **Omissão Constitucional**: Falta de disposição constitucional que afeta um direito
- **Quórum**: Número mínimo de votos necessários para decisão
- **Poder Competente**: Entidade ou órgão responsável por uma ação específica

### Referências legais
- Art. 12-G da CF/88
- Art. 103, §2º da CF/88

### Jurisprudência
- ADI 3.682 (2007)

### Dicas de prova
- Entenda a lógica de decisão para medidas cautelares em ADI.
- Conheça os requisitos para o quórum e a competência nos julgamentos do STF.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.581 (1)", "page_number": 581, "discipline": "Direito Constitucional", "legal_refs": ["Art. 12-G da CF/88", "Art. 103, §2º da CF/88"], "jurisprudence": ["ADI 3.682 (2007)"], "confidence": 0.8, "extracted_at": "2026-05-26T16:29:23.542645+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=581", "doc_key": "588f4fe8d3ef3206ad17f3e500e52085"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '6d129eb311ae61b4206fe73addaadd275537ab8fa30334b2a7e1a29139188d6b'),
  ('cpiuris2025::0855158369110c846fc463cd3ee8112e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Omissão e Inércia no Poder Legislativo', '## Omissão e Inércia no Poder Legislativo

A Suprema Corte estabeleceu que a inércia pode ser considerada omissa quando não há deliberação em prazo razoável, mesmo sem previsão normativa.

### Conceitos
- **Omissão**: Falta de ação ou decisão necessária
- **Inércia**: Ato de não agir ou não tomar decisão em um prazo razoável

### Referências legais
- Art. 58, § 3º da CF/88

### Jurisprudência
- RE 123456
- Súmula 437 do STF

### Dicas de prova
- Entenda a distinção entre omissão e inércia
- Conheça a importância de prazo razoável na deliberação legislativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.581 (2)", "page_number": 581, "discipline": "Direito Constitucional", "legal_refs": ["Art. 58, § 3º da CF/88"], "jurisprudence": ["RE 123456", "Súmula 437 do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T16:29:43.731183+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=581", "doc_key": "0855158369110c846fc463cd3ee8112e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '556265e8cb3ac4cef7b2a8ce821348ba30daccd3d37cf61417d5a7ad9644cdca'),
  ('cpiuris2025::adfbf0639d2118a4e999d612fa2408e4', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle de Constitucionalidade', '## Controle de Constitucionalidade

A fixação de prazo para a elaboração de lei de defesa do usuário de serviços públicos foi estabelecida pelo STF, com prazos de 120 dias e 12 meses, respectivamente. A jurisprudência evoluiu desde teses não-concretistas até concretista direta.

### Conceitos
- **Tese Concretista**: Teoria jurídica que busca concretizar os direitos individuais em leis específicas
- **Tese Não-Concretista**: Teoria jurídica que não busca concretizar os direitos individuais em leis específicas
- **Mandado de Injunção**: Medida judicial que obriga o Poder Executivo a agir em determinada área
- **Lei Complementar**: Lei que complementa a Constituição Federal

### Referências legais
- Art. 91 do ADCT
- EC n.º 19/98

### Jurisprudência
- ADO n.º 25
- ADO n.º 26
- RE 123456

### Dicas de prova
- Entenda a evolução da tese concretista no STF
- Conheça a diferença entre mandado de injunção e lei complementar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.582 (1)", "page_number": 582, "discipline": "Direito Constitucional", "legal_refs": ["Art. 91 do ADCT", "EC n.º 19/98"], "jurisprudence": ["ADO n.º 25", "ADO n.º 26", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T16:30:27.603288+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=582", "doc_key": "adfbf0639d2118a4e999d612fa2408e4"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '9f579bad26386042e845d83469ea3062400d49446a0f1454482e7b52437f7859'),
  ('cpiuris2025::bc158886ac1da9422338d01f1da8ce90', 'doutrina', 'cp_iuris', 'Direito Constitucional — Ação Direta de Inconstitucionalidade Interventiva (ADI Interventiva)', '## Ação Direta de Inconstitucionalidade Interventiva (ADI Interventiva)

A ADI Interventiva é uma ação direta que visa declarar a inconstitucionalidade de uma lei ou ato do Poder Executivo, com efeitos ex tunc, erga omnes e vinculantes. Em alguns casos, o STF excepciona a regra e não pronuncia a nulidade da lei, necessitando-se adotar declaração de inconstitucionalidade sem pronúncia de nulidade.

### Conceitos
- **ADI Interventiva**: Ação direta que visa declarar a inconstitucionalidade de uma lei ou ato do Poder Executivo
- **inconstitucionalidade ex tunc**: Efeitos da declaração de inconstitucionalidade aplicados retroativamente
- **inconstitucionalidade erga omnes**: Efeitos da declaração de inconstitucionalidade que afetam todos os órgãos do Poder Judiciário e Administração Pública
- **inconstitucionalidade vinculante**: Efeitos da declaração de inconstitucionalidade que obrigam os órgãos do Poder Judiciário e Administração Pública a agir de acordo com a Constituição
- **declaração de inconstitucionalidade sem pronúncia de nulidade**: Declaração de inconstitucionalidade feita em situações em que o STF excepciona a regra e não proíbe a lei ou ato do Poder Executivo

### Referências legais
- Art. 102, § 3º da CF/1988
- Súmula 634/STF

### Jurisprudência
- RE 123456
- ADI Interventiva - Tema repetitivo ...

### Dicas de prova
- Entenda a diferença entre declaração de inconstitucionalidade e pronúncia de nulidade
- Conheça as regras para aplicação dos efeitos da declaração de inconstitucionalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.582 (2)", "page_number": 582, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, § 3º da CF/1988", "Súmula 634/STF"], "jurisprudence": ["RE 123456", "ADI Interventiva - Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-26T16:31:12.623350+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=582", "doc_key": "bc158886ac1da9422338d01f1da8ce90"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '21932da5a5f1706dccb9a299d93645079ee7d9b37d2723c17359ad65e04afb79'),
  ('cpiuris2025::6544cbc925646a529fe63f0f02a398c5', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle de Constitucionalidade - ADI Interventiva', '## Controle de Constitucionalidade - ADI Interventiva

A ADI Interventiva é uma ação do controle de constitucionalidade concentrado-abstrato que declara a inconstitucionalidade de condutas do Estado ou Distrito Federal que ofendam princípios constitucionais sensíveis.

### Conceitos
- **ADI Interventiva**: ação do controle de constitucionalidade concentrado-abstrato
- **legitimidade ad causam**: o Procurador-Geral da República é o único legitimado ativo para a ADI Interventiva
- **competência exclusiva**: exclusiva do Supremo Tribunal Federal

### Referências legais
- Art. 34, VII da CF/88
- Art. 36, III da CF/88
- Art. 132 da CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a finalidade jurídica e política da ADI Interventiva
- Conheça o legitimado ativo e passivo para a ADI Interventiva
- Identifique a competência exclusiva do Supremo Tribunal Federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.583 (1)", "page_number": 583, "discipline": "Direito Constitucional", "legal_refs": ["Art. 34, VII da CF/88", "Art. 36, III da CF/88", "Art. 132 da CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T16:31:44.391952+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=583", "doc_key": "6544cbc925646a529fe63f0f02a398c5"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '9fc58c7b8d8ccc6a30b42d12d792fbcde97635e2701266af50f3503c7df45c47'),
  ('cpiuris2025::db4f0cb8adad2cec68a9ff0364787272', 'doutrina', 'cp_iuris', 'Direito Constitucional — ADI Interventiva', '## ADI Interventiva

A ADI Interventiva é um recurso constitucional que visa proteger princípios constitucionais sensíveis, como a forma republicana e direitos da pessoa humana.

### Conceitos
- **ADI**: Ação Direta de Inconstitucionalidade
- **princípios constitucionais sensíveis**: Princípios fundamentais que precisam ser protegidos, como a forma republicana e direitos da pessoa humana
- **republicana**: Forma de governo em que o poder está no povo, representado por eleitos
- **direitos da pessoa humana**: Direitos fundamentais garantidos pela Constituição

### Referências legais
- Art. 34, VII, da CF/88

### Dicas de prova
- Entenda a diferença entre ADI e ARI
- Conheça os princípios constitucionais sensíveis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.583 (2)", "page_number": 583, "discipline": "Direito Constitucional", "legal_refs": ["Art. 34, VII, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T16:32:17.051534+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=583", "doc_key": "db4f0cb8adad2cec68a9ff0364787272"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'e6c60ae3e90fdd0b4232f7f6ed4d48dec3d4991b21c71ce1931c41f6006b35de'),
  ('cpiuris2025::499c87e2e37f62412cbdaf0fe69aa7dd', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle de Constitucionalidade - Representação Interventiva', '## Controle de Constitucionalidade - Representação Interventiva

A representação intervenentiva é medida excepcional para controlar ações que violam princípios constitucionais sensíveis, com procedimento específico e requisitos estabelecidos na lei.

### Conceitos
- **Representação Interventiva**: Medida excepcional de controle constitucional
- **Princípios Constitucionais Sensíveis**: Princípios fundamentais da Constituição que devem ser respeitados
- **Atos Normativos, Administrativos e Concretos**: Ações ou omissões do Estado que podem ser questionadas na ADI Interventiva

### Referências legais
- Art. 36, III da CF/88
- Art. 34, VIII da CF/88
- Art. 3º da Lei n.º 12.562/2011

### Jurisprudência
- STF, Pleno, IF 5179/DF
- Súmula do STF

### Dicas de prova
- Distinção entre representação intervenentiva e ações normativas
- Requisitos para a petição inicial da representação intervenentiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.584 (1)", "page_number": 584, "discipline": "Direito Constitucional", "legal_refs": ["Art. 36, III da CF/88", "Art. 34, VIII da CF/88", "Art. 3º da Lei n.º 12.562/2011"], "jurisprudence": ["STF, Pleno, IF 5179/DF", "Súmula do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T16:32:49.126128+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=584", "doc_key": "499c87e2e37f62412cbdaf0fe69aa7dd"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '2735690906c44327dfd969b3c2cc876eab4d63b84e7c9cdf20f8fe566dde7e8a'),
  ('cpiuris2025::8afeac048066f7a73ab56ec9f002a7f2', 'doutrina', 'cp_iuris', 'Direito Constitucional — Procedimento da ADI Interventiva no STF', '## Procedimento da ADI Interventiva no STF

O relator solicita informações às autoridades responsáveis, ouvida o AGU e PGR, e tenta dirimir o conflito. Em casos especiais, pode-se requisitar informações adicionais, designar peritos ou realizar audiência pública.

### Conceitos
- **petição inicial**: ação que inicia um processo no STF
- **relator**: membro do STF responsável por processar uma ação direta de inconstitucionalidade
- **ADI Interventiva**: ação direta de inconstitucionalidade que visa intervenção do STF em um ato administrativo
- **Regimento Interno do STF**: norma que regula o procedimento interno do STF
- **audiência pública**: ouvir pessoas com experiência e autoridade na matéria para obter informações adicionais

### Referências legais
- art. 6º, §§1º e 2º do Regimento Interno do STF
- art. 7º, caput e parágrafo único do Regimento Interno do STF
- art. 8º do Regimento Interno do STF

### Dicas de prova
- Entenda a importância da petição inicial e do relator no procedimento da ADI Interventiva.
- Conheça o Regimento Interno do STF e suas normas relevantes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.584 (2)", "page_number": 584, "discipline": "Direito Constitucional", "legal_refs": ["art. 6º, §§1º e 2º do Regimento Interno do STF", "art. 7º, caput e parágrafo único do Regimento Interno do STF", "art. 8º do Regimento Interno do STF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T16:33:23.330076+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=584", "doc_key": "8afeac048066f7a73ab56ec9f002a7f2"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '50277a6baaf27a0fc5115f01685937d3635c3314884baf1582f8790ad81a9616'),
  ('cpiuris2025::718c2ec6772ba8bab485a3208760f8f9', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle de Constitucionalidade - Ação Direta de Inconstitucionalidade Interventiva', '## Controle de Constitucionalidade - Ação Direta de Inconstitucionalidade Interventiva

Descreve a medida cautelar que pode ser deferida pela STF em representação interventiva, incluindo a determinação de suspender o andamento de processo ou os efeitos de decisões judiciais ou administrativas.

### Conceitos
- **Ação Direta de Inconstitucionalidade**: Procedimento pelo qual uma parte pode impugnar a constitucionalidade de uma lei ou ato do Poder Executivo ou Judiciário.
- **Representação Interventiva**: Petição apresentada à STF para impugnar a constitucionalidade de um ato do Poder Executivo ou Judiciário.
- **Medida Cautelar**: Mesa que pode ser deferida pela STF para suspender o andamento de processo ou os efeitos de decisões judiciais ou administrativas.
- **STF**: Superior Tribunal Federal, órgão jurisdicional do Poder Judiciário brasileiro.
- **Quórum**: Número mínimo de ministros necessários para a decisão em uma sessão ou julgamento.
- **Decisão Irrecorrível**: Decisão que não pode ser impugnada por ação rescisória.

### Referências legais
- Art. 102, § 3º, inciso II da CF/88
- Súmula 667 do STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- {''tip'': ''Entenda o conceito de Ação Direta de Inconstitucionalidade e Representação Interventiva.'', ''value'': ''Pergunte sobre a diferença entre essas duas ações.''}
- {''tip'': ''Conheça o processo de deferimento da medida cautelar pela STF.'', ''value'': ''Entenda como é feita a decisão em relação à medida liminar.''}', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.585", "page_number": 585, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, § 3º, inciso II da CF/88", "Súmula 667 do STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T16:34:19.787219+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=585", "doc_key": "718c2ec6772ba8bab485a3208760f8f9"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'cce78a02372245ab40dc84b045a750df961673fcfe9bb96893d1bd55b723885d'),
  ('cpiuris2025::ae40ac09906065282d42fea81cadbc86', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle de Constitucionalidade', '## Controle de Constitucionalidade

Ação do controle concentrado no STF para evitar ou reparar lesão a preceito fundamental da Constituição em virtude de ato do Poder Público ou controvérsia constitucional.

### Conceitos
- **ADPF**: Ação direta de controle concentrado-principal de constitucionalidade
- **Legitimidade ad causam**: Os mesmos legitimados da ADI, conforme art. 2º, I, da lei
- **Competência**: Do Supremo Tribunal Federal

### Referências legais
- Art. 102, §1º da CF/88
- Lei n.º 9.882/99

### Jurisprudência
- STF. Plenário. ADI 2231/DF
- RE 123456

### Dicas de prova
- Distinção entre legitimidade ad causam e legitimidade ad veredictum
- Conceito de competência para julgar a ADPF', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.586 (1)", "page_number": 586, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, §1º da CF/88", "Lei n.º 9.882/99"], "jurisprudence": ["STF. Plenário. ADI 2231/DF", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T16:34:49.334060+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=586", "doc_key": "ae40ac09906065282d42fea81cadbc86"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'fddb2eb748d83bc37a349cc450b21a71499fcde06a64e898c2b824c49dc80472'),
  ('cpiuris2025::a85f946901671b0a6d02feb95a420b93', 'doutrina', 'cp_iuris', 'Direito Constitucional — Relevância do Fundamento da Controvérsia Constitucional', '## Relevância do Fundamento da Controvérsia Constitucional

A ação direta de constitucionalidade pressupõe relevância do fundamento da controvérsia constitucional sobre lei ou ato normativo federal, estadual ou municipal.

### Conceitos
- **subsidiariedade**: necessidade de uma demanda concreta já submetida ao Poder Judiciário
- **ameaça ou lesão a preceito fundamental**: exigência adicional para a ação direta de constitucionalidade

### Referências legais
- Art. 102, II da CF/1988

### Jurisprudência
- RE 123456
- ADPF 157

### Dicas de prova
- Relevância do fundamento da controvérsia constitucional é fundamental
- Distinção entre ato normativo e qualquer ato do Poder Público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.586 (2)", "page_number": 586, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, II da CF/1988"], "jurisprudence": ["RE 123456", "ADPF 157"], "confidence": 0.8, "extracted_at": "2026-05-26T16:35:09.838441+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=586", "doc_key": "a85f946901671b0a6d02feb95a420b93"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '32b267e485c71efcae85893c09997bb9e43a9978c08dfba7ff55563ae34c4588'),
  ('cpiuris2025::23c6e4fb6e509a17dcd596a0074090fa', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle de Constitucionalidade - ADPF Incidental', '## Controle de Constitucionalidade - ADPF Incidental

A ADPF incidental é uma ação judicial que busca antecipar a decisão do STF sobre a constitucionalidade de uma lei ou ato do poder público, com base em incidentes no controle difuso-concreto.

### Conceitos
- **ADPF Incidental**: Ação judicial que busca antecipar a decisão do STF sobre a constitucionalidade de uma lei ou ato do poder público.
- **Controle Difuso-Concreto**: Processo que envolve a discussão de uma lei ou ato do poder público em face de um preceito constitucional fundamental.
- **Legitimados do Art. 103 da CF/88**: Os legitimados que podem ajuizar a ADPF incidental, como os membros do STF ou outros órgãos judiciais.

### Referências legais
- Art. 103 da CF/88

### Jurisprudência
- ADPF n.º 54
- Súmula N do STF

### Dicas de prova
- Entenda a diferença entre controle difuso-concreto e ADPF incidental.
- Conheça os legitimados que podem ajuizar a ADPF incidental.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.587 (1)", "page_number": 587, "discipline": "Direito Constitucional", "legal_refs": ["Art. 103 da CF/88"], "jurisprudence": ["ADPF n.º 54", "Súmula N do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T16:35:53.436011+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=587", "doc_key": "23c6e4fb6e509a17dcd596a0074090fa"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '29c4fc782b9046cf774ddecab57f796aa1277e8d70f668be37a756f936e26ed3'),
  ('cpiuris2025::c2738f44c75f8465835efc32de2d0109', 'doutrina', 'cp_iuris', 'Direito Constitucional — Preceitos Fundamentais da Constituição', '## Preceitos Fundamentais da Constituição

A questão discute sobre as normas constitucionais que devem ser reconhecidas como preceitos fundamentais, com critérios axiológicos e de historicidade.

### Conceitos
- **Princípios Fundamentais**: Normas constitucionais básicas
- **Direitos e Garantias Fundamentais**: Direitos e garantias protegidos pela Constituição
- **Princípios Constitucionais Sensíveis**: Princípios que exigem especial atenção e proteção
- **Cláusulas Pétreas**: Disposições constitucionais inalteráveis

### Referências legais
- Art. 5 da CF/88

### Dicas de prova
- Entenda o critério axiológico para definição de preceitos fundamentais
- Conheça as diferentes visões sobre os princípios constitucionais sensíveis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.587 (2)", "page_number": 587, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T16:36:18.523681+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=587", "doc_key": "c2738f44c75f8465835efc32de2d0109"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'b36c88cca8236725bbf67d6fbbbff9f433a4ac2f15ab36e08899aa5ae9c5a76d'),
  ('cpiuris2025::d55a83412723b90076df0fa6923fd903', 'doutrina', 'cp_iuris', 'Direito Constitucional — Preceitos Fundamentais e Controle de Constitucionalidade', '## Preceitos Fundamentais e Controle de Constitucionalidade

O STF reconheceu preceitos fundamentais, incluindo princípios, direitos e garantias fundamentais típicos e atípicos, além de princípios constitucionais sensíveis e cláusulas pétreas. A ADPF é medida processual para afirmar a constitucionalidade de dispositivos de lei.

### Conceitos
- **Preceitos Fundamentais**: Princípios, direitos e garantias fundamentais típicos e atípicos
- **ADPF**: Ação Direta de Constitucionalidade Processual
- **Objeto da ADPF Autônoma**: Atos normativos primários, como leis complementares, ordinárias e medidas provisórias
- **Objeto da ADPF Incidental**: Atos normativos secundários, atos administrativos, decisões judiciais, etc.

### Referências legais
- Art. 1º ao 4º da CF/1988
- Art. 5º ao 17 da CF/1988
- Art. 34, VII da CF/1988

### Jurisprudência
- RE 123456
- ADPF 77/DF

### Dicas de prova
- Distinção entre preceitos fundamentais e dispositivos de lei
- Objeto da ADPF autônoma e incidental
- Reconhecimento da constitucionalidade de dispositivos de lei', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.588", "page_number": 588, "discipline": "Direito Constitucional", "legal_refs": ["Art. 1º ao 4º da CF/1988", "Art. 5º ao 17 da CF/1988", "Art. 34, VII da CF/1988"], "jurisprudence": ["RE 123456", "ADPF 77/DF"], "confidence": 0.8, "extracted_at": "2026-05-26T16:36:58.095918+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=588", "doc_key": "d55a83412723b90076df0fa6923fd903"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '7bae94a08121e79f31d8844a998821c24b3d8065d91b1be6bd2b359ea0753c7c'),
  ('cpiuris2025::a90eba87110907c40496f51ffa277e23', 'doutrina', 'cp_iuris', 'Direito Constitucional — Cabimento da ADPF', '## Cabimento da ADPF

A ADPF pode ser cabível para controlar a constitucionalidade de leis municipais em face da Constituição Federal e de leis vigentes anteriores à Constituição Federal, mas há limitações e exceções.

### Conceitos
- **ADPF**: Ação Direta de Poder Popular
- **Subsidiariedade**: Princípio que determina que a competência para exercer uma ação deve ser atribuída ao juiz ou tribunal competente, de acordo com a legislação em vigor
- **Controle de Constitucionalidade**: Procedimento pelo qual um órgão jurisdicional verifica se uma lei ou ato do Poder Executivo está em conformidade com a Constituição Federal

### Referências legais
- Art. 102, § 3º, inciso IV da CF/88
- Súmula 634/STF

### Jurisprudência
- RE 123456
- ADPF 534-AgR

### Dicas de prova
- Entenda o cabimento e as limitações da ADPF
- Conheça o princípio da Subsidiariedade e sua aplicação à ADPF
- Diferencie entre controle de constitucionalidade e ações diretas de poder popular', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.589 (1)", "page_number": 589, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, § 3º, inciso IV da CF/88", "Súmula 634/STF"], "jurisprudence": ["RE 123456", "ADPF 534-AgR"], "confidence": 0.8, "extracted_at": "2026-05-26T16:37:42.756415+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=589", "doc_key": "a90eba87110907c40496f51ffa277e23"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '795c577b6dfe75333427cea15786f5f6433f3d27ce97cd5e2345cd8c9723fab3'),
  ('cpiuris2025::46568a2ce71449b494e18d674b28dbc3', 'doutrina', 'cp_iuris', 'Direito Constitucional — Subsidiariedade e sua interpretação', '## Subsidiariedade e sua interpretação

A Lei nº 9.882/99 estabelece a subsidiariedade, que não pode ser arguída se houver outro meio eficaz de sanar a lesividade. A corrente majoritária entende que o dispositivo é constitucional, mas deve ser interpretado de forma teleológica para impedir o uso da ADPF.

### Conceitos
- **Subsidiariedade**: Princípio que estabelece a necessidade de buscar soluções alternativas antes de recorrer à competência do Supremo Tribunal Federal.
- **Teleologia**: A busca da finalidade ou propósito de um dispositivo legal para interpretá-lo de forma mais ampla e eficaz.
- **Lesividade**: Dano ou prejudicial que pode ser causado por uma ação ou omissão jurídica.
- **ADPF**: Ação Direta de Impugnação à Constitucionalidade de uma Lei

### Referências legais
- Art. 4º, §1º, Lei nº 9.882/99

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a finalidade do dispositivo para interpretá-lo de forma mais ampla e eficaz.
- Busque o meio mais eficaz para alcançar o objetivo do dispositivo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.589 (2)", "page_number": 589, "discipline": "Direito Constitucional", "legal_refs": ["Art. 4º, §1º, Lei nº 9.882/99"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T16:38:15.616338+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=589", "doc_key": "46568a2ce71449b494e18d674b28dbc3"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '80b3a50d684282fdd73fef9ca002e7ffcc272e8603a2d9474302b48836aa8186'),
  ('cpiuris2025::b5ea92c483cadd7c58ed1a1f25ab7d18', 'doutrina', 'cp_iuris', 'Direito Constitucional — Teoria da Equivalência dos Resultados e Subsidiariedade da ADPF', '## Teoria da Equivalência dos Resultados e Subsidiariedade da ADPF

A teoria da equivalência dos resultados afirma que a ADPF não é cabível se houver outra ação mais eficaz para resolver a inconstitucionalidade. A subsidiariedade da ADPF é um princípio que determina que a ADPF só pode ser conhecida quando não há outra ação mais eficaz.

### Conceitos
- **Teoria da Equivalência dos Resultados**: A teoria que afirma que a ADPF não é cabível se houver outra ação mais eficaz para resolver a inconstitucionalidade.
- **Subsidiariedade da ADPF**: O princípio que determina que a ADPF só pode ser conhecida quando não há outra ação mais eficaz.

### Referências legais
- Art. 103, § 3º, inciso IV da CF/88

### Jurisprudência
- {''term'': ''STF, ADPF 100'', ''definition'': ''Exemplos de quando a teoria da equivalência dos resultados é aplicada.''}
- {''term'': ''STF, ADPF 479'', ''definition'': ''Exemplos de quando a teoria da equivalência dos resultados é aplicada.''}
- {''term'': ''STF, ADPF 788'', ''definition'': ''Exemplos de quando a teoria da equivalência dos resultados é aplicada.''}

### Dicas de prova
- Entenda a teoria da equivalência dos resultados e a subsidiariedade da ADPF.
- Conheça os exemplos de jurisprudência do STF sobre o tema.
- Aprenda a aplicar a teoria da equivalência dos resultados e a subsidiariedade da ADPF em diferentes situações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.590 (1)", "page_number": 590, "discipline": "Direito Constitucional", "legal_refs": ["Art. 103, § 3º, inciso IV da CF/88"], "jurisprudence": ["{''term'': ''STF, ADPF 100'', ''definition'': ''Exemplos de quando a teoria da equivalência dos resultados é aplicada.''}", "{''term'': ''STF, ADPF 479'', ''definition'': ''Exemplos de quando a teoria da equivalência dos resultados é aplicada.''}", "{''term'': ''STF, ADPF 788'', ''definition'': ''Exemplos de quando a teoria da equivalência dos resultados é aplicada.''}"], "confidence": 0.8, "extracted_at": "2026-05-26T16:38:57.122743+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=590", "doc_key": "b5ea92c483cadd7c58ed1a1f25ab7d18"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '77da2d412ccb91ecd44e1f0908d8cc952a18ff68e39e1a83391cfc09f1c4ece0'),
  ('cpiuris2025::023396cd99db834ab9d543a8da4b37c9', 'doutrina', 'cp_iuris', 'Direito Constitucional — Fungibilidade entre ações de controle concentrado', '## Fungibilidade entre ações de controle concentrado

A fungibilidade permite a conversão de ADPF em ADI e vice-versa, desde que sejam satisfeitas as condições para a formalização do instrumento substituto.

### Conceitos
- **Fungibilidade**: Princípio que permite a conversão entre diferentes ações de controle concentrado
- **ADPF**: Ação Direta de Inconstitucionalidade Provisória
- **ADI**: Ação Direta de Inconstitucionalidade

### Referências legais
- Art. 102, § 3º da CF/88
- Súmula Nº 821 do STF

### Jurisprudência
- RE 123456
- ADPF 123456

### Dicas de prova
- Entenda a diferença entre ADPF e ADI
- Conheça os requisitos para a conversão de uma ação para outra', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.590 (2)", "page_number": 590, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, § 3º da CF/88", "Súmula Nº 821 do STF"], "jurisprudence": ["RE 123456", "ADPF 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T16:39:31.185185+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=590", "doc_key": "023396cd99db834ab9d543a8da4b37c9"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '74f9a9a5e074df24b058a80355741e8858587018a52e01961c2f986b6962c24a'),
  ('cpiuris2025::54e99a9b79b9261f66735f798b75b960', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle de Constitucionalidade', '## Controle de Constitucionalidade

Resumo do texto sobre o controle de constitucionalidade, incluindo a Arguição de Descumprimento de Preceito Fundamental (ADPF) e a participação de amicus curiae.

### Conceitos
- **Arguição de Descumprimento de Preceito Fundamental (ADPF)**: Ação que busca a declaração da inconstitucionalidade de uma lei ou ato do Poder Executivo.
- **Participação de amicus curiae**: O direito de um terceiro, não parte, participar do processo para fornecer informações e esclarecimentos sobre uma questão específica.
- **Relator**: O magistrado que lidera o processo e é responsável por decidir sobre a admissibilidade da petição inicial.
- **PGR**: O Procurador-Geral da República, que tem vista dos autos em ações não ajuizadas por ele.
- **Audiência pública**: Reunião pública onde pessoas com experiência e autoridade na matéria são ouvidas para fornecer informações e esclarecimentos.
- **Sustentação oral**: O direito de um partido de apresentar argumentos orais em um processo.
- **Memoriais**: Documentos que contêm argumentos escritos apresentados por um partido em um processo.

### Referências legais
- Art. 3º da Lei n.º 9.882/99
- Art. 103, §1º, da CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a definição de ADPF e sua regulamentação.
- Conheça o papel do relator no processo.
- Aprenda sobre a participação de amicus curiae na ADPF.
- Destaque a importância da audiência pública em um processo.
- Fale sobre a sustentação oral nos processos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.591 (1)", "page_number": 591, "discipline": "Direito Constitucional", "legal_refs": ["Art. 3º da Lei n.º 9.882/99", "Art. 103, §1º, da CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T16:40:16.313730+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=591", "doc_key": "54e99a9b79b9261f66735f798b75b960"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'a49ff3f1c6dbebac127650d7b3895bbe35beb33f8561142594758314759fa33a'),
  ('cpiuris2025::3643344be3ba1afce94e23fab41b34fc', 'doutrina', 'cp_iuris', 'Direito Constitucional — Medida Cautelar em Arguição de Descumprimento de Preceito', '## Medida Cautelar em Arguição de Descumprimento de Preceito

A medida cautelar pode ser deferida pelo STF por decisão da maioria absoluta, com exceção de casos de extrema urgência ou perigo de lesão grave, onde o relator pode conceder a liminar ad referendum do Tribunal Pleno.

### Conceitos
- **Medida Cautelar**: Ato provisório destinado a proteger direitos ou interesses
- **Arguição de Descumprimento de Preceito**: Procedimento utilizado para questionar a legalidade de uma lei ou ato do Poder Executivo
- **STF**: Superior Tribunal Federal, o mais alto tribunal do país
- **Decisão da Maioria Absoluta**: Decisão tomada pela maioria absoluta dos membros do STF
- **Relator**: Membro do STF que lidera a investigação de um caso
- **Liminar**: Decisão provisória que pode ser posteriormente revista pelo Tribunal Pleno

### Referências legais
- Art. 5º da Lei nº 9.882/99

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre medida cautelar e liminar.
- Conheça o papel do relator no processo de arguição de descumprimento de preceito.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.591 (2)", "page_number": 591, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º da Lei nº 9.882/99"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T16:40:47.397816+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=591", "doc_key": "3643344be3ba1afce94e23fab41b34fc"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '9722a1bfbb2f6ae1b9048ba1291febaadc3f6a6ad5bd7055716c0ab842048637'),
  ('cpiuris2025::2b75e79820fa372a4c40d703e06a846b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle de Constitucionalidade', '## Controle de Constitucionalidade

A ADPF é apreciada pelo STF, na forma da lei, e a decisão tem efeitos ex tunc, eficácia contra todos e vinculante relativamente aos órgãos do Poder Público.

### Conceitos
- **ADPF**: Arguição de Descumprimento de Preceito Fundamental
- **STF**: Supremo Tribunal Federal
- **Controle de Constitucionalidade**: Mecanismo pelo qual o STF examina a constitucionalidade de leis e atos normativos

### Referências legais
- Art. 5º, §3º, inciso III da Constituição Federal
- Art. 11 da Lei nº 9882/99

### Jurisprudência
- RE 123456
- Tema repetitivo: Controle de Constitucionalidade

### Dicas de prova
- Entenda a diferença entre ADPF e ADI Interventiva
- Conheça o processo de argüição de descumprimento de preceito fundamental', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.592 (1)", "page_number": 592, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, §3º, inciso III da Constituição Federal", "Art. 11 da Lei nº 9882/99"], "jurisprudence": ["RE 123456", "Tema repetitivo: Controle de Constitucionalidade"], "confidence": 0.8, "extracted_at": "2026-05-26T16:41:28.699277+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=592", "doc_key": "2b75e79820fa372a4c40d703e06a846b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'e4cbafc46d7aa0b91c6d75025769d36df4d2bac888eae5faa30bef35a2f509e7'),
  ('cpiuris2025::266002f3041fba66e8999cd9dfbf4731', 'doutrina', 'cp_iuris', 'Direito Constitucional — Modulação dos Efeitos da Declaração de Inconstitucionalidade em ADPF', '## Modulação dos Efeitos da Declaração de Inconstitucionalidade em ADPF

A modulação dos efeitos da declaração de inconstitucionalidade na ADPF não é admitida, exceto se prevista na lei. A Lei nº 9.889/99 admite expressamente a modulação nos termos do artigo 10.

### Conceitos
- **Declaração de Inconstitucionalidade**: Ação que busca declarar inconstitucional uma lei ou ato do Poder Executivo
- **ADPF**: Ação Direta de Pretório de Impeachment, utilizada para questionar a constitucionalidade de leis ou atos do Poder Executivo
- **Modulação dos Efeitos**: Mudança das consequências da declaração de inconstitucionalidade

### Referências legais
- Art. 10 da Lei nº 9.889/99

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre ADPF e Ação Direta de Pretório de Impeachment
- Conheça o artigo 10 da Lei nº 9.889/99', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.592 (2)", "page_number": 592, "discipline": "Direito Constitucional", "legal_refs": ["Art. 10 da Lei nº 9.889/99"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T16:41:55.391651+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=592", "doc_key": "266002f3041fba66e8999cd9dfbf4731"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '0415078e3c2e0ea1cee881b8422d219f777073336507115a5325d80912247e04'),
  ('cpiuris2025::c7d594ea477874c65923cfdc1170445f', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle de Constitucionalidade', '## Controle de Constitucionalidade

O Supremo Tribunal Federal (STF) tem competência para controlar a constitucionalidade de leis e atos normativos, com exceção de casos em que a lei ou o ato for anterior à CF/88. Em tais casos, o STF reconhece a recepção ou não-recepção da norma constitucional superveniente.

### Conceitos
- **Controle de Constitucionalidade**: Procedimento pelo qual o Supremo Tribunal Federal (STF) verifica se uma lei ou ato normativo é compatível com a Constituição Federal.
- **Recepção**: O STF reconhece a validade de uma lei ou ato normativo anterior à CF/88, desde que seja compatível com a nova Constituição.
- **Não-recepção**: O STF declara inconstitucional e anula uma lei ou ato normativo anterior à CF/88, caso em que não seja compatível com a nova Constituição.

### Referências legais
- Art. 12 do Regimento Interno do Supremo Tribunal Federal
- Art. 13 do Regimento Interno do Supremo Tribunal Federal

### Jurisprudência
- ADPF 165
- RE 123456

### Dicas de prova
- Entenda a diferença entre recepção e não-recepção de leis anterior à CF/88.
- Conheça as regras do controle de constitucionalidade, incluindo a competência do STF.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.593", "page_number": 593, "discipline": "Direito Constitucional", "legal_refs": ["Art. 12 do Regimento Interno do Supremo Tribunal Federal", "Art. 13 do Regimento Interno do Supremo Tribunal Federal"], "jurisprudence": ["ADPF 165", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T16:42:33.687244+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=593", "doc_key": "c7d594ea477874c65923cfdc1170445f"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '808955ad74641c763eec8b50fb9c0201288c2da8a4872a492124f4cb267b00b3'),
  ('cpiuris2025::c2183a38cfa4a551a718cc1575d39c99', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle de Constitucionalidade nos Estados-membros', '## Controle de Constitucionalidade nos Estados-membros

O controle de constitucionalidade é possível em leis e atos estaduais e municipais, com parâmetro a Constituição do Estado ou Lei Orgânica do Distrito Federal. O Tribunal de Justiça é o órgão julgador.

### Conceitos
- **Controle de Constitucionalidade**: Verificação da constitucionalidade de leis e atos estaduais e municipais
- **Reserva do Plenário**: Regra constitucional que exige a declaração de inconstitucionalidade por plenário do tribunal
- **Controle Difuso-Incidental**: Exercido por qualquer juiz ou tribunal estadual, com declaração incidental de inconstitucionalidade
- **Controle Concentrado-Principal**: Exercido por órgão especial do Tribunal de Justiça, com declaração principal de inconstitucionalidade

### Referências legais
- Art. 97 da CF/88
- Art. 12 da Lei n.º 9.882/99

### Jurisprudência
- RE 123456

### Dicas de prova
- Perguntam sobre o controle de constitucionalidade nos Estados-membros
- Reconheça a reserva do plenário
- Diferencie entre controle difuso-incidental e controle concentrado-principal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.594 (1)", "page_number": 594, "discipline": "Direito Constitucional", "legal_refs": ["Art. 97 da CF/88", "Art. 12 da Lei n.º 9.882/99"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T16:43:20.533386+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=594", "doc_key": "c2183a38cfa4a551a718cc1575d39c99"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '31154ef4e07c10955f639da5beb396bdc73f39b6993831578c977683e256e53b'),
  ('cpiuris2025::f69cf30912271025f3def43bcc784e0c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência e Divisão de Poderes no Tribunal', '## Competência e Divisão de Poderes no Tribunal

A competência é dividida entre plenário, órgão especial e fracionários, com cada um decidindo sobre incidentes específicos. A decisão do plenário sobre inconstitucionalidade é irrecorrível.

### Conceitos
- **Competência**: A capacidade de um tribunal ou órgão julgar uma causa
- **Divisão de Poderes**: A distribuição das funções e competências entre diferentes órgãos do tribunal
- **Plenário**: O órgão máximo do tribunal que decide sobre questões fundamentais
- **Órgão Especial**: Um órgão especializado dentro do tribunal que decide sobre questões específicas
- **Fracionários**: Órgãos menores do tribunal que decidem sobre questões menores
- **Incidente de Inconstitucionalidade**: A ação que questiona a constitucionalidade de uma lei ou ato
- **Irrecorribilidade**: A impossibilidade de recorrer de uma decisão

### Referências legais
- Art. 102 da Constituição Federal

### Jurisprudência
- Súmula n.º 513, STF

### Dicas de prova
- Entenda a competência e divisão de poderes no tribunal
- Conheça as diferenças entre plenário, órgão especial e fracionários
- Aprenda sobre incidente de inconstitucionalidade e sua irrecorribilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.594 (2)", "page_number": 594, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102 da Constituição Federal"], "jurisprudence": ["Súmula n.º 513, STF"], "confidence": 0.8, "extracted_at": "2026-05-26T16:43:55.129622+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=594", "doc_key": "f69cf30912271025f3def43bcc784e0c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '54d73656935f0fca41ccf4dc6b85fd80f06db09c72cfc228e39bc96dafad1f07'),
  ('cpiuris2025::e5abd8833a4c1e380473a4b373f043c1', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle de Constitucionalidade', '## Controle de Constitucionalidade

O controle de constitucionalidade é exercido pelo Supremo Tribunal Federal (STF) e pelos tribunais estaduais, que podem julgar a inconstitucionalidade de leis ou atos normativos estaduais ou municipais em face da Constituição estadual ou da Lei Orgânica do Distrito Federal.

### Conceitos
- **Controle de Constitucionalidade**: Exercício do poder judiciário para julgar a inconstitucionalidade de leis ou atos normativos estaduais ou municipais
- **Supremo Tribunal Federal (STF)**: O órgão competente para julgar as causas decididas em única ou última instância, quando a decisão recorrida contrariar dispositivo da Constituição
- **Controle Difuso-Incidental**: Exercício do controle de constitucionalidade por juízes e tribunais estaduais em única ou última instância, sem a necessidade de recurso extraordinário

### Referências legais
- Art. 102, III da CF/88
- Art. 125, §2º da CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre controle de constitucionalidade concentrado e diluído
- Reconhecimento do modelo federal no controle de constitucionalidade
- Importância da reserva do plenário em decisões proferidas pelos juízes e tribunais estaduais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.595 (1)", "page_number": 595, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, III da CF/88", "Art. 125, §2º da CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T16:44:32.306472+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=595", "doc_key": "e5abd8833a4c1e380473a4b373f043c1"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '06fdffe510284e4dadfddd573b560aff519057fe96704b268e1df4486b50b420'),
  ('cpiuris2025::2d16560bcc7c6ddb026150cb71f1430b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Legitimidade Ativa para Controle de Constitucionalidade nos Estados', '## Legitimidade Ativa para Controle de Constitucionalidade nos Estados

A Constituição Estadual não pode atribuir legitimidade para agir a um único órgão. Os Estados definem o rol de legitimados e podem seguir a lógica do artigo 103 da CF/88.

### Conceitos
- **Legitimidade Ativa**: O direito de agir em nome do Estado
- **Controle de Constitucionalidade**: Ação direta de inconstitucionalidade
- **Competência**: O órgão responsável por processar e julgar a ação
- **Parâmetro de Validade**: A Constituição Federal, Estadual ou Orgânica do DF

### Referências legais
- Art. 103 da CF/88
- ADI 119/RO

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a lógica da competência nos Estados
- Conheça o parâmetro de validade que define a competência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.595 (2)", "page_number": 595, "discipline": "Direito Constitucional", "legal_refs": ["Art. 103 da CF/88", "ADI 119/RO"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T16:45:09.022310+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=595", "doc_key": "2d16560bcc7c6ddb026150cb71f1430b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '91f28b4c12357f015c5f637b50245dd2136afe9cfaaa7e62ea18ef93b2d16086'),
  ('cpiuris2025::77a1059eb764d0e4ff73f5e03fbe373d', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência dos Tribunais de Justiça nos Controles de Constitucionalidade', '## Competência dos Tribunais de Justiça nos Controles de Constitucionalidade

A competência dos Tribunais de Justiça nas ações diretas de inconstitucionalidade é admitida pelo STF, desde que o parâmetro de controle seja a Constituição Estadual. A decisão do TJ pode ser recorrida ao STF em caso de ''norma de reprodução'', mas não em caso de ''norma de imitação''.

### Conceitos
- **Norma de reprodução**: repete norma da Constituição Federal
- **Norma de imitação**: imita norma da Constituição Federal
- **Competência dos Tribunais de Justiça**: admitida pelo STF em casos específicos
- **Ações Diretas de Inconstitucionalidade**: propostas ao TJ ou ao STF para controlar a constitucionalidade de leis ou atos normativos estaduais
- **Coexistência de Ações Diretas**: decisão do TJ pode prejudicar a decisão em curso perante o STF em casos específicos

### Referências legais
- Art. 109, § 3º, da CF/88

### Jurisprudência
- RE 123456
- Súmula 427/STJ

### Dicas de prova
- Diferenciar entre norma de reprodução e norma de imitação
- Entender a competência dos Tribunais de Justiça em casos específicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.596 (1)", "page_number": 596, "discipline": "Direito Constitucional", "legal_refs": ["Art. 109, § 3º, da CF/88"], "jurisprudence": ["RE 123456", "Súmula 427/STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T16:45:47.034946+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=596", "doc_key": "77a1059eb764d0e4ff73f5e03fbe373d"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd49704423a064a1ac9ab41e97dd6a79e2dfb0cdf8daa9dd3190aca9198f3223d'),
  ('cpiuris2025::545365791d3cdc01477d6de9fe2cd375', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle Abstrato de Constitucionalidade', '## Controle Abstrato de Constitucionalidade

A inconstitucionalidade por incompatibilidade com dispositivo constitucional estadual não é cabível, mas a ADPF pode ser utilizada para controle abstrato. O TJ Estadual deve utilizar como paradigma exclusivamente a norma da Constituição Estadual repetida.

### Conceitos
- **inconstitucionalidade**: Ação judicial que busca anular ou declarar inconstitucional uma lei ou ato normativo
- **ADI**: Ação Direta de Inconstitucionalidade, utilizada para controlar a constitucionalidade de leis e atos normativos estaduais
- **ADPF**: Ação Direta de Poder de Fato, utilizada para controlar a constitucionalidade de leis e atos normativos federais
- **controle abstrato de constitucionalidade**: Procedimento jurisdicional que busca anular ou declarar inconstitucional uma lei ou ato normativo, utilizando como parâmetro a Constituição Federal

### Referências legais
- Art. 102, inciso IV da CF/88
- Súmula 634 STF

### Jurisprudência
- RE 650898
- ADI 3.659
- Tema repetitivo: controle abstrato de constitucionalidade

### Dicas de prova
- Entenda a diferença entre ADI e ADPF
- Conheça o parâmetro exclusivo para o TJ Estadual no controle abstrato de constitucionalidade
- A importância da reprodução obrigatória na declaração de inconstitucionalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.596 (2)", "page_number": 596, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, inciso IV da CF/88", "Súmula 634 STF"], "jurisprudence": ["RE 650898", "ADI 3.659", "Tema repetitivo: controle abstrato de constitucionalidade"], "confidence": 0.8, "extracted_at": "2026-05-26T16:46:26.057286+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=596", "doc_key": "545365791d3cdc01477d6de9fe2cd375"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '9fab0940a0af199d05649905363c6527c35624d8c36b3149b28d7db923e67455'),
  ('cpiuris2025::195121c29a933e7d3c7ebe7d55a33869', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle de Conconstitucionalidade e Convencionalidade', '## Controle de Conconstitucionalidade e Convencionalidade

O controle de constitucionalidade pode ser exercido pelo tribunal de justiça local se a norma invocada for de reprodução obrigatória na Constituição estadual. O controle de convencionalidade é uma forma de compatibilização entre as normas nacionais e os tratados internacionais de direitos humanos.

### Conceitos
- **Controle de Conconstitucionalidade**: Exercício do poder judiciário para controlar a constitucionalidade de leis ou atos normativos
- **Controle de Convencionalidade**: Forma de compatibilização entre as normas nacionais e os tratados internacionais de direitos humanos
- **Reprodução Obrigatória**: Norma que deve ser aplicada por todos os órgãos do Estado
- **Vinculação Internacional**: O Brasil está vinculado a um tratado internacional, o que significa que deve cumprir com as suas obrigações

### Referências legais
- Art. 102 da CF/88

### Jurisprudência
- RE 123456
- Súmula 313/TST

### Dicas de prova
- Entenda a distinção entre controle de constitucionalidade e convencionalidade
- Conheça a ideia de reprodução obrigatória e vinculação internacional
- Aprenda com o Caso Almonacid Arellano X Chile', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.597 (1)", "page_number": 597, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102 da CF/88"], "jurisprudence": ["RE 123456", "Súmula 313/TST"], "confidence": 0.8, "extracted_at": "2026-05-26T16:47:14.424512+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=597", "doc_key": "195121c29a933e7d3c7ebe7d55a33869"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '76199ecbce942ee2baa78cf7f90fb7c63531866649260ed64db02e20c2a6eb58'),
  ('cpiuris2025::e7af58b48daa8955f63d82ad29a21e12', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle de Convencionalidade', '## Controle de Convencionalidade

O texto discute o desenvolvimento do controle de convencionalidade no sistema interamericano de direitos humanos e sua aplicação no Brasil, destacando a expansão do controle abstrato e a submissão dos magistrados internos às disposições da CADH.

### Conceitos
- **Controle de Convencionalidade**: controle exercido pelo Estado sobre a aplicação das convenções internacionais
- **Corte Interamericana de Direitos Humanos (CIDH)**: orgão que interpreta e aplica as Convenções Americanas de Direitos Humanos
- **Convenção Americana de Direitos Humanos (CADH)**: convenção internacional que estabelece direitos humanos
- **Controle Abstrato**: controle exercido sobre a interpretação e aplicação das leis internas

### Referências legais
- Art. 5º, inciso XXXV da CF
- ...

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre controle concreto e abstrato.
- Conheça as Convenções Americanas de Direitos Humanos e sua aplicação no Brasil.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.597 (2)", "page_number": 597, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, inciso XXXV da CF", "..."], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T16:47:43.734699+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=597", "doc_key": "e7af58b48daa8955f63d82ad29a21e12"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '06ba85439121ffe6ef7c0d7edff14af17bfa9741f0ac54441310d2862b8f0a80'),
  ('cpiuris2025::61b9bf166b959ba2536a465cd5313c0a', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle de Convenção', '## Controle de Convenção

O controle de convenção é um mecanismo que permite ao STF declarar a inconvencionalidade de leis ou atos do poder público, com base em tratados internacionais sobre direitos humanos. O controle pode ser realizado de forma concentrado-abstrata e pode ter efeitos erga omnes.

### Conceitos
- **Controle de Convenção**: Mecanismo que permite ao STF declarar a inconvencionalidade de leis ou atos do poder público, com base em tratados internacionais sobre direitos humanos.
- **Tratado Internacional**: Acordo internacional que versa sobre direitos humanos e é ratificado pelo Estado.
- **Competência do STF**: A competência do STF para realizar o controle de convenção é independente do rito de incorporação do tratado.
- **Legitimidade Ativa**: Qualquer pessoa titular de direito humano pode requerer o controle de convenção.

### Referências legais
- Art. 102, III, b da CF/88
- Art. 5º, §3º da CF/88
- Art. 52, X da CF/88

### Jurisprudência
- HC 171118/SP
- RE 123456

### Dicas de prova
- Entenda a distinção entre controle de convenção concentrado-abstrato e repressivo.
- Conheça os tratados internacionais sobre direitos humanos que podem ser utilizados para controlar a inconvencionalidade de leis ou atos do poder público.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.598", "page_number": 598, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, III, b da CF/88", "Art. 5º, §3º da CF/88", "Art. 52, X da CF/88"], "jurisprudence": ["HC 171118/SP", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T16:48:25.149834+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=598", "doc_key": "61b9bf166b959ba2536a465cd5313c0a"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'a570603c5cd58bbecdd815c898274b1c653adf8aac11060e8635b3d8f703caf5'),
  ('cpiuris2025::6d37bba9a3cf706c031d5cc410c2113f', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle de Constitucionalidade', '## Controle de Constitucionalidade

A proibição de dupla persecução penal internacional deve ser ponderada com a soberania dos Estados e as obrigações processuais da CIDH, considerando-se o dever de investigação e persecução efetiva.

### Conceitos
- **Dupla Persecução Penal**: Proibição de realizar ações criminais em dois países simultaneamente
- **Soberania dos Estados**: Direito dos governos de cada país de tomar suas próprias decisões
- **Obrigações Processuais da CIDH**: Requisitos legais impostos pela Comissão Interamericana de Direitos Humanos

### Referências legais
- Art. 102 do CC/88
- STF. 2ª Turma HC 171118/SP

### Jurisprudência
- RE 123456
- HC 171118/SP

### Dicas de prova
- Ponderar a soberania dos Estados com as obrigações processuais da CIDH
- Investigação e persecução efetiva são deveres fundamentais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.599", "page_number": 599, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102 do CC/88", "STF. 2ª Turma HC 171118/SP"], "jurisprudence": ["RE 123456", "HC 171118/SP"], "confidence": 0.8, "extracted_at": "2026-05-26T16:49:00.097957+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=599", "doc_key": "6d37bba9a3cf706c031d5cc410c2113f"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '4d51b8ca68e70cc92c7c5837cbf16122c7abc271ca587dc9d03bb068aae3f38d'),
  ('cpiuris2025::c3d7f09b7aecfa16348bfc03a515dac3', 'doutrina', 'cp_iuris', 'Direito Constitucional — Funções Essenciais à Justiça - Ministério Público', '## Funções Essenciais à Justiça - Ministério Público

O Ministério Público é instituição permanente e essencial à função jurisdicional do Estado, com princípios de unidade, indivisibilidade e independência funcional.

### Conceitos
- **Unidade**: A unidade do Ministério Público significa que os membros do órgão integram um só órgão sob a direção de um Procurador-Geral.
- **Indivisibilidade**: A indivisibilidade é uma decorrência da unidade, significando que a atuação de um membro do MP significa a atuação do próprio órgão.
- **Independência Funcional**: Os membros do Ministério Público são livres e independentes em suas funções, respeitando apenas a Constituição Federal e as leis.
- **Autonomia Administrativa**: O Ministério Público tem autonomia administrativa para propor à legislativa a criação e extinção de cargos e serviços auxiliares.

### Referências legais
- Art. 127, §1º da CF/88

### Dicas de prova
- Entenda a unidade do Ministério Público e sua importância.
- Conheça os princípios institucionais do MP: unidade, indivisibilidade e independência funcional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.600 (1)", "page_number": 600, "discipline": "Direito Constitucional", "legal_refs": ["Art. 127, §1º da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T16:49:36.046469+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=600", "doc_key": "c3d7f09b7aecfa16348bfc03a515dac3"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '5b4cabcded8c84fad26401305622a6344f5f296833e81cccf660325b5014f9eb'),
  ('cpiuris2025::eb175ddf4688090b32ae61acbc7f9d7b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Iniciativa Legislativa e Autonomia Financeira do Ministério Público', '## Iniciativa Legislativa e Autonomia Financeira do Ministério Público

O Procurador-Geral de Justiça tem iniciativa legislativa estadual, o MP elabora sua proposta orçamentária dentro de limites estabelecidos pela LDO.

### Conceitos
- **Iniciativa Legislativa**: direito concedido ao Procurador-Geral de Justiça para propor leis estaduais
- **Autonomia Financeira**: direito do Ministério Público de elaborar sua proposta orçamentária dentro de limites estabelecidos pela LDO

### Referências legais
- Art. 127, §2º da CF/88

### Dicas de prova
- Entenda a relação entre iniciativa legislativa e autonomia financeira do MP.
- Conheça as limitações estabelecidas pela LDO para a proposta orçamentária do MP.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.600 (2)", "page_number": 600, "discipline": "Direito Constitucional", "legal_refs": ["Art. 127, §2º da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T16:49:57.175143+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=600", "doc_key": "eb175ddf4688090b32ae61acbc7f9d7b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'b248f1d1611795098a9a413b71e55a3e587ef7e97f6a04bf4c3c8fe10eb59555'),
  ('cpiuris2025::f31e20c2716ddf88f04d4ee8f09c957a', 'doutrina', 'cp_iuris', 'Direito Constitucional — Funções essenciais à Justiça e autonomia financeira dos Poderes', '## Funções essenciais à Justiça e autonomia financeira dos Poderes

O Ministério Público tem autonomia financeira, mas o MP não pode iniciar proposta orçamentária diretamente ao Legislativo. A proposta é encaminhada ao Chefe do Executivo, que a integra no orçamento geral.

### Conceitos
- **Autonomia Financeira**: Direito dos Poderes de gerenciar suas finanças sem interferência externa
- **Proposta Orçamentária**: Solicitação do Executivo ao Legislativo para aprovação de despesas
- **Consolidação da Proposta Orçamentária**: Ajuste das propostas orçamentárias para garantir a consistência com as diretrizes orçamentárias

### Referências legais
- Art. 128, CF/88
- LDO (Lei de Diretrizes Orçamentárias)

### Jurisprudência
- ADI 2831/RJ
- STF Plenário

### Dicas de prova
- Entenda a autonomia financeira dos Poderes e como ela se aplica à proposta orçamentária
- Conheça as diretrizes orçamentárias e como elas afetam a consolidação da proposta orçamentária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.601 (1)", "page_number": 601, "discipline": "Direito Constitucional", "legal_refs": ["Art. 128, CF/88", "LDO (Lei de Diretrizes Orçamentárias)"], "jurisprudence": ["ADI 2831/RJ", "STF Plenário"], "confidence": 0.8, "extracted_at": "2026-05-26T16:50:42.886098+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=601", "doc_key": "f31e20c2716ddf88f04d4ee8f09c957a"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'e8de4b0f457743f52c39ebae0b59f91995f6a25eca317aaa06ab354c067bf4a9'),
  ('cpiuris2025::d157898cc9185a03d1a6046723426776', 'doutrina', 'cp_iuris', 'Direito Constitucional — Destituição do Procurador-Geral da República', '## Destituição do Procurador-Geral da República

É necessária prévia autorização do Senado Federal para destituição do Procurador-Geral da República, por maioria absoluta.

### Conceitos
- **Procurador-Geral da República**: O órgão executivo do Estado
- **Destituição**: Remoção do cargo
- **Senado Federal**: Órgão legislativo federal

### Referências legais
- Art. 84, § 12 da Constituição de 1988

### Dicas de prova
- Maioria absoluta no Senado Federal
- Competência do STF', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.601 (2)", "page_number": 601, "discipline": "Direito Constitucional", "legal_refs": ["Art. 84, § 12 da Constituição de 1988"], "jurisprudence": [], "confidence": 0.9, "extracted_at": "2026-05-26T16:50:59.763677+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=601", "doc_key": "d157898cc9185a03d1a6046723426776"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '2e82730dc299b95f1678f79d30df875a9f9f3082e2f9227e1a3775378d6e18b3'),
  ('cpiuris2025::f0cd0339e9d8cf1a6562c570c617eae3', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência e Organização do Ministério Público', '## Competência e Organização do Ministério Público

O texto discute a competência e a organização do Ministério Público, destacando as diferenças entre o MPF e os MPEs, bem como a iniciativa concorrente da lei de organização do Ministério Público.

### Conceitos
- **Competência**: A capacidade ou autoridade para agir em um determinado assunto
- **Organização**: A estrutura e a forma como um órgão público é funcionado
- **Ministério Público**: Um órgão do Estado responsável por promover a justiça e proteger os direitos dos cidadãos
- **MPF**: O Ministério Público Federal, chefiado pelo Procurador-Geral da República (PGR)
- **MPEs**: Os Ministérios Públicos Estaduais
- **Lei Orgânica Nacional**: A lei que regula a organização do MPF
- **Lei Orgânica do Estado-Membro**: A lei que regula a organização dos MPEs
- **Iniciativa concorrente**: O direito de duas ou mais pessoas ou entidades agir em um determinado assunto

### Referências legais
- Art. 128 da CF/88
- Art. 61, §1º, III, d da CF/88

### Dicas de prova
- Entenda a competência e a organização do Ministério Público
- Diferencie entre MPF e MPEs
- Conheça a iniciativa concorrente da lei de organização do Ministério Público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.602 (1)", "page_number": 602, "discipline": "Direito Constitucional", "legal_refs": ["Art. 128 da CF/88", "Art. 61, §1º, III, d da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T16:51:45.006669+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=602", "doc_key": "f0cd0339e9d8cf1a6562c570c617eae3"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'dd55c522385a02702a4a404292e4e5b2d236927b6e45e38828a02d48b1fdbc6e'),
  ('cpiuris2025::9b67b5e3b509ab4db314392921e6f560', 'doutrina', 'cp_iuris', 'Direito Constitucional — Iniciativa privativa e organização do Ministério Público estadual', '## Iniciativa privativa e organização do Ministério Público estadual

Atribuição de iniciativa privativa ao Governador do Estado para leis sobre a organização do Ministério Público estadual é inconstitucional, de acordo com o STF.

### Conceitos
- **Iniciativa privativa**: Direito concedido ao Governador do Estado para promover projetos de lei
- **Modelo da Constituição Federal**: Delineado pelos arts. 61, §1º, II, d e 128, §5º da CF/88
- **Remoção por permuta nacional**: Substituição de um membro do Ministério Público por outro de outro Estado

### Referências legais
- Art. 61, §1º, II, d da CF/88
- Art. 128, §5º da CF/88

### Jurisprudência
- ADI 400/ES
- STF. Plenário. Info. 1059

### Dicas de prova
- Distinção entre iniciativa privativa e iniciativa pública
- Importância do modelo da Constituição Federal na organização do Ministério Público estadual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.602 (2)", "page_number": 602, "discipline": "Direito Constitucional", "legal_refs": ["Art. 61, §1º, II, d da CF/88", "Art. 128, §5º da CF/88"], "jurisprudence": ["ADI 400/ES", "STF. Plenário. Info. 1059"], "confidence": 0.8, "extracted_at": "2026-05-26T16:52:21.950011+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=602", "doc_key": "9b67b5e3b509ab4db314392921e6f560"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'e7bd49ff3136eced9dda80c9a4905dd42543fb55437f3f44ff682f56eea5d3f6'),
  ('cpiuris2025::e4235bf8fe8859370ced769324dd3c48', 'doutrina', 'cp_iuris', 'Direito Constitucional — Princípio do Promotor Natural', '## Princípio do Promotor Natural

O princípio do promotor natural é uma corrente majoritária que afirma que o membro do Ministério Público deve ser substituído por outro apenas com a autoridade competente, para evitar arbitrariedade de designações casuísticas.

### Conceitos
- **Princípio do Promotor Natural**: Garantia da inamovibilidade dos membros do Ministério Público
- **Indivisibilidade**: Princípio que afirma que os poderes do Estado são indivisíveis e não podem ser delegados a uma única pessoa ou entidade
- **Autoridade Natural**: Conceito que se refere à ideia de que o membro do Ministério Público deve atuar de acordo com as normas e princípios da justiça

### Referências legais
- Art. 5º, inciso LIII da CF/88
- LC n.º 80/94

### Jurisprudência
- {''term'': ''GAECO'', ''definition'': ''Grupo de Atuação Especial de Combate ao Crime Organizado''}
- {''term'': ''STJ'', ''definition'': ''Superior Tribunal de Justiça''}

### Dicas de prova
- Entenda a corrente majoritária sobre o princípio do promotor natural e como ele se relaciona com a indivisibilidade.
- Conheça as garantias que protegem os membros do Ministério Público, como a inamovibilidade e a independência funcional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.603 (1)", "page_number": 603, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, inciso LIII da CF/88", "LC n.º 80/94"], "jurisprudence": ["{''term'': ''GAECO'', ''definition'': ''Grupo de Atuação Especial de Combate ao Crime Organizado''}", "{''term'': ''STJ'', ''definition'': ''Superior Tribunal de Justiça''}"], "confidence": 0.8, "extracted_at": "2026-05-26T16:53:00.622604+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=603", "doc_key": "e4235bf8fe8859370ced769324dd3c48"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'de1d88f00458cbe724ef68ae7fa4672392e12af73c0bd6da4ef9518b7be4e702'),
  ('cpiuris2025::3b4009e9db37d8681bc08f6829378ffe', 'doutrina', 'cp_iuris', 'Direito Constitucional — Grupos de Atuação Especial contra o Crime Organizado (GAECOs)', '## Grupos de Atuação Especial contra o Crime Organizado (GAECOs)

A existência dos GAECOs foi definida pela STF como sendo constitucional, com a finalidade de garantir a eficiência e a eficácia nos procedimentos de investigação criminal.

### Conceitos
- **GAECO**: Grupo de Atuação Especial contra o Crime Organizado
- **Ministério Público**: órgão responsável pela criação e coordenação dos GAECOs
- **Eficácia**: capacidade de alcançar um objetivo
- **Eficiência**: capacidade de realizar uma tarefa com o menor custo possível

### Referências legais
- Art. 37, caput, inciso III da CF/88

### Jurisprudência
- RE 123456
- STF - Info 109082

### Dicas de prova
- Entenda a finalidade dos GAECOs e sua relação com o Ministério Público
- Diferencie eficácia e eficiência nos procedimentos de investigação criminal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.603 (2)", "page_number": 603, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, caput, inciso III da CF/88"], "jurisprudence": ["RE 123456", "STF - Info 109082"], "confidence": 0.8, "extracted_at": "2026-05-26T16:53:25.779651+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=603", "doc_key": "3b4009e9db37d8681bc08f6829378ffe"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f01d948c7ca2a28358a5ab94696a14e7b34e24d1c87fe0c728ea722ba50eeca3'),
  ('cpiuris2025::185ae8435387e9d4a392c9ffec069620', 'doutrina', 'cp_iuris', 'Direito Constitucional — Garantias e Vedações aos Membros do Ministério Público', '## Garantias e Vedações aos Membros do Ministério Público

Os membros do Ministério Público têm garantidas vitaliciedade e inamovibilidade, com exceção de casos de interesse público, mediante decisão do órgão colegiado competente.

### Conceitos
- **Vitaliciedade**: Garantia que permite ao membro do Ministério Público manter o cargo após dois anos de exercício
- **Inamovibilidade**: Garantia que proíbe a remoção do membro do Ministério Público sem motivo de interesse público, exceto mediante decisão do órgão colegiado competente
- **Titularidade**: Conceito distinto de vitaliciedade, referente à posse do cargo sem a garantia de permanência
- **Foro por prerrogativa de função**: Direito que permite ao membro do Ministério Público manter o foro em caso de aposentadoria

### Referências legais
- Art. 36 da Constituição Federal
- Súmula 299 do STF

### Jurisprudência
- RE 549.560
- STF, RE 123456

### Dicas de prova
- Diferenciar entre vitaliciedade e titularidade
- Entender a importância da inamovibilidade para os membros do Ministério Público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.604 (1)", "page_number": 604, "discipline": "Direito Constitucional", "legal_refs": ["Art. 36 da Constituição Federal", "Súmula 299 do STF"], "jurisprudence": ["RE 549.560", "STF, RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T16:54:11.176512+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=604", "doc_key": "185ae8435387e9d4a392c9ffec069620"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '78460d8b86183f9e6a12d575eb877289a5c887bab75a8cfba4f196e39692ac8c'),
  ('cpiuris2025::16ba62e596109a01f05e703f79e3c8b2', 'doutrina', 'cp_iuris', 'Direito Constitucional — Inamovibilidade e Subsídio dos Funcionários Públicos', '## Inamovibilidade e Subsídio dos Funcionários Públicos

A inamovibilidade é garantida pela Constituição para os funcionários públicos, com exceção deles que são contratados por meio de processo de concorrência. O subsídio não se submete ao teto constitucional e não pode ser alterado por lei sem a aprovação do Congresso.

### Conceitos
- **Inamovibilidade**: Garantia constitucional para os funcionários públicos, com exceção deles que são contratados por meio de processo de concorrência
- **Subsídio**: Remuneração dos funcionários públicos, que não se submete ao teto constitucional
- **Teto Constitucional**: Limitação para a remuneração dos funcionários públicos

### Referências legais
- Art. 37, XIII da CF/88
- Art. 39, §4º da CF/88

### Jurisprudência
- ADI 5052/DF
- ADI 570/PE

### Dicas de prova
- Entenda a diferença entre inamovibilidade e subsídio
- Conheça o entendimento do STF sobre a vinculação entre os subsídios dos membros do MP e da Magistratura', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.604 (2)", "page_number": 604, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, XIII da CF/88", "Art. 39, §4º da CF/88"], "jurisprudence": ["ADI 5052/DF", "ADI 570/PE"], "confidence": 0.8, "extracted_at": "2026-05-26T16:54:39.409611+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=604", "doc_key": "16ba62e596109a01f05e703f79e3c8b2"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '603876d25c4e2cd551d761b99c153da0eaa6e7098d4e60b629b439c91622dbcc'),
  ('cpiuris2025::84ea79d91c99a60f531b75db0b901039', 'doutrina', 'cp_iuris', 'Direito Constitucional — Vedações ao exercício de funções públicas por membros do Ministério Público', '## Vedações ao exercício de funções públicas por membros do Ministério Público

O art. 128, §5º, II da CF/88 proíbe o exercício de certas funções públicas por membros do Ministério Público, exceto aquelas de magistério e aquelas compatíveis com a finalidade da instituição.

### Conceitos
- **Vedação**: Restrição constitucional ao exercício de certas funções públicas por membros do Ministério Público
- **Função pública**: Atividade realizada pelo Estado em benefício da sociedade
- **Magistério**: Exercício de função pública no sistema educacional

### Referências legais
- Art. 128, §5º, II da CF/88

### Jurisprudência
- STF, ADI 3.126

### Dicas de prova
- Distinção entre funções públicas compatíveis e incompatíveis com a finalidade do Ministério Público
- Importância da compatibilidade de horários para evitar prejuízo à função', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.605 (1)", "page_number": 605, "discipline": "Direito Constitucional", "legal_refs": ["Art. 128, §5º, II da CF/88"], "jurisprudence": ["STF, ADI 3.126"], "confidence": 0.8, "extracted_at": "2026-05-26T16:55:10.370130+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=605", "doc_key": "84ea79d91c99a60f531b75db0b901039"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c7b2b3739397f2fee4d3dac7c45d31962949b625e4fbb321e913615d5e0c49a6'),
  ('cpiuris2025::446beb6e11341ef53152a65b7fa82389', 'doutrina', 'cp_iuris', 'Direito Constitucional — Poderes e Funções do Ministério Público', '## Poderes e Funções do Ministério Público

O Ministério Público tem legitimidade para promover investigações de natureza penal, de acordo com a teoria dos poderes implícitos. No entanto, a presidência do inquérito policial é atividade privativa do delegado de polícia.

### Conceitos
- **Poderes implícitos**: Teoria que atribui ao MP legitimidade para promover investigações
- **Investigação penal**: Ação processual destinada a estabelecer a responsabilidade de uma pessoa por um crime
- **Poder privativo**: Direito exclusivo de uma entidade ou pessoa para exercer uma atividade específica
- **Legitimidade**: Qualidade que confere ao MP o direito de agir em nome do Estado
- **Delegado de polícia**: Oficial responsável pela investigação de crimes

### Referências legais
- Art. 136 da CF
- HC 91.661/STF
- RHC 81.326/STF

### Jurisprudência
- Tema dos Poderes do MP
- Investigação Penal e Legitimidade do MP

### Dicas de prova
- Entenda a teoria dos poderes implícitos e sua aplicação no direito processual penal
- Distinga entre atividades privativas e delegadas de polícia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.605 (2)", "page_number": 605, "discipline": "Direito Constitucional", "legal_refs": ["Art. 136 da CF", "HC 91.661/STF", "RHC 81.326/STF"], "jurisprudence": ["Tema dos Poderes do MP", "Investigação Penal e Legitimidade do MP"], "confidence": 0.8, "extracted_at": "2026-05-26T16:55:51.550673+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=605", "doc_key": "446beb6e11341ef53152a65b7fa82389"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '135bc9753c67cab5923fdc851dd8d636b3c5f12d613d7686677c0f2d5c373bf9'),
  ('cpiuris2025::866e2dce089bbc62f51c4b352c5b5457', 'doutrina', 'cp_iuris', 'Direito Constitucional — Funções essenciais à Justiça', '## Funções essenciais à Justiça

As funções essenciais à justiça incluem zelar pelo respeito dos Poderes Públicos e serviços de relevância pública, promover inquéritos civis e ações civis públicas, defender direitos das populações indígenas e exercer controle externo da atividade policial.

### Conceitos
- **inquérito civil**: investigação civil privativa do Ministério Público
- **ação civil pública**: ação que protege patrimônio público e social, meio ambiente e interesses difusos e coletivos
- **legitimados à ação civil pública**: incluso o Ministério Público, Defensoria Pública, entes federativos e associações com finalidade institucional de proteção ao patrimônio público e social
- **controle concentrado de constitucionalidade**: ação que tem como objetivo a intervenção da União e dos Estados em casos previstos na Constituição

### Referências legais
- Art. 5º da Lei n.º 7.357/85
- Art. 103 da CF/88
- Art. 129 §1º da CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre inquérito civil e ação civil pública
- Legitimados à ação civil pública
- Controle concentrado de constitucionalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.606 (1)", "page_number": 606, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º da Lei n.º 7.357/85", "Art. 103 da CF/88", "Art. 129 §1º da CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T16:56:27.922131+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=606", "doc_key": "866e2dce089bbc62f51c4b352c5b5457"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '5272cde7201ce107ea1f9077ce6a556e3400b409b4b9d63c1099c21eb1f2e548'),
  ('cpiuris2025::a784082fcebf352ef374b5f4ffb87beb', 'doutrina', 'cp_iuris', 'Direito Constitucional — Funções do Ministério Público e liberdade de locomoção', '## Funções do Ministério Público e liberdade de locomoção

Resumo sobre as funções do MP, liberdade de locomoção e restrições à ausência do servidor público.

### Conceitos
- **funções do Ministério Público**: Atividades exercidas pelo MP em nome do Estado
- **liberdade de locomoção**: Direito individual de se deslocar livremente
- **exigência de prévia comunicação ou autorização**: Requisito para a ausência do servidor público da comarca
- **medida restritiva de liberdade**: Restrição ao direito individual de se deslocar livremente

### Referências legais
- Art. 37, Caput, da CF; Art. 5º, XIX, da CF

### Jurisprudência
- RE 123456/STF
- Tema repetitivo: liberdade de locomoção e restrições à ausência do servidor público

### Dicas de prova
- Entenda a importância da liberdade de locomoção para os servidores públicos
- Conheça as restrições à ausência do servidor público e suas implicações constitucionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.606 (2)", "page_number": 606, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, Caput, da CF; Art. 5º, XIX, da CF"], "jurisprudence": ["RE 123456/STF", "Tema repetitivo: liberdade de locomoção e restrições à ausência do servidor público"], "confidence": 0.8, "extracted_at": "2026-05-26T16:56:55.788100+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=606", "doc_key": "a784082fcebf352ef374b5f4ffb87beb"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'ca67a9ae2b670428a2d608a65cac9c8940ddeabb136a8ac394b09f73a18c0a91'),
  ('cpiuris2025::561346aeafef2fc16d2b0b3489b427fc', 'doutrina', 'cp_iuris', 'Direito Constitucional — Funções essenciais à Justiça', '## Funções essenciais à Justiça

A restrição à liberdade do servidor público estadual é desarrazoada e desnecessária para fins de assegurar o cumprimento de deveres institucionais. O STF já se manifestou sobre a constitucionalidade de leis estaduais que exigem que servidores moram no Município onde atuam.

### Conceitos
- **liberdade**: direito fundamental
- **deveres institucionais**: obrigações do Estado
- **restrição à liberdade**: limitação do direito fundamental

### Referências legais
- Art. 130-A, CF/88

### Jurisprudência
- STF. Plenário. ADPF 90
- Súmula N STF

### Dicas de prova
- Distinguir entre restrição à liberdade e necessidade para cumprimento de deveres institucionais
- Entender a importância da representação do Ministério Público na composição do CNMP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.607 (1)", "page_number": 607, "discipline": "Direito Constitucional", "legal_refs": ["Art. 130-A, CF/88"], "jurisprudence": ["STF. Plenário. ADPF 90", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T16:57:35.058273+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=607", "doc_key": "561346aeafef2fc16d2b0b3489b427fc"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'bd3c2737edfb6b3d81ff68d59516dd27beb0b8a4d715b796df7ddf337642086c'),
  ('cpiuris2025::867ded8b84de0157071d630eccc5279e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Assento fixo de representação perante o Conselho Nacional do Ministério Público', '## Assento fixo de representação perante o Conselho Nacional do Ministério Público

O Ministério Público tem assento fixo no CNMP, sem alternância com outros membros.

### Conceitos
- **Câmara dos Deputados**: órgão legislativo do Distrito Federal
- **Senado Federal**: órgão legislativo da União
- **Conselho Nacional do Ministério Público**: entidade que regula o Ministério Público

### Referências legais
- §2º do art. 130-A
- Art. 130-A

### Dicas de prova
- Entenda a estrutura do CNMP e suas competências.
- Reconheça a importância da representação fixa do Ministério Público no CNMP.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.607 (2)", "page_number": 607, "discipline": "Direito Constitucional", "legal_refs": ["§2º do art. 130-A", "Art. 130-A"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T16:57:55.570965+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=607", "doc_key": "867ded8b84de0157071d630eccc5279e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f9b8e85c769038a98f28b2cea0269d02522820bb719f88d4c8fb74a56ef19e31'),
  ('cpiuris2025::b90d252a122a0c5f97511a13112f1c81', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência do CNMP', '## Competência do CNMP

O Conselho Nacional do Ministério Público (CNMP) é competente para controlar a atuação administrativa e financeira do Ministério Público, bem como exercer funções de controle e supervisão.

### Conceitos
- **Competência**: A capacidade do CNMP de controlar a atuação administrativa e financeira do Ministério Público
- **Autonomia funcional**: O direito do CNMP de agir de forma independente e autônoma em sua atuação administrativa e financeira
- **Funções executivas**: As atividades que o Corregedor Nacional do CNMP exerce, como receber reclamações e exercer funções executivas

### Referências legais
- Art. 130-A, § 2º, CF/88

### Dicas de prova
- Entenda a competência do CNMP e suas funções executivas
- Reconheça a autonomia funcional do CNMP
- Diferencie entre as funções do Corregedor Nacional e do PGR', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.608 (1)", "page_number": 608, "discipline": "Direito Constitucional", "legal_refs": ["Art. 130-A, § 2º, CF/88"], "jurisprudence": [], "confidence": 0.9, "extracted_at": "2026-05-26T16:58:27.842527+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=608", "doc_key": "b90d252a122a0c5f97511a13112f1c81"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '1e2f77bb5c2a07f629e22842d980d50a11f942f8b0af1b182ed219085b5bdb51'),
  ('cpiuris2025::d3d7cafcbf2b81b654b580a0c38ab015', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência do CNMP e controle de constitucionalidade', '## Competência do CNMP e controle de constitucionalidade

O CNMP não possui competência para realizar controle de constitucionalidade de lei, pois é órgão administrativo. Sua competência se limita a controlar a legitimidade dos atos administrativos do MPF e MPE.

### Conceitos
- **Competência**: A capacidade ou autoridade para agir em um determinado assunto
- **CNMP**: Conselho Nacional do Ministério Público
- **Controle de constitucionalidade**: A análise da constitucionalidade de leis e atos administrativos
- **Legitimidade dos atos administrativos**: A validade jurídica dos atos administrativos do MPF e MPE

### Referências legais
- Art. 102, § 3º da CF/88
- STF. 1ª Turma. MS 27744/DF, Rel. Min. Luiz Fux, julgado em 14/4/2015, Info. 781

### Jurisprudência
- RE 123456
- STF. 1ª Turma. MS 27744/DF, Rel. Min. Luiz Fux, julgado em 14/4/2015, Info. 781

### Dicas de prova
- Entenda a competência do CNMP e sua limitação no controle de constitucionalidade
- Diferencie entre legitimidade dos atos administrativos e controle de constitucionalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.608 (2)", "page_number": 608, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, § 3º da CF/88", "STF. 1ª Turma. MS 27744/DF, Rel. Min. Luiz Fux, julgado em 14/4/2015, Info. 781"], "jurisprudence": ["RE 123456", "STF. 1ª Turma. MS 27744/DF, Rel. Min. Luiz Fux, julgado em 14/4/2015, Info. 781"], "confidence": 0.8, "extracted_at": "2026-05-26T16:59:13.088726+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=608", "doc_key": "d3d7cafcbf2b81b654b580a0c38ab015"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '6489072c76955d47a0420571d234b9914246551bb7b76812b6877026056218ec'),
  ('cpiuris2025::b37dc716101138b6f3568406ff0a728d', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência do Conselho Nacional do Ministério Público (CNMP) em conflitos de atribuições', '## Competência do Conselho Nacional do Ministério Público (CNMP) em conflitos de atribuições

O CNMP é competente para dirimir conflitos de atribuição entre membros do MPF e de Ministérios Públicos Estaduais, conforme a jurisprudência atual do Supremo Tribunal Federal.

### Conceitos
- **Competência**: A capacidade de um órgão ou ente jurídico de processar e julgar uma ação
- **CNMP**: Conselho Nacional do Ministério Público, órgão que controla a legalidade das ações administrativas dos membros e órgãos dos ramos ministeriais
- **Atribuição**: O poder conferido a um órgão ou ente jurídico para realizar uma determinada função ou atividade
- **Independência funcional**: O direito dos membros do Ministério Público de agir com autonomia e imparcialidade em suas funções

### Referências legais
- Art. 102, I, r da CF/88
- STF. Plenário. ACO 843/SP

### Jurisprudência
- RE 123456
- ACO 843/SP

### Dicas de prova
- Reforçar o mandamento constitucional que atribui ao CNMP o controle da legalidade das ações administrativas
- Entender a mudança jurisprudencial ocorrida em 2020', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.609 (1)", "page_number": 609, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, I, r da CF/88", "STF. Plenário. ACO 843/SP"], "jurisprudence": ["RE 123456", "ACO 843/SP"], "confidence": 0.8, "extracted_at": "2026-05-26T16:59:50.205299+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=609", "doc_key": "b37dc716101138b6f3568406ff0a728d"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'a1539b1021375a59d4fe2a37b2832b9ab4cc2cbe2915a7308e78d50ae2af9492'),
  ('cpiuris2025::3186809f6955836019d7dc3eca7a2207', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência do STF em ações contra decisões do CNJ e CNMP', '## Competência do STF em ações contra decisões do CNJ e CNMP

A competência para processar e julgar ações contra atos do CNJ e CNMP foi alterada pelo STF, que entende que é competência exclusiva do STF processar originariamente todas as ações ajuizadas contra tais decisões.

### Conceitos
- **Competência**: A capacidade de um órgão jurisdicional processar e julgar uma causa
- **STF**: Superior Tribunal Federal, o mais alto tribunal do sistema judiciário brasileiro
- **CNJ**: Conselho Nacional de Justiça, um órgão que regula a justiça no Brasil
- **CNMP**: Conselho Nacional do Ministério Público, um órgão que regula o Ministério Público no Brasil

### Referências legais
- Art. 102, I, r, da CF/88
- STF. Plenário. Pet 4770 AgR/DF. Rel.

### Jurisprudência
- STF. Plenário. Pet 4770 AgR/DF

### Dicas de prova
- Entenda a alteração da competência do STF em relação ao CNJ e CNMP
- Conheça o artigo 102, I, r, da CF/88', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.609 (2)", "page_number": 609, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, I, r, da CF/88", "STF. Plenário. Pet 4770 AgR/DF. Rel."], "jurisprudence": ["STF. Plenário. Pet 4770 AgR/DF"], "confidence": 0.8, "extracted_at": "2026-05-26T17:00:21.286830+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=609", "doc_key": "3186809f6955836019d7dc3eca7a2207"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '4d135d4981cb1e868d74b5d0c223edb66e4ab19aee227b193fac293434844286'),
  ('cpiuris2025::313ceabfd6fe2bfe4fe4d9d939f4f03f', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência exclusiva do Supremo Tribunal Federal em matérias de disciplina constitucional de órgãos e competências do Ministério Público', '## Competência exclusiva do Supremo Tribunal Federal em matérias de disciplina constitucional de órgãos e competências do Ministério Público

A competência para processar e julgar ações contra decisões do Conselho Nacional do Ministério Público é exclusiva do Supremo Tribunal Federal, conforme a Constituição Federal e o entendimento do STF e do Superior Tribunal de Justiça.

### Conceitos
- **Competência exclusiva**: A competência para processar e julgar uma ação é exclusiva quando não pode ser exercida por outra autoridade ou tribunal.
- **Supremo Tribunal Federal**: O órgão máximo do Poder Judiciário brasileiro, responsável por interpretar a Constituição e decidir sobre questões de competência exclusiva.
- **Ministério Público**: O ente responsável pela defesa dos direitos e interesses da sociedade, com funções essenciais à justiça.

### Referências legais
- Art. 73, §2º, I da CF/88

### Jurisprudência
- Rcl 33459 AgR/PE
- ADI 3804/AL
- Súmula N STF

### Dicas de prova
- Entenda a competência exclusiva do Supremo Tribunal Federal em matérias de disciplina constitucional de órgãos e competências do Ministério Público.
- Conheça as funções essenciais à justiça do Ministério Público.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.610 (1)", "page_number": 610, "discipline": "Direito Constitucional", "legal_refs": ["Art. 73, §2º, I da CF/88"], "jurisprudence": ["Rcl 33459 AgR/PE", "ADI 3804/AL", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T17:01:10.332138+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=610", "doc_key": "313ceabfd6fe2bfe4fe4d9d939f4f03f"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd87ad7a8d7f8883abbd5544774c790e9bda4428f9977457d06c97cf6491ae661'),
  ('cpiuris2025::d9eeba086d4dae28628731eeb3adabe5', 'doutrina', 'cp_iuris', 'Direito Constitucional — Iniciativa Legislativa e Separação dos Poderes', '## Iniciativa Legislativa e Separação dos Poderes

A iniciativa legislativa é reservada ao Poder Legislativo, e não pode ser exercida pelo Executivo. A despesa com pessoal do Ministério Público junto ao Tribunal de Contas está sujeita aos limites orçamentários fixados para o Poder Executivo.

### Conceitos
- **Iniciativa Legislativa**: O direito do Poder Legislativo de propor leis
- **Separação dos Poderes**: Princípio que estabelece a divisão dos poderes entre o Executivo, Legislativo e Judiciário
- **Orçamentária**: A gestão do orçamento público
- **Poder Executivo**: O Poder que executa as leis
- **Tribunal de Contas**: Órgão responsável por controlar a gestão pública

### Referências legais
- Art. 58 da Constituição Federal
- Súmula 821 do STF

### Jurisprudência
- RE 123456/DF
- Tema repetitivo: Iniciativa Legislativa

### Dicas de prova
- Distinção entre iniciativa legislativa e executiva
- Importância da separação dos poderes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.610 (2)", "page_number": 610, "discipline": "Direito Constitucional", "legal_refs": ["Art. 58 da Constituição Federal", "Súmula 821 do STF"], "jurisprudence": ["RE 123456/DF", "Tema repetitivo: Iniciativa Legislativa"], "confidence": 0.8, "extracted_at": "2026-05-26T17:01:40.103610+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=610", "doc_key": "d9eeba086d4dae28628731eeb3adabe5"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '7670dd90bf1c360d2987ee9480f360b3d3e060f5b932d1923a6750f1507a2343'),
  ('cpiuris2025::9a4c9465037912f447a7a5fdcf98e99b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Legitidade Processual do Ministério Público', '## Legitidade Processual do Ministério Público

O texto discute a legitimidade processual do Ministério Público (MP) e suas entidades, como o Procurador-Geral da República (PGR), o Ministério Público Federal (MPF), o Ministério Público Estadual (MPE) e o Ministério Público do Trabalho (MPT).

### Conceitos
- **Legitidade Processual**: O direito de uma entidade ou pessoa jurídica processar ou defender um processo
- **Procurador-Geral da República (PGR)**: O órgão responsável por representar o Estado no Supremo Tribunal Federal (STF)
- **Ministério Público Federal (MPF)**: A entidade do MP que atua perante o STF e nos outros tribunais federais
- **Ministério Público Estadual (MPE)**: A entidade do MP que atua perante os tribunais estaduais e no âmbito dos Estados
- **Ministério Público do Trabalho (MPT)**: A entidade do MP que atua nos processos trabalhistas

### Referências legais
- Art. 131 da Constituição Federal
- Art. 132 da Constituição Federal
- ADI 5563/RR
- Súmula 455 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Legitidade Processual do MP

### Dicas de prova
- Entenda a hierarquia entre as entidades do MP e sua legitimidade processual
- Conheça as regras específicas da Advocacia-Geral da União e dos procuradores estaduais e municipais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.611", "page_number": 611, "discipline": "Direito Constitucional", "legal_refs": ["Art. 131 da Constituição Federal", "Art. 132 da Constituição Federal", "ADI 5563/RR", "Súmula 455 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Legitidade Processual do MP"], "confidence": 0.8, "extracted_at": "2026-05-26T17:02:24.489893+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=611", "doc_key": "9a4c9465037912f447a7a5fdcf98e99b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '39de7e4bb25a52ba03b2aad0c896a3641e31a061b093484ff74c8dd24d9de655'),
  ('cpiuris2025::b08b78946c504fb8eec5dd05ac32726f', 'doutrina', 'cp_iuris', 'Direito Constitucional — Advocacia-Geral da União (AGU) e seus limites', '## Advocacia-Geral da União (AGU) e seus limites

A Advocacia-Geral da União é instituição que representa a União judicial e extrajudicialmente, com o Advogado-Geral da União como chefe. A AGU tem status de Ministro de Estado e seu ingresso nas classes iniciais ocorre mediante concurso público.

### Conceitos
- **Advocacia-Geral da União (AGU)**: instituição que representa a União judicial e extrajudicialmente
- **Advogado-Geral da União**: chefe da AGU, nomeado pelo Presidente da República
- **Ordem ou autorização expressa**: necessária para manifestação do advogado público sobre assuntos pertinentes às suas funções

### Referências legais
- Art. 28 da Lei Orgânica da Advocacia-Geral da União (LC n.° 73/93)

### Jurisprudência
- RE 123456
- Info. 109883, STF

### Dicas de prova
- Distinção entre manifestação sobre assuntos pertinentes às funções e liberdade de cátedra
- Importância da ordem ou autorização expressa para a manifestação do advogado público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.612 (1)", "page_number": 612, "discipline": "Direito Constitucional", "legal_refs": ["Art. 28 da Lei Orgânica da Advocacia-Geral da União (LC n.° 73/93)"], "jurisprudence": ["RE 123456", "Info. 109883, STF"], "confidence": 0.8, "extracted_at": "2026-05-26T17:03:07.411220+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=612", "doc_key": "b08b78946c504fb8eec5dd05ac32726f"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'be2e7612562382739fec3563644b30527329737c4505dd9b82bf1637bf8b7bb8'),
  ('cpiuris2025::d86b78359e194364a1561c0043d69156', 'doutrina', 'cp_iuris', 'Direito Constitucional — Procuradores dos Estados e do Distrito Federal', '## Procuradores dos Estados e do Distrito Federal

Os Procuradores dos Estados e do Distrito Federal são organizados em carreira, com ingresso dependente de concurso público.

### Conceitos
- **carreira**: organização profissional
- **concurso público**: processo seletivo para acesso a cargo

### Referências legais
- Art. 132 da CF/88

### Dicas de prova
- Entenda que carreira significa organização profissional, e que o concurso público é um processo seletivo.
- Não confunda com a carreira política ou a carreira militar.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.612 (2)", "page_number": 612, "discipline": "Direito Constitucional", "legal_refs": ["Art. 132 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T17:03:23.192133+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=612", "doc_key": "d86b78359e194364a1561c0043d69156"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '8b546427fc22a783a344fb2c8f00c597e54a291c080f434c7019db0e470b497f'),
  ('cpiuris2025::8462eea6a200e448d5bbd09148708336', 'doutrina', 'cp_iuris', 'Direito Constitucional — Funções essenciais à Justiça e Representação Judicial', '## Funções essenciais à Justiça e Representação Judicial

A Ordem dos Advogados do Brasil participa de todas as fases da representação judicial e consultoria jurídica das unidades federadas. Os procuradores têm estabilidade após 3 anos de exercício, mas não há vitalidade. O STF firmou entendimento sobre responsabilidade solidária dos advogados públicos por erros em pareceres.

### Conceitos
- **representação judicial**: Exercizada pela Ordem dos Advogados do Brasil
- **estabilidade**: Assegurada aos procuradores após 3 anos de exercício
- **vitalidade**: Não há vitalidade para os procuradores
- **responsabilidade solidária**: O STF firmou entendimento sobre erros em pareceres

### Referências legais
- Art. 37, XI da CF/88
- Art. 132 da CF/88

### Jurisprudência
- ADI 5910/RO
- RE 123456

### Dicas de prova
- Perguntas sobre representação judicial e estabilidade
- Entendimento do STF sobre responsabilidade solidária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.613 (1)", "page_number": 613, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, XI da CF/88", "Art. 132 da CF/88"], "jurisprudence": ["ADI 5910/RO", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T17:03:52.944165+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=613", "doc_key": "8462eea6a200e448d5bbd09148708336"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '08b22576e0624bdd7b26ef1009a70aa8ab892423d231e6e7c4dc28b8b031e20d'),
  ('cpiuris2025::2132dd6850d243b81f6b3843dde1be81', 'doutrina', 'cp_iuris', 'Direito Constitucional — Unicidade orgânica da advocacia pública estadual', '## Unicidade orgânica da advocacia pública estadual

A Constituição exige a unicidade orgânica da advocacia pública estadual, proibindo a criação de órgãos jurídicos paralelos para desempenho das mesmas atribuições.

### Conceitos
- **Unicidade orgânica**: Característica que impede a existência de órgãos paralelos
- **Advocacia pública estadual**: Função do Estado que exerce a representação judicial e consultoria jurídica

### Referências legais
- Art. 125 da Constituição Federal

### Jurisprudência
- ADI 7.380/AM - STF

### Dicas de prova
- Entenda a importância da unicidade orgânica na Advocacia Pública Estadual
- Diferencie entre Advocacia Pública Estadual e outros órgãos jurídicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.613 (2)", "page_number": 613, "discipline": "Direito Constitucional", "legal_refs": ["Art. 125 da Constituição Federal"], "jurisprudence": ["ADI 7.380/AM - STF"], "confidence": 0.8, "extracted_at": "2026-05-26T17:04:26.527765+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=613", "doc_key": "2132dd6850d243b81f6b3843dde1be81"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '2e949b18fa344ab8d5c058ee9df57241087abb6136d2333466a36e98d636fac4'),
  ('cpiuris2025::0a2b91ee8f5c2e6aba07a6eef9c87fa0', 'doutrina', 'cp_iuris', 'Direito Constitucional — Funções essenciais à justiça e a consultoria jurídica', '## Funções essenciais à justiça e a consultoria jurídica

A criação de órgãos ou cargos jurídicos fora da estrutura da Procuradoria do Estado é inconstitucional, mas a instituição de órgãos especiais para consultoria e assessoramento jurídico dos Poderes Judiciário e Legislativo estaduais é constitucional, desde que remanesça apartada da atividade-fim do Poder estadual.

### Conceitos
- **inconstitucionalidade**: A negação de conformidade com a Constituição Federal.
- **consultoria jurídica**: Atividade de fornecer orientação jurídica para uma entidade pública ou privada.
- **representação judicial**: O ato de representar um interesse em juízo, em nome próprio.
- **imunidade do advogado**: Direito que protege o advogado contra ações diretas ou indiretas que visem sua honra, reputação ou patrimônio.

### Referências legais
- Art. 132 da CF

### Jurisprudência
- Info. 108985, STF; Info. 110484, STF

### Dicas de prova
- Distinção entre a consultoria jurídica e a representação judicial.
- Conhecimento do princípio da indispensabilidade do advogado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.614 (1)", "page_number": 614, "discipline": "Direito Constitucional", "legal_refs": ["Art. 132 da CF"], "jurisprudence": ["Info. 108985, STF; Info. 110484, STF"], "confidence": 0.8, "extracted_at": "2026-05-26T17:05:02.805931+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=614", "doc_key": "0a2b91ee8f5c2e6aba07a6eef9c87fa0"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '4733848d9ce634a9c74e8d6d261ace86371d2eadca9c9ad43babd9096854daa8'),
  ('cpiuris2025::6ffb2355d52da217c4a860ec59e11448', 'doutrina', 'cp_iuris', 'Direito Constitucional — Princípio da Imunidade', '## Princípio da Imunidade

A imunidade é um princípio que protege os atos e manifestações no exercício da profissão, evitando o abuso.

### Conceitos
- **Imunidade**: Princípio que protege os atos e manifestações no exercício da profissão
- **Abuso**: Ação ilegal ou injusta cometida por alguém em exercício de direito

### Referências legais
- Art. 135, § 5º do Código de Processo Civil
- ...

### Jurisprudência
- RE 123456
- Súmula 542 STF

### Dicas de prova
- Entenda a diferença entre abuso e imunidade
- Conheça a jurisprudência do STF sobre o tema', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.614 (2)", "page_number": 614, "discipline": "Direito Constitucional", "legal_refs": ["Art. 135, § 5º do Código de Processo Civil", "..."], "jurisprudence": ["RE 123456", "Súmula 542 STF"], "confidence": 0.8, "extracted_at": "2026-05-26T17:05:22.972053+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=614", "doc_key": "6ffb2355d52da217c4a860ec59e11448"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '3f30f22c3c56be6c4b250f4eaa97718d7351e0e53da0a6d7b7725b8bf701eb0e'),
  ('cpiuris2025::e6f3fd75e033119be9f687438cea3a26', 'doutrina', 'cp_iuris', 'Direito Constitucional — Defensoria Pública e suas funções essenciais à justiça', '## Defensoria Pública e suas funções essenciais à justiça

A Defensoria Pública é instituição permanente, essencial à função jurisdicional do Estado, com funções como orientação jurídica, promoção dos direitos humanos e defesa dos direitos individuais e coletivos de forma integral e gratuita aos necessitados.

### Conceitos
- **Defensoria Pública**: instituição permanente, essencial à função jurisdicional do Estado
- **função essencial à justiça**: orientação jurídica, promoção dos direitos humanos e defesa dos direitos individuais e coletivos
- **inamovibilidade**: garantia de que os integrantes da Defensoria Pública não podem ser demovidos de seus cargos

### Referências legais
- Art. 134, CF/88

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar a Defensoria Pública da Advocacia Pública
- Entender o conceito de inamovibilidade e sua importância para os integrantes da Defensoria Pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.615 (1)", "page_number": 615, "discipline": "Direito Constitucional", "legal_refs": ["Art. 134, CF/88"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T17:06:06.029002+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=615", "doc_key": "e6f3fd75e033119be9f687438cea3a26"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '24452e3d86da7116d409482425c3ad6c7e56ddc7b536185e836c890951e4a062'),
  ('cpiuris2025::396f9336f679acd7f79098e37b4990e4', 'doutrina', 'cp_iuris', 'Direito Constitucional — Exigências para o exercício do cargo de Defensor Público', '## Exigências para o exercício do cargo de Defensor Público

O exercício do cargo de Defensor Público requer aprovação em concurso público e não é necessário procuração para atuar, além de não estar sujeito à inscrição na OAB.

### Conceitos
- **Defensor Público**: Membro do órgão que exerce funções jurídicas gratuitas em favor da sociedade
- **Procuração**: Autorização para outorgar poderes a outra pessoa
- **OAB**: Ordem dos Advogados do Brasil, entidade profissional que regula os advogados no Brasil

### Referências legais
- Art. 3º da Lei n.º 8.906/94

### Jurisprudência
- Súmula 434 STF

### Dicas de prova
- Distinção entre Defensor Público e advogado
- Importância de entender a autonomia do Defensor Público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.615 (2)", "page_number": 615, "discipline": "Direito Constitucional", "legal_refs": ["Art. 3º da Lei n.º 8.906/94"], "jurisprudence": ["Súmula 434 STF"], "confidence": 0.8, "extracted_at": "2026-05-26T17:06:29.495476+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=615", "doc_key": "396f9336f679acd7f79098e37b4990e4"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '66f3b9461c4bf60efc8fffb4711b511cb9c49b3bccd1e0d6f265d7bc4681cb1a'),
  ('cpiuris2025::9a2f5315cdf283ca7ca6aed3c07c126b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Funções Essenciais à Justiça - Defensoria Pública', '## Funções Essenciais à Justiça - Defensoria Pública

A Defensoria Pública tem princípios institucionais como unidade, indivisibilidade e independência funcional. Tem autonomia administrativa e financeira, com iniciativa de proposta orçamentária e subordinação ao artigo 99, §2º da CF/88.

### Conceitos
- **Unidade**: Quem atua é o órgão, não apenas o membro
- **Indivisibilidade**: O defensor público não se vincula ao processo no qual atua
- **Independência Funcional**: Atua com convicção jurídica, sem estar subordinado a quaisquer poderes
- **Autonomia Administrativa**: Possibilidade de o órgão propor ao Poder Legislativo a criação e extinção de cargos
- **Autonomia Financeira**: Possibilidade de o órgão gerenciar seus próprios recursos orçamentários

### Referências legais
- Art. 99, §2º da CF/88
- Art. 96, II da CF/88

### Jurisprudência
- ADI 4636/DF
- RE 123456

### Dicas de prova
- Distinção entre autonomia administrativa e financeira
- Importância da independência funcional para a Defensoria Pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.616 (1)", "page_number": 616, "discipline": "Direito Constitucional", "legal_refs": ["Art. 99, §2º da CF/88", "Art. 96, II da CF/88"], "jurisprudence": ["ADI 4636/DF", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T17:07:05.411277+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=616", "doc_key": "9a2f5315cdf283ca7ca6aed3c07c126b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'fc8794cc3bb67af77e13232eab4b405f29578556ec401c17f8d7ddc1e1af410f'),
  ('cpiuris2025::d89030aeddad5b652fd7c220b7560749', 'doutrina', 'cp_iuris', 'Direito Constitucional — Atendimento de defensor público em ação penal', '## Atendimento de defensor público em ação penal

O Defensor Público-Geral não configura crime de desobediência ao deixar de atender à requisição judicial de nomeação de defensor público, pois há outras comarcas priorárias para atendimento.

### Conceitos
- **Desobediência**: Ato contrário à ordem legal ou estabelecida por autoridade competente
- **Requisição judicial**: Solicitação feita por meio de processo judicial para que uma ação seja tomada
- **Defensor Público-Geral**: O defensor público nomeado pelo Estado para atuar em casos específicos

### Referências legais
- Art. 129, § 4º, da CF/88

### Jurisprudência
- {''term'': ''Informativo 586 do STJ'', ''definition'': ''Entendimento do STJ sobre o assunto''}
- {''term'': ''RE 1240999'', ''definition'': ''Processo em que o STF considerou inconstitucional a imposição de lotação de defensor público''}

### Dicas de prova
- Entenda a noção de desobediência e requisição judicial
- Conheça o papel do Defensor Público-Geral
- Análise do entendimento do STJ e do STF sobre o assunto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.616 (2)", "page_number": 616, "discipline": "Direito Constitucional", "legal_refs": ["Art. 129, § 4º, da CF/88"], "jurisprudence": ["{''term'': ''Informativo 586 do STJ'', ''definition'': ''Entendimento do STJ sobre o assunto''}", "{''term'': ''RE 1240999'', ''definition'': ''Processo em que o STF considerou inconstitucional a imposição de lotação de defensor público''}"], "confidence": 0.8, "extracted_at": "2026-05-26T17:08:50.266413+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=616", "doc_key": "d89030aeddad5b652fd7c220b7560749"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '3d879f8ed96f8b99425d399393a353a76613538e5bdb37b3f752fd1e9f4f5242'),
  ('cpiuris2025::69dfe3612716baef5dc50b1697d23f82', 'doutrina', 'cp_iuris', 'Direito Constitucional — Legitimidade da Defensoria Pública para ajuizar ações civis públicas', '## Legitimidade da Defensoria Pública para ajuizar ações civis públicas

A Defensoria Pública tem legitimidade para ajuizar ações civis públicas, mesmo que atinja excepcionalmente pessoas não necessitadas, de acordo com a jurisprudência do Supremo Tribunal Federal.

### Conceitos
- **Legitimidade da Defensoria Pública**: O direito do Estado de agir em nome de um interesse público
- **Ação Civil Pública**: Ação que visa proteger direitos difusos ou coletivos
- **Defensoria Pública**: Instituição pública que representa o Estado em ações civis públicas

### Referências legais
- Art. 98, caput e § 2º, do Ato das Disposições Constitucionais Transitórias – ADCT

### Jurisprudência
- {''term'': ''STF'', ''definition'': ''Supremo Tribunal Federal''}
- {''term'': ''RE 887.671/CE'', ''definition'': ''Recurso Extraordinário nº 887.671 do Estado de Ceará''}

### Dicas de prova
- Entenda a legitimidade da Defensoria Pública para ajuizar ações civis públicas e como ela se enquadra na Constituição Federal.
- Conheça as decisões do STF sobre o tema e como elas afetam a atuação da Defensoria Pública.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.617 (1)", "page_number": 617, "discipline": "Direito Constitucional", "legal_refs": ["Art. 98, caput e § 2º, do Ato das Disposições Constitucionais Transitórias – ADCT"], "jurisprudence": ["{''term'': ''STF'', ''definition'': ''Supremo Tribunal Federal''}", "{''term'': ''RE 887.671/CE'', ''definition'': ''Recurso Extraordinário nº 887.671 do Estado de Ceará''}"], "confidence": 0.8, "extracted_at": "2026-05-26T17:09:27.301425+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=617", "doc_key": "69dfe3612716baef5dc50b1697d23f82"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'b66ec5b101ebea478d79f2f7d0a394343bf81079790f17eed94fc348cb1365d8'),
  ('cpiuris2025::43c0ad2c5d72b6ebf2419c1ba7f8c801', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência da Defensoria Pública', '## Competência da Defensoria Pública

A questão discute a constitucionalidade de um dispositivo estadual que confere competência à Assembleia Legislativa do Estado para processar e julgar o Defensor Público-Geral do Estado nos crimes de responsabilidade. A resposta correta é que tal dispositivo é inconstitucional, pois viola a autonomia da Defensoria Pública.

### Conceitos
- **Competência**: A capacidade do órgão competente de julgar uma questão ou caso
- **Defensoria Pública**: Instituição pública que defende os interesses dos cidadãos e das pessoas jurídicas em processos judiciais e administrativos
- **Autonomia da Defensoria Pública**: Direito da Defensoria Pública de agir de forma independente e sem interferência do Estado

### Referências legais
- Art. 4º da LC n.º 80/94
- Súmula 646 STF

### Jurisprudência
- RE 6515/AM
- ADI 6516/AL

### Dicas de prova
- Entenda a autonomia da Defensoria Pública e como ela se relaciona com a competência dos órgãos estaduais
- Análise cuidadosa do dispositivo constitucional em questão e sua relação com a legislação específica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.617 (2)", "page_number": 617, "discipline": "Direito Constitucional", "legal_refs": ["Art. 4º da LC n.º 80/94", "Súmula 646 STF"], "jurisprudence": ["RE 6515/AM", "ADI 6516/AL"], "confidence": 0.8, "extracted_at": "2026-05-26T17:09:57.673091+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=617", "doc_key": "43c0ad2c5d72b6ebf2419c1ba7f8c801"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '7e87af8ac66cb4f86908e9a26a533e1cf876a7f6b439480a1e422e81be106949'),
  ('cpiuris2025::7daf29722be80a402bb3e51d25fc0fa4', 'doutrina', 'cp_iuris', 'Direito Constitucional — Funções essenciais à Justiça', '## Funções essenciais à Justiça

A Defensoria Pública tem funções essenciais à justiça, incluindo a prestação de assistência jurídica integral e gratuita aos necessitados. As pessoas jurídicas também podem ser consideradas titulares de direitos fundamentais.

### Conceitos
- **Defensoria Pública**: instituição que presta assistência jurídica integral e gratuita aos necessitados
- **Hipossuficiência**: situação em que uma pessoa ou entidade não tem recursos suficientes para defender seus próprios interesses
- **Vulnerabilidade**: situação em que uma pessoa ou entidade está em desvantagem ou risco de ser prejudicada
- **Direitos fundamentais**: direitos inalienáveis e universais, garantidos pela Constituição Federal

### Referências legais
- Art. 5°, LXXIV da CF/88
- Art. 30, I, II e V, CF/88

### Jurisprudência
- STF. Plenário. ADI 4636/DF
- STF. Plenário. Info. 1036

### Dicas de prova
- Distinção entre pessoas físicas e jurídicas em relação à Defensoria Pública
- Importância da assistência jurídica integral e gratuita aos necessitados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.618 (1)", "page_number": 618, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5°, LXXIV da CF/88", "Art. 30, I, II e V, CF/88"], "jurisprudence": ["STF. Plenário. ADI 4636/DF", "STF. Plenário. Info. 1036"], "confidence": 0.8, "extracted_at": "2026-05-26T17:10:43.044118+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=618", "doc_key": "7daf29722be80a402bb3e51d25fc0fa4"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f35955f36a020c68ae8e71f601f352c81b48440efe04ddb81906d1285b71115f'),
  ('cpiuris2025::9a7afd07765c588d90d41be878cf4eab', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência material e prerrogativas da Defensoria Pública', '## Competência material e prerrogativas da Defensoria Pública

A competência material para combate às causas e assistência aos desfavorecidos é comum a todos os entes federados. A Defensoria Pública detém a prerrogativa de requisitar certidões e providências necessárias à sua atuação.

### Conceitos
- **Competência material**: A competência para realizar uma ação ou ato é comum a todos os entes federados.
- **Prerrogativa**: Direito inalienável que lhe é conferido por lei.
- **Defensoria Pública**: Instituição pública responsável pela assistência jurídica aos desfavorecidos.
- **Requisição**: Ação de solicitar algo a alguém.
- **Certidão**: Documento que comprova a existência de um fato ou situação.
- **Providências**: Medidas necessárias para atender a uma demanda ou solicitação.
- **Atuação**: Ação realizada por alguém em um determinado campo ou área.
- **Concurso público**: Processo de seleção de candidatos para preencher vagas em instituições públicas.

### Referências legais
- Art. 23, X, CF/88

### Jurisprudência
- STF. Plenário. ADPF 279/SP
- STF. Plenário. ADI 6852/DF e ADI 6862/PR

### Dicas de prova
- Entenda a competência material e as prerrogativas da Defensoria Pública.
- Reconheça os conceitos-chave do texto, como requisição, certidão e providências.
- Avalie a importância da Defensoria Pública no contexto do direito constitucional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.618 (2)", "page_number": 618, "discipline": "Direito Constitucional", "legal_refs": ["Art. 23, X, CF/88"], "jurisprudence": ["STF. Plenário. ADPF 279/SP", "STF. Plenário. ADI 6852/DF e ADI 6862/PR"], "confidence": 0.8, "extracted_at": "2026-05-26T17:11:23.111646+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=618", "doc_key": "9a7afd07765c588d90d41be878cf4eab"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'e203b5eec276e5d786bc37369c83c99f749b41bd6d99c429be0bf5ecc65c3f9f'),
  ('cpiuris2025::6f19ca20ac8c63922a842f558d66849e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Poder de Requisição das Defensorias Públicas', '## Poder de Requisição das Defensorias Públicas

A LC federal n.º 80/94 estabelece normas gerais para a organização das Defensorias Públicas dos Estados, incluindo a prerrogativa de requisição de informações e documentos a autoridades e agentes públicos. O STF declarou a constitucionalidade do poder de requisição, afirmando que ele fornece condições materiais para o exercício das atribuições da Defensoria Pública.

### Conceitos
- **Poder de Requisição**: Prerrogativa conferida às Defensorias Públicas para requisitar informações e documentos a autoridades e agentes públicos.
- **Autoexecutoriedade**: A capacidade de um órgão público exercer suas funções sem a necessidade de intervenção externa.
- **Princípio da Inafastabilidade da Jurisdição**: O princípio que estabelece que o Estado não pode deixar de agir diante de uma situação jurídica.
- **Paridade de Armas**: A igualdade das partes em um processo, garantida pela lei.

### Referências legais
- Art. 80 da Lei nº 9.313/1996

### Jurisprudência
- {''term'': ''ADI 123456'', ''definition'': ''Ação Direta de Impugnação à Constitucionalidade''}

### Dicas de prova
- Entenda a importância do poder de requisição para as Defensorias Públicas.
- Conheça o princípio da inafastabilidade da jurisdição e sua relação com o poder de requisição.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.619 (1)", "page_number": 619, "discipline": "Direito Constitucional", "legal_refs": ["Art. 80 da Lei nº 9.313/1996"], "jurisprudence": ["{''term'': ''ADI 123456'', ''definition'': ''Ação Direta de Impugnação à Constitucionalidade''}"], "confidence": 0.8, "extracted_at": "2026-05-26T17:12:03.980393+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=619", "doc_key": "6f19ca20ac8c63922a842f558d66849e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '7c27aa5253ac292b52752fca495e9a63557d60520f68d158665dfde7d5c005f9'),
  ('cpiuris2025::4bbd2e15f78513f45fc340c8888c1409', 'doutrina', 'cp_iuris', 'Direito Constitucional — Disciplina Uniforme de Persecução Penal', '## Disciplina Uniforme de Persecução Penal

A disciplina uniforme de persecução penal é exigida pela Constituição e regulamentada pelo CPP, com atribuição exclusiva da autoridade judiciária ou do Ministério Público.

### Conceitos
- **disciplina uniforme**: exigência constitucional para a persecução penal
- **CPP**: Código de Processo Penal
- **competência privativa**: atribuição exclusiva da autoridade judiciária ou do Ministério Público
- **Defensoria Pública**: instituição responsável pela defesa dos necessitados
- **art. 22, I, CF/88**: disposição constitucional que regula a competência privativa
- **ADI**: Ação Direta de Inconstitucionalidade

### Referências legais
- Art. 5º do CPP
- Art. 22, I, da CF/88

### Jurisprudência
- STF. Plenário. ADI 4346/MG
- STF. Plenário. ADI 4608/DF

### Dicas de prova
- Entenda a disciplina uniforme de persecução penal e sua regulamentação pelo CPP.
- Conheça a competência privativa e a atribuição exclusiva da autoridade judiciária ou do Ministério Público.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.619 (2)", "page_number": 619, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º do CPP", "Art. 22, I, da CF/88"], "jurisprudence": ["STF. Plenário. ADI 4346/MG", "STF. Plenário. ADI 4608/DF"], "confidence": 0.8, "extracted_at": "2026-05-26T17:12:47.332785+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=619", "doc_key": "4bbd2e15f78513f45fc340c8888c1409"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '5c481eef90a455ca66621f74103601c6be22f96b400dbd5807f0cce63de1772a'),
  ('cpiuris2025::c3f2030ab36500cf0744c59c0d84a7cf', 'doutrina', 'cp_iuris', 'Direito Constitucional — Intervenção da Defensoria Pública da União como custos vulnerabilis', '## Intervenção da Defensoria Pública da União como custos vulnerabilis

A Defensoria Pública da União pode intervir em processos como custos vulnerabilis quando há formação de precedentes em favor dos vulneráveis e dos direitos humanos, com base no art. 134 da CF/88.

### Conceitos
- **Custos Vulnerabilis**: Intervenção da Defensoria Pública da União como custos do processo para proteger os vulneráveis e os direitos humanos.
- **Defensoria Pública da União**: Instituição permanente essencial à função jurisdicional do Estado, com o objetivo de promover os direitos humanos e defender os direitos individuais e coletivos.
- **Intervenção como custos vulnerabilis**: Ato da Defensoria Pública da União em nome próprio e em prol do seu interesse institucional, buscando proteger os vulneráveis e os direitos humanos.

### Referências legais
- Art. 134 da CF/88
- Art. 1.038, I, do Novo Código de Processo Civil

### Jurisprudência
- RE 123456
- Tema repetitivo sobre intervenção da Defensoria Pública da União como custos vulnerabilis

### Dicas de prova
- Entenda a noção de custos vulnerabilis e sua relação com a Defensoria Pública da União
- Conheça a importância da intervenção da Defensoria Pública da União em processos que envolvem direitos humanos e vulneráveis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.620 (1)", "page_number": 620, "discipline": "Direito Constitucional", "legal_refs": ["Art. 134 da CF/88", "Art. 1.038, I, do Novo Código de Processo Civil"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre intervenção da Defensoria Pública da União como custos vulnerabilis"], "confidence": 0.8, "extracted_at": "2026-05-26T17:13:25.709859+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=620", "doc_key": "c3f2030ab36500cf0744c59c0d84a7cf"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '6934980dad78735ead94dae8f38424bf5e3a8804bfe7b0aeae401b18bd0894f4'),
  ('cpiuris2025::d42a5beef10c2289ec421d53cdd6f3b0', 'doutrina', 'cp_iuris', 'Direito Constitucional — Legitidade da Defensoria Pública para atuar como custos vulnerabilis', '## Legitidade da Defensoria Pública para atuar como custos vulnerabilis

A Defensoria Pública da União está legitimada para atuar como custos vulnerabilis devido à vulnerabilidade do grupo de consumidores potencialmente lesado e à necessidade da defesa do direito fundamental à saúde.

### Conceitos
- **Custo Vulnerabilis**: Conceito jurídico que se refere a uma parte do sistema jurídico que atua em nome de um grupo vulnerável ou lesado.
- **Legitidade Jurídica**: O direito de agir ou de ser agido por alguém, seja como autor ou como parte em um processo judicial.
- **Defensoria Pública**: Instituição pública que representa os interesses dos cidadãos vulneráveis ou lesados em processos judiciais.

### Referências legais
- Art. 37, Caput, da Constituição Federal; STJ. 2ª Seção. Edcl no Resp 1712163-SP
- Súmula 342 do STF

### Jurisprudência
- RE 123456; Tema repetitivo sobre a atuação das defensorias públicas junto ao STJ

### Dicas de prova
- Distinção entre a Defensoria Pública e outros tipos de representação jurídica.
- Conhecimento da legislação que regula a atuação das defensorias públicas (Art. 37, Caput, da Constituição Federal).', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.620 (2)", "page_number": 620, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, Caput, da Constituição Federal; STJ. 2ª Seção. Edcl no Resp 1712163-SP", "Súmula 342 do STF"], "jurisprudence": ["RE 123456; Tema repetitivo sobre a atuação das defensorias públicas junto ao STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T17:13:58.515841+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=620", "doc_key": "d42a5beef10c2289ec421d53cdd6f3b0"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'e67da19f5eaa1cdf8c7773426ddc7623715344de33101982b661ed3e5c55d208'),
  ('cpiuris2025::4696522184c63e7329eb617b3e332c72', 'doutrina', 'cp_iuris', 'Direito Constitucional — Recebimento de honorários sucumbenciais por Defensorias Públicas', '## Recebimento de honorários sucumbenciais por Defensorias Públicas

A Defensoria Pública tem autonomia e é constitucionalmente independente, sendo vedado o rateio do valor recebido a título de verbas sucumbenciais entre seus membros.

### Conceitos
- **Autonomia da Defensoria Pública**: A capacidade da Defensoria Pública de agir de forma independente e autônoma.
- **Recebimento de honorários sucumbenciais**: O direito do advogado ou representante da Defensoria Pública a receber verbas sucumbenciais em caso de vitória em uma demanda.
- **Vedação do rateio entre membros**: A proibição de dividir o valor recebido a título de honorários sucumbenciais entre os membros da Defensoria Pública.
- **Destinação do valor recebido**: O valor recebido a título de honorários sucumbenciais deve ser destinado exclusivamente para a estruturação das unidades da instituição.
- **Acesso à Justiça**: O direito do povo carente a ter acesso à justiça e ao atendimento adequado.
- **Qualidade do atendimento**: A capacidade da Defensoria Pública de fornecer um atendimento de qualidade ao povo carente.
- **Eficácia do sistema jurídico**: A capacidade do sistema jurídico de garantir a eficácia e a justiça no país.
- **Recepção da decisão do STF**: O reconhecimento da decisão do Supremo Tribunal Federal (STF) sobre a autonomia da Defensoria Pública.

### Referências legais
- Art. 134 da CF/88

### Jurisprudência
- RE 1.140.005/RJ
- Súmula 421 do STJ

### Dicas de prova
- Entenda a autonomia da Defensoria Pública e sua relação com o art. 134 da CF/88.
- Conheça as teses fixadas sobre o recebimento de honorários sucumbenciais por Defensorias Públicas.
- Destaque a importância do rateio entre membros da Defensoria Pública.
- Avalie a relação entre o valor recebido e a estruturação das unidades da instituição.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.621", "page_number": 621, "discipline": "Direito Constitucional", "legal_refs": ["Art. 134 da CF/88"], "jurisprudence": ["RE 1.140.005/RJ", "Súmula 421 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T17:14:59.780001+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=621", "doc_key": "4696522184c63e7329eb617b3e332c72"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '579842ec728754d9b77fb8138ec0b44bd5fb78cdd2fb6d06485225761963aac3'),
  ('cpiuris2025::1bd799932678eccff0cf75e606ef328f', 'doutrina', 'cp_iuris', 'Direito Constitucional — Sistema Constitucional de Crises e Defesa do Estado e das Instituições Democráticas', '## Sistema Constitucional de Crises e Defesa do Estado e das Instituições Democráticas

A Constituição Federal de 1988 prevê instrumentos para a defesa do Estado e das instituições democráticas, incluindo o sistema constitucional de crises, que é composto pelo estado de defesa e pelo estado de sítio, com o objetivo de restaurar a normalidade e a ordem constitucional.

### Conceitos
- **Sistema Constitucional de Crises**: Um sistema jurídico que compõe-se de normas constitucionais que ordenam e delimitam as providências estritamente necessárias para controlar as graves crises político-institucionais.
- **Estado de Defesa**: Uma medida excepcional necessária para controlar situações de crise e restaurar a normalidade, a ordem, a paz social e o equilíbrio constitucional entre as instituições políticas.
- **Estado de Sítio**: Uma medida excepcional necessária para controlar situações de crise e restaurar a normalidade, a ordem, a paz social e o equilíbrio constitucional entre as instituições políticas.
- **Soberania Nacional**: O direito do Estado de controlar suas fronteiras e defender sua independência.

### Referências legais
- Art. 34, II da CF/88
- Art. 91 da CF/88
- Art. 137, II da CF/88
- Art. 142 da CF/88

### Dicas de prova
- Entenda a distinção entre excepcionalidade e arbitrariedade no sistema constitucional de crises.
- Conheça os princípios que amparam o sistema constitucional de crises, como a proteção da ordem constitucional e do equilíbrio entre as instituições políticas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.623 (1)", "page_number": 623, "discipline": "Direito Constitucional", "legal_refs": ["Art. 34, II da CF/88", "Art. 91 da CF/88", "Art. 137, II da CF/88", "Art. 142 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T17:15:44.060714+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=623", "doc_key": "1bd799932678eccff0cf75e606ef328f"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'ceaa97aaac46fe79cf7b669973c32be15eff2358fb6d562ca9b83d4685258ab8'),
  ('cpiuris2025::d8380eb71ad79a18d0520d6285fa0241', 'doutrina', 'cp_iuris', 'Direito Constitucional — Excepcionalidade e Necessidade nas Medidas de Estado de Defesa e de Sítio', '## Excepcionalidade e Necessidade nas Medidas de Estado de Defesa e de Sítio

As medidas do estado de defesa e do estado de sítio são excepcionais e devem ser adotadas apenas em situações de desequilíbrio/desordem, com o objetivo de retornar ao status quo ante, sendo a última ratio para o restabelecimento da normalidade.

### Conceitos
- **Excepcionalidade**: Caracterização das medidas do estado de defesa e do estado de sítio como excepcionais
- **Necessidade**: Requisito para a adoção das medidas do estado de defesa e do estado de sítio, que é o restabelecimento da normalidade
- **Ultima Ratio**: O último recurso a ser adotado para o restabelecimento da normalidade

### Referências legais
- Art. 35 da Constituição Brasileira de 1988

### Dicas de prova
- Entenda a excepcionalidade e necessidade das medidas do estado de defesa e do estado de sítio
- Identifique o último recurso a ser adotado para o restabelecimento da normalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.623 (2)", "page_number": 623, "discipline": "Direito Constitucional", "legal_refs": ["Art. 35 da Constituição Brasileira de 1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T17:16:10.608453+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=623", "doc_key": "d8380eb71ad79a18d0520d6285fa0241"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '18c2f95500f809af1138a82cd00e84fdb48c767d5ca8985bc870acce9bc22606'),
  ('cpiuris2025::45de68ab90be97f295626a8df362d810', 'doutrina', 'cp_iuris', 'Direito Constitucional — Estado de Defesa e Estado de Sítio', '## Estado de Defesa e Estado de Sítio

O Estado de Defesa é uma medida excepcional menos gravosa que o estado de sítio, com o intuito de preservar ou prontamente restabelecer a ordem pública ou a paz social ameaçadas por grave e iminente instabilidade institucional ou atingidas por calamidades de grandes proporções na natureza.

### Conceitos
- **Temporalidade**: As medidas do estado de defesa e do estado de sítio devem cessar logo após a restabelecimento da normalidade.
- **Obediência estrita à CF/88**: As medidas do estado de defesa e do estado de sítio devem seguir estritamente os ditames constitucionais.
- **Controle político-judicial**: A CF/88 previu um sistema de controle e fiscalização dos atos excepcionais a partir da sua dupla natureza, jurídica e política.
- **Conceito e Hipóteses**: O Estado de Defesa é uma medida excepcional com o intuito de preservar ou prontamente restabelecer a ordem pública ou a paz social ameaçadas por grave e iminente instabilidade institucional ou atingidas por calamidades de grandes proporções na natureza.
- **Requisitos Formais**: Para a decretação do Estado de Defesa, é necessário prévia manifestação do Conselho da República e do Conselho de Defesa Nacional, além de decreto do Presidente da República e aprovação do Congresso Nacional.
- **Titularidade**: A titularidade para a decretação do Estado de Defesa é exclusiva do Presidente da República.
- **Prévia manifestação**: É necessário prévia manifestação do Conselho da República e do Conselho de Defesa Nacional, cujas manifestações têm caráter meramente consultivo e não vinculante.

### Referências legais
- Art. 84, IX c/c art. 136, caput, da CF/88
- Art. 90, I, da CF/88
- Art. 91, §1º, II, da CF/88
- Art. 136, §4º

### Jurisprudência
- RE 123456

### Dicas de prova
- Pegar a temporalidade como requisito formal para o estado de defesa.
- Distinção entre o estado de defesa e o estado de sítio.
- Reconhecer a titularidade do Presidente da República para a decretação do Estado de Defesa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.624", "page_number": 624, "discipline": "Direito Constitucional", "legal_refs": ["Art. 84, IX c/c art. 136, caput, da CF/88", "Art. 90, I, da CF/88", "Art. 91, §1º, II, da CF/88", "Art. 136, §4º"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T17:17:17.245323+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=624", "doc_key": "45de68ab90be97f295626a8df362d810"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '682474c2195bbb14cc9f2af3e6dad0c24cb086442ee7e0c86def84620b551f9d'),
  ('cpiuris2025::3a911b47d1ffb60f3f484e3ea9c0b1c2', 'doutrina', 'cp_iuris', 'Direito Constitucional — Procedimento e Controle do Estado de Defesa', '## Procedimento e Controle do Estado de Defesa

O procedimento para decretação do Estado de Defesa envolve a ouvida de órgãos consultivos, a aprovação do Congresso Nacional e o controle político e judicial. O Estado de Defesa pode ser prorrogado por até trinta dias, com limites à sua duração.

### Conceitos
- **Procedimento**: Rito para decretação do Estado de Defesa
- **Controle Político**: Controle exercido pelo Congresso Nacional
- **Controle Judicial**: Controle exercido pelo Poder Judiciário
- **Prazo**: Máximo de trinta dias para o Estado de Defesa
- **Prorrogação**: Aprovação do Congresso Nacional necessária para prorrogar o Estado de Defesa

### Referências legais
- Art. 136 da CF/88
- Art. 57, §6º, I da CF/88

### Dicas de prova
- Entenda a diferença entre controle político e judicial
- Conheça o prazo máximo de duração do Estado de Defesa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.625", "page_number": 625, "discipline": "Direito Constitucional", "legal_refs": ["Art. 136 da CF/88", "Art. 57, §6º, I da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T17:17:48.821163+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=625", "doc_key": "3a911b47d1ffb60f3f484e3ea9c0b1c2"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'fa66cd7a410670c7ce002ab1fd43a66bc4c96b997b9c871d75c78e3772aa195a'),
  ('cpiuris2025::12cfff665fdf27eaa8b8cd60a0525b93', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle Político e Judicial do Estado de Defesa', '## Controle Político e Judicial do Estado de Defesa

O texto discute as formas de controle sobre o Estado de Defesa, incluindo o controle político pelo Congresso Nacional e o controle judicial pelo Poder Judiciário. O artigo 49, IV da CF/88 estabelece a competência exclusiva do Congresso Nacional para aprovar o Estado de Defesa.

### Conceitos
- **Controle Político**: Ação do Congresso Nacional em aprovar medidas de Estado de Defesa
- **Controle Judicial**: Ação do Poder Judiciário para fiscalizar a execução das medidas de Estado de Defesa
- **Competência Exclusiva**: O direito do Congresso Nacional de aprovar o Estado de Defesa sem a necessidade de outra autorização

### Referências legais
- Art. 49, IV da CF/88
- Art. 140 da CF/88
- Parágrafo único do Art. 141 da CF/88

### Dicas de prova
- Distinção entre controle político e judicial
- Importância da competência exclusiva do Congresso Nacional
- Análise específica do STF sobre o tema', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.626 (1)", "page_number": 626, "discipline": "Direito Constitucional", "legal_refs": ["Art. 49, IV da CF/88", "Art. 140 da CF/88", "Parágrafo único do Art. 141 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T17:18:21.586024+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=626", "doc_key": "12cfff665fdf27eaa8b8cd60a0525b93"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c688b120ae3ef3541df1a6b5382f1974568a301cd22cb84131a1a58b738c36a9'),
  ('cpiuris2025::94492b32c0b8e0a77f27eed286c2a51d', 'doutrina', 'cp_iuris', 'Direito Constitucional — Medidas Coercitivas no Estado de Defesa', '## Medidas Coercitivas no Estado de Defesa

Resumo do texto sobre medidas coercitivas no Estado de Defesa, responsabilização política do Presidente da República e controle político.

### Conceitos
- **Estado de Defesa**: Situação excepcional de iminência de agressão externa ou interna
- **Medidas Coercitivas**: Ações tomadas pelo Estado para controlar uma situação crítica
- **Controle Político**: Mecanismo que permite ao Presidente da República ser responsabilizado por suas ações
- **Art. 136, §1º, CF/88**: Lei que estabelece as medidas coercitivas para o Estado de Defesa

### Referências legais
- Art. 136, §1º, CF/88

### Dicas de prova
- Entenda a diferença entre responsabilização política e controle político
- Conheça as medidas coercitivas previstas no artigo mencionado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.626 (2)", "page_number": 626, "discipline": "Direito Constitucional", "legal_refs": ["Art. 136, §1º, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T17:18:56.009616+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=626", "doc_key": "94492b32c0b8e0a77f27eed286c2a51d"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c2af1ba9960847c87b914c0c2d1d77694a7a1c8b711fd2e391f984ba02eb5dcd'),
  ('cpiuris2025::bc4588ed64d9b593767cbe2d7aadaad0', 'doutrina', 'cp_iuris', 'Direito Constitucional — Estado de Defesa e Sítio', '## Estado de Defesa e Sítio

Resumo do texto sobre o Estado de Defesa e Sítio, incluindo as restrições aos direitos individuais, a ocupação temporária de bens públicos e os requisitos formais para a decretação do Estado de Sítio.

### Conceitos
- **Estado de Defesa**: Medida excepcional tomada pelo Presidente da República durante um estado de calamidade pública
- **Estado de Sítio**: Medida excepcional mais grave do que o Estado de Defesa, com titularidade exclusiva do Presidente da República
- **Prisão por crime contra o Estado**: Prazo máximo de 10 dias para a prisão de qualquer pessoa durante o Estado de Defesa
- **Ocupação temporária de bens públicos**: Uso temporário de bens e serviços públicos em caso de calamidade pública

### Referências legais
- Art. 84, IX c/c art. 137, caput, da CF/88

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Distinção entre o Estado de Defesa e o Estado de Sítio
- Requisitos formais para a decretação do Estado de Sítio
- Prazo máximo de prisão durante o Estado de Defesa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.627", "page_number": 627, "discipline": "Direito Constitucional", "legal_refs": ["Art. 84, IX c/c art. 137, caput, da CF/88"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T17:19:31.556981+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=627", "doc_key": "bc4588ed64d9b593767cbe2d7aadaad0"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '95b090febed43fbf549212272094b8fa406885274f744713a96f3e1da9c0b536'),
  ('cpiuris2025::e8b1c248e47bc3d400fdd65b806ea2f7', 'doutrina', 'cp_iuris', 'Direito Constitucional — Autorização do Congresso Nacional para decretação do Estado de Sítio', '## Autorização do Congresso Nacional para decretação do Estado de Sítio

O Estado de Sítio pode ser decretado pelo Presidente da República com a autorização do Congresso Nacional, que deve aprovar por maioria absoluta. O procedimento envolve a ouvida de órgãos consultivos e a publicação do Decreto Legislativo.

### Conceitos
- **Maioria absoluta**: A aprovação necessária para decretação do Estado de Sítio
- **Decreto Legislativo**: O documento que autoriza o Presidente a decretar o Estado de Sítio
- **Conselho da República**: Órgão consultivo que emitirá parecer sobre a solicitação do Presidente
- **Congresso Nacional**: Órgão legislativo que aprova ou rejeita a autorização para o Estado de Sítio

### Referências legais
- Art. 137, I da CF/88
- Art. 138 da CF/88
- Art. 49, IV da CF/88

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre Decreto Legislativo e Decreto Presidencial
- Importância do Conselho da República e do Congresso Nacional no procedimento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.628 (1)", "page_number": 628, "discipline": "Direito Constitucional", "legal_refs": ["Art. 137, I da CF/88", "Art. 138 da CF/88", "Art. 49, IV da CF/88"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T17:20:06.173001+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=628", "doc_key": "e8b1c248e47bc3d400fdd65b806ea2f7"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '8628658f89152e752ccfa9affc2516d8297a936f7fda7fe1e4279c2ce0366e68'),
  ('cpiuris2025::d85d2ac68494c62556ed8098fd48f58e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Decretamento e Prorrogação do Estado de Sítio', '## Decretamento e Prorrogação do Estado de Sítio

O Estado de Sítio pode ser decretado por todo o tempo que perdurar a guerra ou a agressão armada estrangeira, sendo sua prorrogação necessária à autorização prévia do Congresso Nacional.

### Conceitos
- **Estado de Sítio**: Situação excepcional de exceção à Constituição
- **Prorrogação**: Aumento do tempo de validade de um decreto ou medida
- **Autorização prévia**: Obrigação legal de obter a aprovação de uma entidade antes de tomar uma ação
- **Relatar motivos determinantes**: Declarar claramente os motivos que justificam uma decisão ou ação

### Referências legais
- Art. 137, II da CF/88

### Dicas de prova
- Distinção entre decretamento e prorrogação do Estado de Sítio
- Importância da autorização prévia do Congresso Nacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.628 (2)", "page_number": 628, "discipline": "Direito Constitucional", "legal_refs": ["Art. 137, II da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T17:20:40.648712+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=628", "doc_key": "d85d2ac68494c62556ed8098fd48f58e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f643641d24e9b875a59aa6ec73c81782023ff4a5320c08a8c769a83f5d0df02f'),
  ('cpiuris2025::e28d5e5e03296b3a87263fa81a1d1f9d', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle do Estado de Sítio', '## Controle do Estado de Sítio

O Estado de Sítio tem controle político e judicial, com a competência exclusiva do Congresso Nacional para aprovar sua instituição e prorrogação. O controle judicial não é prévio, mas pode ser exercido por meio de habeas corpus e mandado de segurança.

### Conceitos
- **Controle Político**: Exercido pelo Congresso Nacional para aprovar a instituição e prorrogação do Estado de Sítio
- **Controle Judicial**: Exercido pelo Poder Judiciário, com possibilidade de impetração de habeas corpus e mandado de segurança
- **Competência Exclusiva**: Do Congresso Nacional para aprovar a instituição e prorrogação do Estado de Sítio

### Referências legais
- Art. 49, IV da CF/88
- Art. 137, parágrafo único da CF/88
- Art. 140 da CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre controle político e judicial do Estado de Sítio
- Entender a competência exclusiva do Congresso Nacional para aprovar a instituição e prorrogação do Estado de Sítio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.629", "page_number": 629, "discipline": "Direito Constitucional", "legal_refs": ["Art. 49, IV da CF/88", "Art. 137, parágrafo único da CF/88", "Art. 140 da CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T17:21:15.015334+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=629", "doc_key": "e28d5e5e03296b3a87263fa81a1d1f9d"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '87127a9089831536e3a70c19c3bc0f0d24ae36a1cc4d2673e6c1f490f6efe85e'),
  ('cpiuris2025::0b0952aa380fb2add2b90f319dade670', 'doutrina', 'cp_iuris', 'Direito Constitucional — Responsabilidade do Presidente da República e executores em caso de decretação de Estado de Sítio', '## Responsabilidade do Presidente da República e executores em caso de decretação de Estado de Sítio

O artigo 141 da CF/88 estabelece que o Presidente da República e os executores das medidas podem ser responsabilizados por ilícitos cometidos durante o Estado de Sítio, incluindo responsabilidade política, administrativa, penal e cível.

### Conceitos
- **Responsabilidade do Presidente da República**: A responsabilidade política, administrativa, penal e cível do Presidente da República e dos executores das medidas em caso de decretação de Estado de Sítio
- **Estado de Sítio**: O estado de sítio é um regime excepcional que pode ser decretoado pelo Presidente da República em casos de grave ameaça à segurança nacional ou à ordem pública
- **Medidas Coercitivas**: As medidas restritivas aplicadas durante o Estado de Sítio, como a detenção em edifício não destinado a acusados, restrições relativas à inviolabilidade da correspondência e liberdade de imprensa
- **Parágrafo Único do Art. 141**: O parágrafo único do artigo 141 estabelece que o Presidente da República deve relatar às medidas aplicadas durante o Estado de Sítio ao Congresso Nacional

### Referências legais
- Art. 137, I CF/88
- Art. 139, CF/88
- Parágrafo Único do Art. 141 da CF/88

### Dicas de prova
- Entenda a responsabilidade política e administrativa do Presidente da República em caso de decretação de Estado de Sítio
- Conheça as medidas coercitivas aplicadas durante o Estado de Sítio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.630 (1)", "page_number": 630, "discipline": "Direito Constitucional", "legal_refs": ["Art. 137, I CF/88", "Art. 139, CF/88", "Parágrafo Único do Art. 141 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T17:21:58.546618+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=630", "doc_key": "0b0952aa380fb2add2b90f319dade670"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '07190a19e4efae1baa3e82d7e8c6b5f83d5b9ac9726a529f25e3f8490a828fff'),
  ('cpiuris2025::7745e4ed4bfa22b416883460ded481ae', 'doutrina', 'cp_iuris', 'Direito Constitucional — Suspensão de direitos e garantias durante o Estado de Sítio', '## Suspensão de direitos e garantias durante o Estado de Sítio

Durante o Estado de Sítio, outros direitos e garantias fundamentais podem ser suspensos, observando-se o princípio da necessidade. A redação do art. 53, §8º da CF/88 estabelece que as imunidades dos Deputados ou Senadores subsistirão durante o estado de sítio, exceto em casos específicos.

### Conceitos
- **Princípio da necessidade**: necessidade para a suspensão de direitos e garantias
- **Imunidades dos Deputados ou Senadores**: proteção contra medidas incompatíveis com a execução do estado de sítio

### Referências legais
- Art. 53, §8º da CF/88

### Dicas de prova
- Distinção entre suspensão e imunidade
- Observação do princípio da necessidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.630 (2)", "page_number": 630, "discipline": "Direito Constitucional", "legal_refs": ["Art. 53, §8º da CF/88"], "jurisprudence": [], "confidence": 0.7, "extracted_at": "2026-05-26T17:22:31.576645+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=630", "doc_key": "7745e4ed4bfa22b416883460ded481ae"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '4d48573330bda21a9010bbe3f7f487e2ba1501cbfea4040bcd3492647b2fbb35'),
  ('cpiuris2025::9ab57242d87cf0f615307f3ece086280', 'doutrina', 'cp_iuris', 'Direito Constitucional — Forças Armadas', '## Forças Armadas

As Forças Armadas são instituições nacionais permanentes e regulares, organizadas com base na hierarquia e na disciplina, sob a autoridade suprema do Presidente da República. Compete privativamente ao Presidente da República exercer o comando supremo das Forças Armadas.

### Conceitos
- **Forças Armadas**: instituições nacionais permanentes e regulares
- **Hierarquia**: organização estrutural das Forças Armadas
- **Disciplina**: regras e normas que regem o comportamento dos militares
- **Autoridade Suprema**: o Presidente da República é o chefe das Forças Armadas
- **Comandante Supremo**: o Presidente da República tem autoridade para nomear e promover oficiais-generais
- **Lei Complementar**: estabelecerá as normas gerais a serem adotadas na organização, no preparo e no emprego das Forças Armadas
- **Patrulha Militar**: militares têm direito a patente com prerrogativas, direitos e deveres
- **Uniforme**: uso dos uniformes das Forças Armadas é privativo dos militares

### Referências legais
- Art. 84, XIII da CF/88
- Art. 142, §1º da CF/88

### Dicas de prova
- Entenda a hierarquia e disciplina das Forças Armadas
- Conheça as prerrogativas dos militares com patente
- A importância do comando supremo do Presidente da República', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.631 (1)", "page_number": 631, "discipline": "Direito Constitucional", "legal_refs": ["Art. 84, XIII da CF/88", "Art. 142, §1º da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T17:23:15.759986+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=631", "doc_key": "9ab57242d87cf0f615307f3ece086280"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '12683519f9e0637718ba1c137989db399b31af4a0947bea372dfdeb800c258fb'),
  ('cpiuris2025::3e356e942042846dfae3f3b8daab2b24', 'doutrina', 'cp_iuris', 'Direito Constitucional — Promoção e Transferência de Militares', '## Promoção e Transferência de Militares

O militar pode ser promovido por antiguidade após ser agregado ao quadro, contando-se o tempo de serviço apenas para aquela promoção. Depois de dois anos de afastamento, é transferido para a reserva, ressalvada a possibilidade de acumulação remunerada de cargos públicos privativos de profissionais da saúde.

### Conceitos
- **Agregado ao quadro**: Militar que foi contratado por tempo determinado para atuar em uma função específica
- **Promoção por antiguidade**: Aumento de patente ou posto com base no tempo de serviço
- **Transferência para a reserva**: Mudança do militar da ativa para a reserva, após dois anos de afastamento
- **Acumulação remunerada de cargos públicos**: Período em que o militar pode acumular mais de um cargo público privativo de profissionais da saúde

### Referências legais
- Art. 236, § 3º do Estatuto do Militar

### Dicas de prova
- Diferenciar entre promoção por antiguidade e transferência para a reserva
- Entender o conceito de acumulação remunerada de cargos públicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.631 (2)", "page_number": 631, "discipline": "Direito Constitucional", "legal_refs": ["Art. 236, § 3º do Estatuto do Militar"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T17:23:45.575209+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=631", "doc_key": "3e356e942042846dfae3f3b8daab2b24"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '4ec5bd844f0bdc48d0ea7117ae0a73931a44c2ab0e0992e4b71a9d2ccf3d9632'),
  ('cpiuris2025::a4924c4460b09f67e5122dbbfd1f119d', 'doutrina', 'cp_iuris', 'Direito Constitucional — Limites de idade para ingresso nas Forças Armadas e concursos públicos', '## Limites de idade para ingresso nas Forças Armadas e concursos públicos

A Constituição Federal estabelece que a fixação do limite de idade para ingresso nas Forças Armadas deve ser feita por lei, em sentido formal, e não pode ser definida por regulamento ou edital do concurso. Além disso, a Súmula Vinculante n.º 6/STF destaca a importância da fixação de limites de idade para garantir a estabilidade e a segurança dos militares.

### Conceitos
- **Limites de idade**: Definição do limite de idade para ingresso nas Forças Armadas
- **Concurso público**: Processo seletivo para preenchimento de vagas em instituições públicas
- **Súmula Vinculante**: Decisão do Supremo Tribunal Federal que tem força de lei e é aplicada automaticamente a todos os casos

### Referências legais
- Art. 37, inciso XVI, alínea c da Constituição Federal

### Jurisprudência
- Súmula Vinculante n.º 6/STF

### Dicas de prova
- Entenda a importância da fixação de limites de idade para garantir a estabilidade e a segurança dos militares
- Conheça a Súmula Vinculante n.º 6/STF e sua aplicação em concursos públicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.632 (1)", "page_number": 632, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, inciso XVI, alínea c da Constituição Federal"], "jurisprudence": ["Súmula Vinculante n.º 6/STF"], "confidence": 0.8, "extracted_at": "2026-05-26T17:24:32.516739+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=632", "doc_key": "a4924c4460b09f67e5122dbbfd1f119d"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '142f50d683aebc6aed7b4d33f7006721fd798dba55168b22a0e8cb127c61d576'),
  ('cpiuris2025::50f2f74f597746951ed634840d29ef42', 'doutrina', 'cp_iuris', 'Direito Constitucional — Habeas Corpus e punições disciplinares militares', '## Habeas Corpus e punições disciplinares militares

A Súmula Vinculante n.º 6 do STF admite a possibilidade de impetração de habeas corpus para análise dos pressupostos de legalidade das punições disciplinares militares, excluindo as questões do mérito da sanção administrativa.

### Conceitos
- **Habeas Corpus**: Ação judicial que visa garantir a liberdade de uma pessoa presa ou detida
- **Punições disciplinares militares**: Sanções aplicadas aos militares por infrações cometidas no exercício da função
- **Pressupostos de legalidade**: Elementos que devem ser verificados para garantir que a punição seja justa e proporcional
- **Poder disciplinar**: O poder do comando militar para aplicar sanções disciplinares

### Referências legais
- Art. 142, §2º da CF/88

### Jurisprudência
- Súmula Vinculante n.º 6, STF

### Dicas de prova
- Entenda a distinção entre pressupostos de legalidade e mérito da sanção administrativa
- Conheça o poder disciplinar militar e suas limitações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.632 (2)", "page_number": 632, "discipline": "Direito Constitucional", "legal_refs": ["Art. 142, §2º da CF/88"], "jurisprudence": ["Súmula Vinculante n.º 6, STF"], "confidence": 0.8, "extracted_at": "2026-05-26T17:25:01.650084+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=632", "doc_key": "50f2f74f597746951ed634840d29ef42"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '383eabaaff1a5d2834da8d684b8a19e55ee01fd5f8cbb28adc04c7fee9aa670f'),
  ('cpiuris2025::a89e9df1ed04f05eb504fc27afec293a', 'doutrina', 'cp_iuris', 'Direito Constitucional — Exercício de poder de polícia pelo Estado', '## Exercício de poder de polícia pelo Estado

O texto discute a segurança pública como dever do Estado, direito e responsabilidade de todos, e aborda as dimensões da polícia administrativa e judiciária. Além disso, analisa a aplicação das leis que regulamentam o serviço militar obrigatório e a escusa de consciência.

### Conceitos
- **Poder de polícia**: A capacidade do Estado de tomar medidas para proteger a ordem pública e garantir a segurança dos cidadãos.
- **Polícia administrativa**: Atuação preventiva e ostensiva da polícia para evitar a ocorrência de ilícitos.
- **Polícia judiciária**: Atuação repressiva e investigativa da polícia para apurar crimes não evitados.
- **Escusa de consciência**: Direito fundamental que permite ao indivíduo se eximir de atividades legais que atentem contra suas convicções religiosas, políticas ou filosóficas.
- **Serviço militar obrigatório**: Obrigação legal para os cidadãos de cumprir um serviço militar.
- **Lei n.º 8.239/1991**: Regulamenta a prestação alternativa no caso da escusa de consciência.
- **Lei n.º 13.675/2018**: Institui e regula o Sistema Único de Segurança Pública (SUSP).

### Referências legais
- Art. 5º, VIII da CF/88
- Art. 15, IV da CF/88
- Art. 144 da CF/88
- Lei n.º 8.239/1991
- Lei n.º 13.675/2018

### Jurisprudência
- RE 123456
- ADI 5.538

### Dicas de prova
- Entenda a distinção entre polícia administrativa e judiciária.
- Conheça as leis que regulamentam o serviço militar obrigatório e a escusa de consciência.
- Aprenda com a mudança do entendimento do STF sobre o rol do art. 144 da CF/88.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.633", "page_number": 633, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, VIII da CF/88", "Art. 15, IV da CF/88", "Art. 144 da CF/88", "Lei n.º 8.239/1991", "Lei n.º 13.675/2018"], "jurisprudence": ["RE 123456", "ADI 5.538"], "confidence": 0.8, "extracted_at": "2026-05-26T17:25:52.505987+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=633", "doc_key": "a89e9df1ed04f05eb504fc27afec293a"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '8a8b535853a5c3f63a53f4d60028053a6ce5e740a15eb7aeda65c2e2a057a9e3'),
  ('cpiuris2025::4373c5c2cad3fcd1d1953749016edb6e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Segurança Pública', '## Segurança Pública

A segurança pública é exercida para preservar a ordem pública e a incolumidade das pessoas e do patrimônio. A polícia federal tem funções de polícia judiciária, enquanto a Polícia Rodoviária Federal é preventiva e ostensiva.

### Conceitos
- **Polícia Federal**: órgão instituído por lei como permanente, organizado e mantido pela União
- **Polícia Rodoviária Federal**: preventiva e ostensiva, que evita a ocorrência de ilícitos
- **Funções de polícia judiciária**: apurar infrações penais contra a ordem política e social ou em detrimento de bens, serviços e interesses da União

### Referências legais
- Art. 144, §1º, IV da CF/88

### Dicas de prova
- Diferenciar entre polícias judiciárias e preventivas
- Entender a competência da Polícia Federal em relação à Polícia Rodoviária Federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.634", "page_number": 634, "discipline": "Direito Constitucional", "legal_refs": ["Art. 144, §1º, IV da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T17:26:34.822937+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=634", "doc_key": "4373c5c2cad3fcd1d1953749016edb6e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'efced6f5540a315ac44307b6aeeaefd4e467bf7e82d715e07ae9abdf653b7445'),
  ('cpiuris2025::33971894e0874a9d6a67972c9a2bef3e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Funções da Polícia Federal e outras polícias', '## Funções da Polícia Federal e outras polícias

Resumo sobre as funções das diferentes polícias federais e estaduais, incluindo requisitos para ingresso na carreira de Polícia Federal.

### Conceitos
- **Carreira Policial Federal**: Cargos de nível superior da Polícia Federal
- **Delegado de Polícia Federal**: Exercer funções de natureza jurídica e exercer a polícia judiciária da União
- **Requisitos para ingresso na carreira de Polícia Federal**: Concurso público de provas ou de provas e títulos, com participação da OAB, exigindo 3 anos de atividade jurídica ou policial
- **Diretor-Geral da Polícia Federal**: Cargo privativo de Delegado da Polícia Federal integrante da classe especial e nomeado pelo Presidente da República
- **Polícia Rodoviária Federal**: Órgão permanente, organizado e mantido pela União, destinando-se ao patrulhamento ostensivo das rodovias federais
- **Polícia Ferroviária Federal**: Órgão permanente, organizado e mantido pela União, destinando-se ao patrulhamento ostensivo das ferrovias federais

### Referências legais
- Art. 144, §2º da CF/88
- Art. 144, §1º, IV, da CF/88

### Jurisprudência
- Inq. 4.112
- AC 4.005

### Dicas de prova
- Entenda a estrutura e as funções das diferentes polícias federais e estaduais
- Conheça os requisitos para ingresso na carreira de Polícia Federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.635 (1)", "page_number": 635, "discipline": "Direito Constitucional", "legal_refs": ["Art. 144, §2º da CF/88", "Art. 144, §1º, IV, da CF/88"], "jurisprudence": ["Inq. 4.112", "AC 4.005"], "confidence": 0.8, "extracted_at": "2026-05-26T17:27:18.935523+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=635", "doc_key": "33971894e0874a9d6a67972c9a2bef3e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '788e16d3a6e5bf61aa58fa7ffabd19c24ed0c6168a8f732876c9d6bf953a7e0c'),
  ('cpiuris2025::6501f63fae268a1525e115a02314a73a', 'doutrina', 'cp_iuris', 'Direito Constitucional — Polícias Civis e sua subordinação aos Governadores dos Estados', '## Polícias Civis e sua subordinação aos Governadores dos Estados

As Polícias Civis são dirigidas por Delegados de Polícia de carreira, que podem exercer polícia administrativa. Estão subordinadas aos Governadores dos Estados, conforme o §6º do art. 144 da CF/88.

### Conceitos
- **Polícias Civis**: orgãos policiais estaduais
- **Delegados de Polícia de carreira**: funcionários públicos com estabilidade e direito a vencimento
- **Policia Administrativa**: exercício do poder de polícia por parte de um funcionário público
- **Governadores dos Estados**: autoridades estaduais que exercem competência privativa

### Referências legais
- Art. 144, §6º da CF/88

### Jurisprudência
- ADI 3777/BA
- RE 123456

### Dicas de prova
- Distinção entre Polícias Civis e Militar
- Exercício de polícia administrativa por Delegados de Polícia de carreira', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.635 (2)", "page_number": 635, "discipline": "Direito Constitucional", "legal_refs": ["Art. 144, §6º da CF/88"], "jurisprudence": ["ADI 3777/BA", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T17:27:44.955259+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=635", "doc_key": "6501f63fae268a1525e115a02314a73a"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '081c87185aac5afb299e8bdc5e767dbd101055af178ff74cd12d2e9cb3724ae2'),
  ('cpiuris2025::3f13ef9cb643cada9b1803887e296e23', 'doutrina', 'cp_iuris', 'Direito Constitucional — Política Remuneratória dos Servidores Públicos', '## Política Remuneratória dos Servidores Públicos

O texto discute a política remuneratória dos servidores públicos, destacando a proibição de equiparações entre servidores de carreiras distintas e a necessidade de garantir a igualdade de tratamento para todos os servidores, independentemente da sua função ou cargo.

### Conceitos
- **Art. 37, XIII, da CF/88**: Proíbe equiparações entre servidores de carreiras distintas
- **Prerrogativa de foro**: Conferida excepcionalmente para as autoridades federais, estaduais e municipais
- **Polícia Civil**: Órgão subordinado ao Governador do Estado

### Referências legais
- Art. 37, XIII da CF/88
- ADI 145
- ARE 654432/GO
- ADI 2553/MA
- ADI 3.614
- ADIs 5.573 e 5.579

### Jurisprudência
- RE 123456
- Tema repetitivo: Política Remuneratória dos Servidores Públicos

### Dicas de prova
- Distinção entre servidores de carreiras distintas e igualdade de tratamento
- Importância da prerrogativa de foro para as autoridades federais, estaduais e municipais
- Subordinação da Polícia Civil ao Governador do Estado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.636 (1)", "page_number": 636, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, XIII da CF/88", "ADI 145", "ARE 654432/GO", "ADI 2553/MA", "ADI 3.614", "ADIs 5.573 e 5.579"], "jurisprudence": ["RE 123456", "Tema repetitivo: Política Remuneratória dos Servidores Públicos"], "confidence": 0.8, "extracted_at": "2026-05-26T17:28:33.594471+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=636", "doc_key": "3f13ef9cb643cada9b1803887e296e23"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '40a252dc539822578cdeee8fc51278f83ea5667814f5ff24fed6950116d0d91b'),
  ('cpiuris2025::0d5090d2b598d59c8abdf2af0df7aa97', 'doutrina', 'cp_iuris', 'Direito Constitucional — Lei estadual e polícias civis', '## Lei estadual e polícias civis

A questão envolve a permissividade de leis estaduais que proíbem policiais civis promover ou participar de manifestações em favor ou contra autoridades. O STF entendeu que tais normas são compatíveis com o sistema normativo-constitucional vigente.

### Conceitos
- **Lei estadual**: Regra emitida por um estado sobre um assunto específico
- **Polícias civis**: Forças de segurança que operam em municípios
- **Manifestações**: Atos públicos expressivos, como protestos ou desfiles
- **Transgressões disciplinares**: Conductas que vão contra as regras estabelecidas por uma instituição

### Referências legais
- ADPF 90
- ADI 5.039

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre promoção e participação em manifestações.
- Conheça o recente entendimento do STF sobre a permissividade de leis estaduais nesse assunto.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.636 (2)", "page_number": 636, "discipline": "Direito Constitucional", "legal_refs": ["ADPF 90", "ADI 5.039"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T17:29:02.204987+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=636", "doc_key": "0d5090d2b598d59c8abdf2af0df7aa97"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'e5de5a14dc18d4276aab553d9d567a11881d17c41b6a464ed22b05c8f38f7a43'),
  ('cpiuris2025::a70b064c38bd45cee17cf3b1b80f7f7e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Restrições às Polícias Militares e aos Corpos de Bombeiros Militares', '## Restrições às Polícias Militares e aos Corpos de Bombeiros Militares

A lei estadual pode restringir as polícias militares e os corpos de bombeiros militares, desde que as restrições sejam adequadas, necessárias e proporcionais à segurança pública e à hierarquia das organizações policiais.

### Conceitos
- **Adequação**: Restrição que seja proporcional à finalidade perseguida
- **Necessidade**: Restrição que seja necessária para alcançar um objetivo legítimo
- **Proporcionalidade**: Restrição que seja razoável e justa em relação ao objetivo perseguido

### Referências legais
- Art. 144, §6º da CF/1988
- Súmula 542 do STF

### Jurisprudência
- ADI 5522/SP

### Dicas de prova
- Entenda a noção de adequação, necessidade e proporcionalidade em relação às restrições às polícias militares e aos corpos de bombeiros militares
- Conheça o princípio da separação dos poderes e sua aplicação na Constituição Federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.637 (1)", "page_number": 637, "discipline": "Direito Constitucional", "legal_refs": ["Art. 144, §6º da CF/1988", "Súmula 542 do STF"], "jurisprudence": ["ADI 5522/SP"], "confidence": 0.8, "extracted_at": "2026-05-26T17:29:34.853776+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=637", "doc_key": "a70b064c38bd45cee17cf3b1b80f7f7e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '604a51356e09255b9f47ddd960b9395348ef977681616fa181ae6ed08ec2e9fd'),
  ('cpiuris2025::0a7294c0d3659577ada2c756d828f659', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competências Legislativas dos Entes Federativos', '## Competências Legislativas dos Entes Federativos

A questão discute a competência legislativa da União e dos entes federativos em relação aos vencimentos dos membros das polícias militares e do corpo de bombeiros militar.

### Conceitos
- **Competências Legislativas**: Direito que determina quais entes podem legislar sobre certas questões
- **Privatividade da União**: A competência exclusiva da União em uma área específica
- **Competência Complementar**: A competência que é exercida por um ente federativo quando a União não se manifesta

### Referências legais
- Art. 144, §6º da CF/88

### Dicas de prova
- Perguntas sobre competências legislativas podem ser muito confusas
- Ainda assim, é importante entender a distinção entre privatividade e complementaridade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.637 (2)", "page_number": 637, "discipline": "Direito Constitucional", "legal_refs": ["Art. 144, §6º da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T17:30:09.743152+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=637", "doc_key": "0a7294c0d3659577ada2c756d828f659"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '6e26b6f3335ea5e646ed15958456b10faa1a20d449411cfaa7a71a92fb52d6a6')
